class _DependenciaOpcionalAusente:
    """Marcador tardio que permite carregar os motores independentes."""

    def __init__(self, pacote):
        self.pacote = pacote

    def __getattr__(self, nome):
        if nome in {
            "ndarray", "DataFrame", "Interval", "Union", "FiniteSet",
            "Tuple", "MatrixBase", "Equality",
        }:
            return _TipoOpcionalAusente
        if nome == "symbols":
            def criar_simbolos(nomes, **kwargs):
                quantidade = len(str(nomes).replace(",", " ").split())
                return tuple(
                    _DependenciaOpcionalAusente(self.pacote)
                    for _ in range(quantidade)
                )
            return criar_simbolos
        return self

    def __call__(self, *args, **kwargs):
        return self

    def __iter__(self):
        return iter(())

    def __bool__(self):
        return False

    def __getitem__(self, chave):
        return self

    def _operacao(self, *args, **kwargs):
        return self

    __add__ = __radd__ = __sub__ = __rsub__ = _operacao
    __mul__ = __rmul__ = __truediv__ = __rtruediv__ = _operacao
    __pow__ = __rpow__ = __matmul__ = __rmatmul__ = _operacao
    __neg__ = __pos__ = _operacao

    def __repr__(self):
        return f"<dependência opcional ausente: {self.pacote}>"


