class ParserEstatisticaAvancadaPSF:
    """Leitura de matrizes, vetores, textos e expressões estatísticas."""

    theta = sp.Symbol("theta", real=True)

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @classmethod
    def matriz(cls, texto):
        dados = cls.literal(texto, "matriz")

        try:
            matriz = np.asarray(dados, dtype=float)
        except (TypeError, ValueError) as erro:
            raise ValueError("A matriz deve conter apenas números.") from erro

        if matriz.ndim != 2 or matriz.shape[0] == 0 or matriz.shape[1] == 0:
            raise ValueError("A matriz deve ser bidimensional e não vazia.")
        if not np.isfinite(matriz).all():
            raise ValueError("A matriz contém valor não finito.")

        return matriz

    @classmethod
    def vetor(cls, texto):
        dados = cls.literal(texto, "vetor")

        try:
            vetor = np.asarray(dados)
        except Exception as erro:
            raise ValueError("Vetor inválido.") from erro

        if vetor.ndim != 1 or len(vetor) == 0:
            raise ValueError("O vetor deve ser unidimensional e não vazio.")

        return vetor

    @classmethod
    def ponto(cls, texto, dimensao):
        vetor = cls.vetor(texto)

        try:
            vetor = vetor.astype(float)
        except (TypeError, ValueError) as erro:
            raise ValueError("O ponto deve ser numérico.") from erro

        if len(vetor) != dimensao:
            raise ValueError(
                f"O ponto deve possuir {dimensao} componentes."
            )

        return vetor.reshape(1, -1)

    @classmethod
    def log_posterior(cls, texto):
        expressao = texto.strip().replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            raise ValueError("Expressão de log-posterior não permitida.")

        locais = {
            "theta": cls.theta,
            "sin": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "abs": sp.Abs,
            "pi": sp.pi,
            "e": sp.E,
        }

        try:
            expr = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            raise ValueError("Log-posterior inválido.") from erro

        if expr.free_symbols - {cls.theta}:
            raise ValueError("A expressão só pode depender de theta.")

        return expr


class MotorPCAAvancadoPSF:
    """Análise de componentes principais com reconstrução."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"pca\s+(.+?)\s*;\s*(\d+)"
            r"(?:\s*;\s*(padronizar|centrar))?",
            texto,
        )

        if not padrao:
            return None

        try:
            x = ParserEstatisticaAvancadaPSF.matriz(padrao.group(1))
        except ValueError as erro:
            return {"erro": str(erro)}

        componentes = int(padrao.group(2))
        modo = padrao.group(3) or "centrar"
        limite = min(x.shape)

        if componentes < 1 or componentes > limite:
            return {
                "erro": (
                    f"O número de componentes deve estar entre 1 e {limite}."
                )
            }

        media = np.mean(x, axis=0)

        if modo == "padronizar":
            escala = np.std(x, axis=0, ddof=0)

            if np.any(escala == 0):
                return {
                    "erro": (
                        "Não é possível padronizar uma coluna com desvio zero."
                    )
                }

            x_preparado = (x-media)/escala
        else:
            escala = np.ones(x.shape[1])
            x_preparado = x-media

        modelo = SklearnPCA(n_components=componentes)
        transformado = modelo.fit_transform(x_preparado)
        reconstruido_preparado = modelo.inverse_transform(transformado)
        reconstruido = reconstruido_preparado*escala+media
        erro_reconstrucao = float(
            np.sqrt(np.mean((x-reconstruido)**2))
        )
        covariancia = np.cov(x_preparado, rowvar=False)
        total_variancia = float(np.sum(modelo.explained_variance_ratio_))

        return {
            "tipo": "análise de componentes principais",
            "dados": {
                "observações": int(x.shape[0]),
                "variáveis": int(x.shape[1]),
                "componentes_pedidos": componentes,
                "pré_processamento": modo,
            },
            "pedido": "Reduzir a dimensão preservando a maior variância possível",
            "formula": (
                "centralizar X; diagonalizar a covariância; "
                "projetar nos autovetores principais"
            ),
            "passos": [
                f"Média de cada variável: {media.tolist()}.",
                f"Escala aplicada: {escala.tolist()}.",
                f"Matriz de covariância: {np.asarray(covariancia).tolist()}.",
                (
                    "Autovetores/componentes ordenados por variância: "
                    f"{modelo.components_.tolist()}."
                ),
                (
                    "Variâncias explicadas: "
                    f"{modelo.explained_variance_.tolist()}."
                ),
                (
                    "Proporções explicadas: "
                    f"{modelo.explained_variance_ratio_.tolist()}."
                ),
                f"Dados projetados: {transformado.tolist()}.",
            ],
            "resultado": {
                "componentes": modelo.components_.tolist(),
                "dados_transformados": transformado.tolist(),
                "variancia_explicada_total": total_variancia,
                "erro_reconstrucao_rmse": erro_reconstrucao,
                "reconstrucao": reconstruido.tolist(),
            },
            "verificacao": {
                "componentes_ortonormais": bool(
                    np.allclose(
                        modelo.components_ @ modelo.components_.T,
                        np.eye(componentes),
                        atol=1e-8,
                    )
                ),
                "proporcao_entre_zero_um": bool(
                    0 <= total_variancia <= 1+1e-10
                ),
            },
        }


class MotorAgrupamentosPSF:
    """K-means e agrupamento hierárquico aglomerativo."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        kmeans = re.fullmatch(
            r"kmeans\s+(.+?)\s*;\s*(\d+)"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if kmeans:
            try:
                x = ParserEstatisticaAvancadaPSF.matriz(kmeans.group(1))
            except ValueError as erro:
                return {"erro": str(erro)}

            k = int(kmeans.group(2))
            semente = int(kmeans.group(3) or 0)

            if k < 1 or k > len(x):
                return {"erro": "k deve estar entre 1 e o número de observações."}

            modelo = SklearnKMeans(
                n_clusters=k,
                random_state=semente,
                n_init=10,
            )
            rotulos = modelo.fit_predict(x)
            distancias = np.linalg.norm(
                x-modelo.cluster_centers_[rotulos],
                axis=1,
            )

            grupos = {
                int(grupo): np.where(rotulos == grupo)[0].tolist()
                for grupo in range(k)
            }

            return {
                "tipo": "agrupamento K-means",
                "dados": {
                    "observações": len(x),
                    "variáveis": x.shape[1],
                    "k": k,
                    "semente": semente,
                },
                "pedido": "Minimizar a soma das distâncias quadráticas aos centróides",
                "formula": "min Σ_i ||x_i−μ_{c_i}||²",
                "passos": [
                    "Inicializamos centróides com a estratégia k-means++.",
                    "Atribuímos cada observação ao centróide mais próximo.",
                    "Recalculamos cada centróide pela média do grupo.",
                    "Repetimos até as atribuições estabilizarem.",
                    f"Centróides finais: {modelo.cluster_centers_.tolist()}.",
                    f"Grupos por índice: {grupos}.",
                ],
                "resultado": {
                    "rótulos": rotulos.tolist(),
                    "centróides": modelo.cluster_centers_.tolist(),
                    "inércia": float(modelo.inertia_),
                    "iterações": int(modelo.n_iter_),
                    "distâncias_aos_centróides": distancias.tolist(),
                },
                "verificacao": {
                    "todos_atribuídos": len(rotulos) == len(x),
                    "inércia_não_negativa": float(modelo.inertia_) >= 0,
                },
            }

        hierarquico = re.fullmatch(
            r"agrupamento\s+hierarquico\s+(.+?)\s*;\s*(\d+)"
            r"(?:\s*;\s*(ward|complete|average|single))?",
            texto,
        )

        if not hierarquico:
            return None

        try:
            x = ParserEstatisticaAvancadaPSF.matriz(hierarquico.group(1))
        except ValueError as erro:
            return {"erro": str(erro)}

        k = int(hierarquico.group(2))
        ligacao = hierarquico.group(3) or "ward"

        if k < 1 or k > len(x):
            return {"erro": "k deve estar entre 1 e o número de observações."}

        modelo = AgglomerativeClustering(
            n_clusters=k,
            linkage=ligacao,
            compute_distances=True,
        )
        rotulos = modelo.fit_predict(x)
        fusoes = []

        for indice, filhos in enumerate(modelo.children_):
            fusoes.append({
                "passo": indice+1,
                "grupos_fundidos": [int(filhos[0]), int(filhos[1])],
                "distância": (
                    float(modelo.distances_[indice])
                    if hasattr(modelo, "distances_")
                    else None
                ),
            })

        return {
            "tipo": "agrupamento hierárquico",
            "dados": {
                "observações": len(x),
                "grupos_finais": k,
                "ligação": ligacao,
            },
            "pedido": "Construir a hierarquia de fusões e cortar em k grupos",
            "formula": (
                "fundir repetidamente os grupos com menor distância "
                "segundo o critério escolhido"
            ),
            "passos": [
                f"Fusões sucessivas: {fusoes}.",
                f"Corte final em {k} grupos.",
            ],
            "resultado": {
                "rótulos": rotulos.tolist(),
                "fusões": fusoes,
            },
            "verificacao": {
                "quantidade_grupos": len(set(rotulos.tolist())),
                "esperado": k,
            },
        }


class FerramentasClassificacaoPSF:
    """Preparação e apresentação uniforme de classificadores."""

    @staticmethod
    def dados(treino_texto, alvo_texto, ponto_texto):
        x = ParserEstatisticaAvancadaPSF.matriz(treino_texto)
        y = ParserEstatisticaAvancadaPSF.vetor(alvo_texto)

        if len(y) != len(x):
            raise ValueError("X e y devem ter o mesmo número de observações.")
        if len(set(y.tolist())) < 2:
            raise ValueError("São necessárias pelo menos duas classes.")

        ponto = ParserEstatisticaAvancadaPSF.ponto(
            ponto_texto,
            x.shape[1],
        )
        return x, y, ponto

    @staticmethod
    def resumo(modelo, x, y, ponto, probabilidades=True):
        previsto_treino = modelo.predict(x)
        previsto = modelo.predict(ponto)
        resultado = {
            "classe_prevista": previsto[0].item()
            if hasattr(previsto[0], "item")
            else previsto[0],
            "acurácia_treino": float(
                accuracy_score(y, previsto_treino)
            ),
            "matriz_confusão_treino": confusion_matrix(
                y,
                previsto_treino,
            ).tolist(),
            "classes": [
                valor.item() if hasattr(valor, "item") else valor
                for valor in modelo.classes_
            ],
        }

        if probabilidades and hasattr(modelo, "predict_proba"):
            resultado["probabilidades"] = (
                modelo.predict_proba(ponto)[0].tolist()
            )

        return resultado


class MotorAnaliseDiscriminantePSF:
    """Análise discriminante linear."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"analise\s+discriminante\s+(.+?)\s*;\s*"
            r"(.+?)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            x, y, ponto = FerramentasClassificacaoPSF.dados(
                padrao.group(1),
                padrao.group(2),
                padrao.group(3),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        modelo = LinearDiscriminantAnalysis(
            solver="svd",
            store_covariance=True,
        )

        try:
            modelo.fit(x, y)
        except Exception as erro:
            return {"erro": f"Não foi possível ajustar a LDA: {erro}"}

        resumo = FerramentasClassificacaoPSF.resumo(
            modelo, x, y, ponto
        )
        medias = {
            str(classe): media.tolist()
            for classe, media in zip(modelo.classes_, modelo.means_)
        }

        return {
            "tipo": "análise discriminante linear",
            "dados": {
                "observações": len(x),
                "variáveis": x.shape[1],
                "classes": resumo["classes"],
                "ponto": ponto[0].tolist(),
            },
            "pedido": "Classificar o ponto por funções discriminantes lineares",
            "formula": (
                "δ_k(x)=xᵀΣ⁻¹μ_k−½μ_kᵀΣ⁻¹μ_k+log π_k"
            ),
            "passos": [
                f"Médias de classe: {medias}.",
                f"Prioris estimadas: {modelo.priors_.tolist()}.",
                f"Covariância comum: {modelo.covariance_.tolist()}.",
                (
                    "Calculamos os escores discriminantes e selecionamos "
                    "a classe de maior valor."
                ),
            ],
            "resultado": resumo,
            "verificacao": (
                "A matriz de confusão mostra o comportamento no conjunto fornecido."
            ),
        }


class MotorRegressaoLogisticaPSF:
    """Regressão logística para classificação."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"regressao\s+logistica\s+(.+?)\s*;\s*"
            r"(.+?)\s*;\s*(.+?)(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            x, y, ponto = FerramentasClassificacaoPSF.dados(
                padrao.group(1),
                padrao.group(2),
                padrao.group(3),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        semente = int(padrao.group(4) or 0)
        escalador = StandardScaler()
        x_e = escalador.fit_transform(x)
        ponto_e = escalador.transform(ponto)
        modelo = LogisticRegression(
            max_iter=5000,
            random_state=semente,
        )

        try:
            modelo.fit(x_e, y)
        except Exception as erro:
            return {"erro": f"Não foi possível ajustar a regressão: {erro}"}

        resumo = FerramentasClassificacaoPSF.resumo(
            modelo, x_e, y, ponto_e
        )

        return {
            "tipo": "regressão logística",
            "dados": {
                "observações": len(x),
                "variáveis": x.shape[1],
                "ponto": ponto[0].tolist(),
            },
            "pedido": "Estimar probabilidades de classe e classificar",
            "formula": "P(Y=1|x)=1/(1+e^{−(β₀+βᵀx)})",
            "passos": [
                f"Média de padronização: {escalador.mean_.tolist()}.",
                f"Escala: {escalador.scale_.tolist()}.",
                f"Interceptos: {modelo.intercept_.tolist()}.",
                f"Coeficientes: {modelo.coef_.tolist()}.",
                (
                    "Aplicamos a função logística/softmax aos escores "
                    "e escolhemos a maior probabilidade."
                ),
            ],
            "resultado": resumo,
            "verificacao": {
                "iterações": modelo.n_iter_.tolist(),
                "convergiu_no_limite": bool(
                    np.all(modelo.n_iter_ < modelo.max_iter)
                ),
            },
        }


class MotorSVMPSF:
    """Máquinas de vetores de suporte."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"svm\s+(.+?)\s*;\s*(.+?)\s*;\s*(.+?)"
            r"(?:\s*;\s*(linear|rbf|poly|sigmoid))?"
            r"(?:\s*;\s*([0-9.eE+-]+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            x, y, ponto = FerramentasClassificacaoPSF.dados(
                padrao.group(1),
                padrao.group(2),
                padrao.group(3),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        kernel = padrao.group(4) or "linear"
        c = float(padrao.group(5) or 1.0)

        if c <= 0:
            return {"erro": "C deve ser positivo."}

        escalador = StandardScaler()
        x_e = escalador.fit_transform(x)
        ponto_e = escalador.transform(ponto)
        modelo = SVC(
            kernel=kernel,
            C=c,
            probability=True,
            random_state=0,
        )

        try:
            modelo.fit(x_e, y)
        except Exception as erro:
            return {"erro": f"Não foi possível ajustar a SVM: {erro}"}

        resumo = FerramentasClassificacaoPSF.resumo(
            modelo, x_e, y, ponto_e
        )
        resumo["vetores_suporte"] = modelo.support_vectors_.tolist()
        resumo["índices_suporte"] = modelo.support_.tolist()
        resumo["quantidade_por_classe"] = modelo.n_support_.tolist()
        resumo["decisão_ponto"] = modelo.decision_function(ponto_e).tolist()

        return {
            "tipo": "máquina de vetores de suporte",
            "dados": {
                "kernel": kernel,
                "C": c,
                "ponto": ponto[0].tolist(),
            },
            "pedido": "Construir a margem e classificar o ponto",
            "formula": (
                "min ½||w||²+CΣξ_i, sujeito a "
                "y_i(w·φ(x_i)+b)≥1−ξ_i"
            ),
            "passos": [
                "Padronizamos as variáveis.",
                "Otimizamos a margem com penalização C.",
                (
                    f"Vetores de suporte encontrados: "
                    f"{modelo.support_.tolist()}."
                ),
                (
                    f"Valor da função de decisão no ponto: "
                    f"{modelo.decision_function(ponto_e).tolist()}."
                ),
            ],
            "resultado": resumo,
            "verificacao": (
                "Os vetores de suporte são as observações que definem a fronteira."
            ),
        }


class MotorArvoresFlorestasPSF:
    """Árvore de decisão e floresta aleatória."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        arvore = re.fullmatch(
            r"arvore\s+decisao\s+(.+?)\s*;\s*(.+?)\s*;\s*(.+?)"
            r"(?:\s*;\s*(\d+|none))?"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if arvore:
            try:
                x, y, ponto = FerramentasClassificacaoPSF.dados(
                    arvore.group(1),
                    arvore.group(2),
                    arvore.group(3),
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            profundidade = (
                None
                if (arvore.group(4) or "none") == "none"
                else int(arvore.group(4))
            )
            semente = int(arvore.group(5) or 0)
            modelo = DecisionTreeClassifier(
                max_depth=profundidade,
                random_state=semente,
            )
            modelo.fit(x, y)
            resumo = FerramentasClassificacaoPSF.resumo(
                modelo, x, y, ponto
            )
            regras = export_text(modelo)

            return {
                "tipo": "árvore de decisão",
                "dados": {
                    "profundidade_máxima": profundidade,
                    "ponto": ponto[0].tolist(),
                },
                "pedido": "Construir regras de decisão e classificar",
                "formula": (
                    "selecionar divisões que maximizem a redução de impureza"
                ),
                "passos": [
                    (
                        f"Importâncias das variáveis: "
                        f"{modelo.feature_importances_.tolist()}."
                    ),
                    f"Regras aprendidas:\n{regras}",
                    (
                        "Percorremos a árvore segundo as comparações do ponto."
                    ),
                ],
                "resultado": {
                    **resumo,
                    "profundidade": int(modelo.get_depth()),
                    "folhas": int(modelo.get_n_leaves()),
                    "regras": regras,
                },
                "verificacao": {
                    "acurácia_treino": resumo["acurácia_treino"],
                },
            }

        floresta = re.fullmatch(
            r"floresta\s+aleatoria\s+(.+?)\s*;\s*(.+?)\s*;\s*(.+?)"
            r"(?:\s*;\s*(\d+))?"
            r"(?:\s*;\s*(\d+|none))?"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if not floresta:
            return None

        try:
            x, y, ponto = FerramentasClassificacaoPSF.dados(
                floresta.group(1),
                floresta.group(2),
                floresta.group(3),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        arvores = int(floresta.group(4) or 100)
        profundidade = (
            None
            if (floresta.group(5) or "none") == "none"
            else int(floresta.group(5))
        )
        semente = int(floresta.group(6) or 0)

        if arvores < 1 or arvores > 5000:
            return {"erro": "A quantidade de árvores deve estar entre 1 e 5000."}

        modelo = RandomForestClassifier(
            n_estimators=arvores,
            max_depth=profundidade,
            random_state=semente,
            bootstrap=True,
        )
        modelo.fit(x, y)
        resumo = FerramentasClassificacaoPSF.resumo(
            modelo, x, y, ponto
        )
        votos = [
            estimador.predict(ponto)[0].item()
            if hasattr(estimador.predict(ponto)[0], "item")
            else estimador.predict(ponto)[0]
            for estimador in modelo.estimators_
        ]

        return {
            "tipo": "floresta aleatória",
            "dados": {
                "árvores": arvores,
                "profundidade_máxima": profundidade,
                "ponto": ponto[0].tolist(),
            },
            "pedido": "Combinar árvores aleatorizadas para classificar",
            "formula": "classe final = voto majoritário das árvores",
            "passos": [
                "Criamos amostras bootstrap do conjunto de treino.",
                "Cada árvore considera subconjuntos aleatórios de variáveis.",
                f"Votos individuais: {votos[:300]}.",
                (
                    f"Importâncias médias: "
                    f"{modelo.feature_importances_.tolist()}."
                ),
            ],
            "resultado": {
                **resumo,
                "votos": votos,
                "importâncias": modelo.feature_importances_.tolist(),
            },
            "verificacao": (
                "A classe apresentada corresponde ao voto agregado/probabilidade."
            ),
        }


class MotorRedesNeuraisPSF:
    """Perceptron multicamada treinado por retropropagação."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"rede\s+neural\s+(.+?)\s*;\s*(.+?)\s*;\s*(.+?)"
            r"(?:\s*;\s*(.+?))?"
            r"(?:\s*;\s*(\d+))?"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            x, y, ponto = FerramentasClassificacaoPSF.dados(
                padrao.group(1),
                padrao.group(2),
                padrao.group(3),
            )
            camadas_brutas = (
                ParserEstatisticaAvancadaPSF.literal(
                    padrao.group(4),
                    "camadas",
                )
                if padrao.group(4)
                else [10]
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(camadas_brutas, (list, tuple)):
            return {"erro": "As camadas ocultas devem formar uma lista."}

        try:
            camadas = tuple(int(v) for v in camadas_brutas)
        except (TypeError, ValueError):
            return {"erro": "Os tamanhos das camadas devem ser inteiros."}

        if not camadas or any(v <= 0 for v in camadas):
            return {"erro": "Cada camada oculta deve possuir tamanho positivo."}

        iteracoes = int(padrao.group(5) or 2000)
        semente = int(padrao.group(6) or 0)
        escalador = StandardScaler()
        x_e = escalador.fit_transform(x)
        ponto_e = escalador.transform(ponto)
        modelo = MLPClassifier(
            hidden_layer_sizes=camadas,
            activation="relu",
            solver="adam",
            max_iter=iteracoes,
            random_state=semente,
        )

        try:
            modelo.fit(x_e, y)
        except Exception as erro:
            return {"erro": f"Não foi possível treinar a rede: {erro}"}

        resumo = FerramentasClassificacaoPSF.resumo(
            modelo, x_e, y, ponto_e
        )

        return {
            "tipo": "rede neural artificial",
            "dados": {
                "arquitetura_oculta": camadas,
                "iterações_máximas": iteracoes,
                "ponto": ponto[0].tolist(),
            },
            "pedido": "Treinar a rede e classificar o ponto",
            "formula": (
                "z^{(l)}=W^{(l)}a^{(l−1)}+b^{(l)}; "
                "a^{(l)}=ReLU(z^{(l)})"
            ),
            "passos": [
                "Padronizamos as entradas.",
                "Inicializamos pesos segundo a semente indicada.",
                "Executamos propagação direta, cálculo da perda e retropropagação.",
                f"Iterações efetivas: {modelo.n_iter_}.",
                f"Perda final: {modelo.loss_}.",
                f"Curva de perda: {modelo.loss_curve_[:1000]}.",
            ],
            "resultado": {
                **resumo,
                "perda_final": float(modelo.loss_),
                "iterações": int(modelo.n_iter_),
                "camadas": list(modelo.n_layers_ for _ in [0]),
                "formas_pesos": [list(w.shape) for w in modelo.coefs_],
            },
            "verificacao": {
                "convergiu_antes_limite": modelo.n_iter_ < iteracoes,
                "acurácia_treino": resumo["acurácia_treino"],
            },
            "observacao": (
                "O resultado mede o ajuste nos dados fornecidos; "
                "não garante generalização para dados novos."
            ),
        }


class MotorEmbeddingsPSF:
    """Embeddings por coocorrência, PPMI e decomposição SVD."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"embedding\s+(.+?)\s*;\s*(\d+)\s*;\s*(\d+)"
            r"(?:\s*;\s*(\S+))?",
            texto,
        )

        if not padrao:
            return None

        corpus_bruto = padrao.group(1).strip()
        janela = int(padrao.group(2))
        dimensao = int(padrao.group(3))
        consulta = padrao.group(4)

        if (
            len(corpus_bruto) >= 2
            and corpus_bruto[0] in ("'", '"')
            and corpus_bruto[-1] == corpus_bruto[0]
        ):
            try:
                corpus_bruto = ast.literal_eval(corpus_bruto)
            except Exception:
                corpus_bruto = corpus_bruto[1:-1]

        tokens = re.findall(
            r"[a-z0-9_]+",
            normalizar_texto(str(corpus_bruto)),
        )

        if len(tokens) < 2:
            return {"erro": "O corpus precisa de pelo menos duas palavras."}
        if janela < 1 or janela > 100:
            return {"erro": "A janela deve estar entre 1 e 100."}

        vocabulario = sorted(set(tokens))
        indice = {
            palavra: i
            for i, palavra in enumerate(vocabulario)
        }
        matriz = np.zeros(
            (len(vocabulario), len(vocabulario)),
            dtype=float,
        )

        for i, palavra in enumerate(tokens):
            esquerda = max(0, i-janela)
            direita = min(len(tokens), i+janela+1)

            for j in range(esquerda, direita):
                if i == j:
                    continue

                distancia = abs(i-j)
                matriz[indice[palavra], indice[tokens[j]]] += 1/distancia

        total = float(np.sum(matriz))
        linhas = np.sum(matriz, axis=1, keepdims=True)
        colunas = np.sum(matriz, axis=0, keepdims=True)
        denominador = linhas @ colunas
        ppmi = np.zeros_like(matriz)
        mascara = (matriz > 0) & (denominador > 0)
        ppmi[mascara] = np.maximum(
            np.log2(
                matriz[mascara]*total/denominador[mascara]
            ),
            0,
        )

        u, singulares, _ = np.linalg.svd(
            ppmi,
            full_matrices=False,
        )
        dimensao_real = min(
            dimensao,
            len(singulares),
        )

        if dimensao_real < 1:
            return {"erro": "Dimensão inválida."}

        embeddings = (
            u[:, :dimensao_real]
            * np.sqrt(singulares[:dimensao_real])
        )
        tabela = {
            palavra: embeddings[indice[palavra]].tolist()
            for palavra in vocabulario
        }
        similares = None

        if consulta is not None:
            consulta = normalizar_texto(consulta)

            if consulta not in indice:
                return {
                    "erro": f"A palavra {consulta!r} não aparece no corpus."
                }

            vetor = embeddings[indice[consulta]]
            norma = np.linalg.norm(vetor)
            pontuacoes = []

            for palavra in vocabulario:
                if palavra == consulta:
                    continue

                outro = embeddings[indice[palavra]]
                denominador_cos = norma*np.linalg.norm(outro)
                similaridade = (
                    float(np.dot(vetor, outro)/denominador_cos)
                    if denominador_cos > 0
                    else 0.0
                )
                pontuacoes.append((palavra, similaridade))

            similares = sorted(
                pontuacoes,
                key=lambda item: item[1],
                reverse=True,
            )[:10]

        return {
            "tipo": "word embeddings por coocorrência",
            "dados": {
                "tokens": len(tokens),
                "vocabulário": len(vocabulario),
                "janela": janela,
                "dimensão_pedida": dimensao,
            },
            "pedido": "Construir vetores semânticos das palavras",
            "formula": "PPMI(i,j)=max(log₂(P(i,j)/(P(i)P(j))),0); E=U√Σ",
            "passos": [
                f"Vocabulário: {vocabulario}.",
                f"Matriz de coocorrência: {matriz.tolist()}.",
                f"Matriz PPMI: {ppmi.tolist()}.",
                f"Valores singulares: {singulares.tolist()}.",
                f"Dimensão efetiva: {dimensao_real}.",
            ],
            "resultado": {
                "embeddings": tabela,
                "similares": similares,
                "dimensão": dimensao_real,
            },
            "verificacao": {
                "todas_palavras_representadas": len(tabela) == len(vocabulario),
                "valores_finitos": bool(np.isfinite(embeddings).all()),
            },
        }


class MotorInferenciaBayesianaMCMCPSF:
    """Amostragem de Metropolis-Hastings para um parâmetro."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"mcmc\s+metropolis\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            expr = ParserEstatisticaAvancadaPSF.log_posterior(
                padrao.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        atual = float(padrao.group(2))
        desvio_proposta = float(padrao.group(3))
        iteracoes = int(padrao.group(4))
        burn = int(padrao.group(5))
        semente = int(padrao.group(6) or 0)

        if desvio_proposta <= 0:
            return {"erro": "O desvio da proposta deve ser positivo."}
        if iteracoes < 100 or iteracoes > 5_000_000:
            return {"erro": "As iterações devem estar entre 100 e 5000000."}
        if burn < 0 or burn >= iteracoes:
            return {"erro": "burn deve estar entre 0 e iterações−1."}

        funcao = sp.lambdify(
            ParserEstatisticaAvancadaPSF.theta,
            expr,
            modules=["numpy"],
        )
        rng = np.random.default_rng(semente)
        cadeia = np.empty(iteracoes, dtype=float)
        aceites = 0

        try:
            log_atual = float(funcao(atual))
        except Exception as erro:
            return {"erro": f"Não foi possível avaliar a distribuição: {erro}"}

        if not np.isfinite(log_atual):
            return {"erro": "O ponto inicial possui log-posterior não finito."}

        for i in range(iteracoes):
            proposta = atual+rng.normal(0, desvio_proposta)
            log_proposta = float(funcao(proposta))

            if np.isfinite(log_proposta):
                log_alpha = min(0.0, log_proposta-log_atual)

                if math.log(rng.random()) < log_alpha:
                    atual = proposta
                    log_atual = log_proposta
                    aceites += 1

            cadeia[i] = atual

        posterior = cadeia[burn:]
        media = float(np.mean(posterior))
        mediana = float(np.median(posterior))
        desvio = float(np.std(posterior, ddof=1))
        intervalo = np.quantile(
            posterior,
            [0.025, 0.975],
        ).tolist()
        taxa = aceites/iteracoes

        def autocorrelacao(lag):
            if lag >= len(posterior):
                return None

            a = posterior[:-lag] if lag else posterior
            b = posterior[lag:] if lag else posterior

            if np.std(a) == 0 or np.std(b) == 0:
                return 0.0

            return float(np.corrcoef(a, b)[0, 1])

        autocorrelacoes = {
            lag: autocorrelacao(lag)
            for lag in (1, 5, 10, 20, 50)
            if lag < len(posterior)
        }

        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "mcmc_metropolis.png"
        figura, eixo = plt.subplots(figsize=(9, 5))
        eixo.plot(cadeia)
        eixo.axvline(burn, linestyle="--")
        eixo.set_xlabel("Iteração")
        eixo.set_ylabel("theta")
        eixo.set_title("Cadeia de Metropolis-Hastings")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "inferência Bayesiana por MCMC",
            "dados": {
                "log_posterior": sp.sstr(expr),
                "theta_inicial": float(padrao.group(2)),
                "desvio_proposta": desvio_proposta,
                "iterações": iteracoes,
                "burn": burn,
                "semente": semente,
            },
            "pedido": "Aproximar a distribuição posterior",
            "formula": "α=min(1,exp(logπ(θ')−logπ(θ)))",
            "passos": [
                "Propomos θ' por passeio aleatório normal.",
                "Calculamos a razão de aceitação em escala logarítmica.",
                "Aceitamos ou rejeitamos cada proposta.",
                f"Taxa de aceitação: {taxa}.",
                f"Autocorrelações: {autocorrelacoes}.",
            ],
            "resultado": {
                "média_posterior": media,
                "mediana_posterior": mediana,
                "desvio_posterior": desvio,
                "intervalo_credível_95": intervalo,
                "taxa_aceitação": taxa,
                "amostras_utilizadas": len(posterior),
                "últimas_amostras": posterior[-100:].tolist(),
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "taxa_aceitacao_entre_zero_um": 0 <= taxa <= 1,
                "amostras_finitas": bool(np.isfinite(posterior).all()),
            },
            "observacao": (
                "A qualidade depende de mistura, autocorrelação, burn-in "
                "e adequação da distribuição-alvo."
            ),
        }


class MotorEstatisticaCausalPSF:
    """Diagramas causais e estimação linear ajustada."""

    @staticmethod
    def _grafo(arestas):
        grafo = nx.DiGraph()

        for aresta in arestas:
            if not isinstance(aresta, (list, tuple)) or len(aresta) != 2:
                raise ValueError("Cada aresta deve ter formato (causa,efeito).")

            grafo.add_edge(aresta[0], aresta[1])

        if not nx.is_directed_acyclic_graph(grafo):
            raise ValueError("O diagrama causal deve ser acíclico.")

        return grafo

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        dag = re.fullmatch(
            r"causal\s+dag\s+(.+?)\s*;\s*(.+?)\s*;\s*(.+)",
            texto,
        )

        if dag:
            try:
                arestas = ParserEstatisticaAvancadaPSF.literal(
                    dag.group(1),
                    "arestas",
                )
                tratamento = ParserEstatisticaAvancadaPSF.literal(
                    dag.group(2),
                    "tratamento",
                )
                desfecho = ParserEstatisticaAvancadaPSF.literal(
                    dag.group(3),
                    "desfecho",
                )
                grafo = self._grafo(arestas)
            except ValueError as erro:
                return {"erro": str(erro)}

            if tratamento not in grafo or desfecho not in grafo:
                return {"erro": "Tratamento e desfecho devem pertencer ao DAG."}

            pais_t = set(grafo.predecessors(tratamento))
            ancestrais_y = nx.ancestors(grafo, desfecho)
            descendentes_t = nx.descendants(grafo, tratamento)
            confundidores_candidatos = sorted(
                (pais_t & ancestrais_y)-descendentes_t,
                key=str,
            )
            caminhos_dirigidos = list(
                nx.all_simple_paths(
                    grafo,
                    tratamento,
                    desfecho,
                )
            )
            grafo_sem_saida_t = grafo.copy()
            grafo_sem_saida_t.remove_edges_from(
                list(grafo_sem_saida_t.out_edges(tratamento))
            )
            caminhos_backdoor = list(
                nx.all_simple_paths(
                    grafo_sem_saida_t.to_undirected(),
                    tratamento,
                    desfecho,
                    cutoff=max(1, len(grafo)),
                )
            )

            return {
                "tipo": "análise de diagrama causal",
                "dados": {
                    "arestas": list(map(list, arestas)),
                    "tratamento": tratamento,
                    "desfecho": desfecho,
                },
                "pedido": "Identificar caminhos causais e confundidores",
                "formula": (
                    "um conjunto de ajuste deve bloquear caminhos de backdoor "
                    "sem incluir descendentes do tratamento"
                ),
                "passos": [
                    f"Ordem topológica: {list(nx.topological_sort(grafo))}.",
                    f"Pais do tratamento: {sorted(pais_t, key=str)}.",
                    f"Ancestrais do desfecho: {sorted(ancestrais_y, key=str)}.",
                    f"Descendentes do tratamento: {sorted(descendentes_t, key=str)}.",
                    f"Caminhos causais dirigidos: {caminhos_dirigidos}.",
                    f"Caminhos candidatos de backdoor: {caminhos_backdoor}.",
                ],
                "resultado": {
                    "DAG_válido": True,
                    "caminhos_dirigidos": caminhos_dirigidos,
                    "candidatos_ajuste": confundidores_candidatos,
                    "caminhos_backdoor_candidatos": caminhos_backdoor,
                },
                "verificacao": (
                    "Os candidatos de ajuste não são descendentes do tratamento."
                ),
                "observacao": (
                    "A seleção automática é uma análise estrutural básica; "
                    "colisores e critérios completos de d-separação exigem "
                    "interpretação cuidadosa do DAG."
                ),
            }

        estimar = re.fullmatch(
            r"causal\s+linear\s+(.+?)\s*;\s*(.+?)\s*;\s*"
            r"(.+?)\s*;\s*(.+?)\s*;\s*(.+)",
            texto,
        )

        if not estimar:
            return None

        try:
            matriz = ParserEstatisticaAvancadaPSF.matriz(estimar.group(1))
            colunas = list(
                ParserEstatisticaAvancadaPSF.literal(
                    estimar.group(2),
                    "colunas",
                )
            )
            tratamento = ParserEstatisticaAvancadaPSF.literal(
                estimar.group(3),
                "tratamento",
            )
            desfecho = ParserEstatisticaAvancadaPSF.literal(
                estimar.group(4),
                "desfecho",
            )
            ajuste = list(
                ParserEstatisticaAvancadaPSF.literal(
                    estimar.group(5),
                    "ajuste",
                )
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if len(colunas) != matriz.shape[1]:
            return {"erro": "A quantidade de nomes não coincide com as colunas."}
        if tratamento not in colunas or desfecho not in colunas:
            return {"erro": "Tratamento ou desfecho não encontrado."}
        if any(nome not in colunas for nome in ajuste):
            return {"erro": "Variável de ajuste desconhecida."}

        indice_y = colunas.index(desfecho)
        nomes_x = [tratamento] + [
            nome
            for nome in ajuste
            if nome != tratamento and nome != desfecho
        ]
        indices_x = [colunas.index(nome) for nome in nomes_x]
        y = matriz[:, indice_y]
        x = matriz[:, indices_x]
        desenho = np.column_stack([np.ones(len(x)), x])
        beta, residuos, posto, singulares = np.linalg.lstsq(
            desenho,
            y,
            rcond=None,
        )
        previsto = desenho @ beta
        residuo = y-previsto
        n = len(y)
        p = desenho.shape[1]
        sigma2 = float(np.sum(residuo**2)/max(1, n-p))
        cov_beta = sigma2*np.linalg.pinv(desenho.T@desenho)
        erros = np.sqrt(np.diag(cov_beta))
        efeito = float(beta[1])
        erro_efeito = float(erros[1])
        intervalo = [
            efeito-1.96*erro_efeito,
            efeito+1.96*erro_efeito,
        ]
        r2 = 1-float(np.sum(residuo**2))/float(
            np.sum((y-np.mean(y))**2)
        ) if np.sum((y-np.mean(y))**2) > 0 else 1.0

        return {
            "tipo": "estimação causal linear ajustada",
            "dados": {
                "tratamento": tratamento,
                "desfecho": desfecho,
                "ajuste": nomes_x[1:],
                "observações": n,
            },
            "pedido": "Estimar o efeito linear condicional do tratamento",
            "formula": "Y=β₀+τT+γᵀZ+ε",
            "passos": [
                f"Matriz de desenho: {desenho.tolist()}.",
                f"Coeficientes de mínimos quadrados: {beta.tolist()}.",
                f"Resíduos: {residuo.tolist()}.",
                f"Erro-padrão de τ: {erro_efeito}.",
            ],
            "resultado": {
                "efeito_tratamento_tau": efeito,
                "intervalo_aproximado_95": intervalo,
                "coeficientes": {
                    "intercepto": float(beta[0]),
                    **{
                        nome: float(valor)
                        for nome, valor in zip(nomes_x, beta[1:])
                    },
                },
                "R2": r2,
                "posto": int(posto),
                "valores_singulares": singulares.tolist(),
            },
            "verificacao": {
                "posto_completo": int(posto) == desenho.shape[1],
                "residuo_médio": float(np.mean(residuo)),
            },
            "observacao": (
                "A interpretação como efeito causal exige que o conjunto de "
                "ajuste satisfaça hipóteses causais, não apenas estatísticas."
            ),
        }


class FerramentasTopologiaComputacionalPSF:
    """Homologia simplicial sobre GF(2)."""

    @staticmethod
    def fechamento(simplices):
        faces_por_dimensao = {}

        for simplex in simplices:
            if not isinstance(simplex, (list, tuple, set)):
                raise ValueError("Cada simplex deve ser uma lista ou tupla.")

            vertices = tuple(sorted(set(simplex), key=repr))

            if not vertices:
                continue

            for tamanho in range(1, len(vertices)+1):
                for face in itertools.combinations(vertices, tamanho):
                    faces_por_dimensao.setdefault(
                        tamanho-1,
                        set(),
                    ).add(face)

        if not faces_por_dimensao:
            raise ValueError("O complexo não pode ser vazio.")

        return {
            dimensao: sorted(faces, key=repr)
            for dimensao, faces in faces_por_dimensao.items()
        }

    @staticmethod
    def posto_mod2(matriz):
        a = np.asarray(matriz, dtype=np.uint8) % 2

        if a.size == 0:
            return 0

        linhas, colunas = a.shape
        posto = 0

        for coluna in range(colunas):
            pivots = np.where(a[posto:, coluna] == 1)[0]

            if not len(pivots):
                continue

            pivot = posto+int(pivots[0])
            a[[posto, pivot]] = a[[pivot, posto]]

            for linha in range(linhas):
                if linha != posto and a[linha, coluna]:
                    a[linha] ^= a[posto]

            posto += 1

            if posto == linhas:
                break

        return posto

    @classmethod
    def betti(cls, simplices):
        faces = cls.fechamento(simplices)
        dimensao = max(faces)
        postos = {}
        matrizes = {}

        for k in range(1, dimensao+1):
            base_baixa = faces.get(k-1, [])
            base_alta = faces.get(k, [])
            indice_baixo = {
                face: i
                for i, face in enumerate(base_baixa)
            }
            matriz = np.zeros(
                (len(base_baixa), len(base_alta)),
                dtype=np.uint8,
            )

            for j, simplex in enumerate(base_alta):
                for face in itertools.combinations(simplex, len(simplex)-1):
                    matriz[indice_baixo[tuple(face)], j] ^= 1

            matrizes[k] = matriz
            postos[k] = cls.posto_mod2(matriz)

        betti = []

        for k in range(dimensao+1):
            n_k = len(faces.get(k, []))
            posto_dk = postos.get(k, 0)
            posto_dk1 = postos.get(k+1, 0)
            betti.append(n_k-posto_dk-posto_dk1)

        euler = sum(
            ((-1)**k)*len(faces.get(k, []))
            for k in range(dimensao+1)
        )
        return faces, betti, euler, postos


class MotorPoincareComputacionalPSF:
    """Testes homológicos necessários para candidatos a 3-esfera."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"poincare\s+complexo\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            simplices = ParserEstatisticaAvancadaPSF.literal(
                padrao.group(1),
                "lista de simplices",
            )
            faces, betti, euler, postos = (
                FerramentasTopologiaComputacionalPSF.betti(simplices)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        dimensao = max(faces)
        tetraedros = faces.get(3, [])
        triangulos = faces.get(2, [])
        incidencias = {
            triangulo: sum(
                1
                for tetraedro in tetraedros
                if set(triangulo).issubset(tetraedro)
            )
            for triangulo in triangulos
        }
        fechado_pseudomanifold = (
            dimensao == 3
            and bool(tetraedros)
            and all(valor == 2 for valor in incidencias.values())
        )
        homologia_esfera = (
            dimensao == 3
            and betti[:4] == [1, 0, 0, 1]
        )

        if not homologia_esfera or not fechado_pseudomanifold:
            conclusao = "não satisfaz os testes necessários de 3-esfera"
            justificacao = None
        else:
            conclusao = "não determinado"
            justificacao = (
                "A homologia de uma 3-esfera e a condição de pseudovariedade "
                "fechada são necessárias, mas não verificam por si sós que o "
                "complexo seja uma 3-variedade simplesmente conexa. A "
                "Conjectura de Poincaré, resolvida por Perelman, permite concluir "
                "S³ apenas depois de estabelecer essas hipóteses topológicas."
            )

        return {
            "tipo": "análise computacional relacionada à Conjectura de Poincaré",
            "dados": {
                "simplices_máximos_recebidos": simplices,
                "estado_problema": STATUS_PROBLEMAS_MATEMATICOS_PSF["poincare"],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF["atualizado_em"],
            },
            "pedido": "Testar invariantes necessários de uma triangulação de S³",
            "formula": "β_k=dim ker ∂_k−dim im ∂_{k+1}; χ=Σ(−1)^k f_k",
            "passos": [
                (
                    "Fechamos o complexo incluindo todas as faces dos "
                    "simplices recebidos."
                ),
                f"Quantidades por dimensão: "
                f"{ {k: len(v) for k, v in faces.items()} }.",
                f"Postos das matrizes de bordo sobre GF(2): {postos}.",
                f"Números de Betti: {betti}.",
                f"Característica de Euler: {euler}.",
                (
                    "Verificamos se cada face triangular pertence a exatamente "
                    "dois tetraedros."
                ),
            ],
            "resultado": {
                "dimensão": dimensao,
                "betti_GF2": betti,
                "euler": euler,
                "pseudovariedade_fechada": fechado_pseudomanifold,
                "homologia_de_S3": homologia_esfera,
                "classificação_completa": conclusao,
            },
            "verificacao": {
                "incidências_triangulares": {
                    str(chave): valor
                    for chave, valor in incidencias.items()
                },
            },
            "justificacao": justificacao,
        }


class MotorRiemannEstadoPSF:
    """Verificação numérica finita de zeros da função zeta."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"riemann\s+zeros\s+(\d+)"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        quantidade = int(padrao.group(1))
        precisao = int(padrao.group(2) or 50)

        if quantidade < 1 or quantidade > 10000:
            return {"erro": "A quantidade deve estar entre 1 e 10000."}
        if precisao < 20 or precisao > 500:
            return {"erro": "A precisão deve estar entre 20 e 500 dígitos."}

        mp.mp.dps = precisao
        zeros = []
        max_desvio = mp.mpf("0")
        max_residuo = mp.mpf("0")

        for indice in range(1, quantidade+1):
            zero = mp.zetazero(indice)
            desvio = abs(mp.re(zero)-mp.mpf("0.5"))
            residuo = abs(mp.zeta(zero))
            max_desvio = max(max_desvio, desvio)
            max_residuo = max(max_residuo, residuo)

            if indice <= 200:
                zeros.append({
                    "índice": indice,
                    "zero": str(zero),
                    "parte_real": str(mp.re(zero)),
                    "parte_imaginária": str(mp.im(zero)),
                    "|ζ(ρ)|": str(residuo),
                    "desvio_de_1/2": str(desvio),
                })

        return {
            "tipo": "verificação numérica da Hipótese de Riemann",
            "dados": {
                "zeros_verificados": quantidade,
                "precisão_decimal": precisao,
                "estado_problema": STATUS_PROBLEMAS_MATEMATICOS_PSF["riemann"],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF["atualizado_em"],
            },
            "pedido": "Calcular zeros não triviais e verificar a linha crítica",
            "formula": "ζ(ρ)=0 e Re(ρ)=1/2",
            "passos": [
                "Calculamos cada zero não trivial pela numeração padrão.",
                "Avaliamos ζ no zero calculado.",
                "Comparamos a parte real com 1/2.",
                f"Maior desvio numérico: {max_desvio}.",
                f"Maior resíduo |ζ(ρ)|: {max_residuo}.",
            ],
            "resultado": {
                "zeros_registrados": zeros,
                "todos_na_linha_critica_numericamente": bool(
                    max_desvio < mp.mpf(10)**(-(precisao//2))
                ),
                "estado_geral": "não determinado",
            },
            "verificacao": (
                f"Foram verificados finitamente {quantidade} zeros."
            ),
            "justificacao": (
                "Verificar qualquer quantidade finita de zeros não demonstra "
                "que todos os infinitos zeros não triviais estejam na linha "
                "Re(s)=1/2. A Hipótese de Riemann continua aberta; o cálculo "
                "fornece evidência numérica, não uma prova universal."
            ),
        }


class MotorPvsNPPSF:
    """SAT finito: procura e verificação de certificados."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"pvsnp\s+sat\s+(.+)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            clausulas = ParserEstatisticaAvancadaPSF.literal(
                padrao.group(1),
                "cláusulas",
            )
            certificado = (
                ParserEstatisticaAvancadaPSF.literal(
                    padrao.group(2),
                    "certificado",
                )
                if padrao.group(2)
                else None
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(clausulas, (list, tuple)) or not clausulas:
            return {"erro": "Forneça uma lista não vazia de cláusulas."}

        try:
            clausulas = [
                [int(literal) for literal in clausula]
                for clausula in clausulas
            ]
        except (TypeError, ValueError):
            return {"erro": "Cada literal deve ser um inteiro não nulo."}

        if any(
            not clausula or any(literal == 0 for literal in clausula)
            for clausula in clausulas
        ):
            return {"erro": "Cláusulas vazias ou literal zero não são aceitos."}

        variaveis = sorted({
            abs(literal)
            for clausula in clausulas
            for literal in clausula
        })

        if len(variaveis) > 24:
            return {
                "erro": (
                    "A busca exata está limitada a 24 variáveis; "
                    "forneça um certificado para verificação direta."
                )
            }

        def satisfaz(atribuicao):
            return all(
                any(
                    atribuicao[abs(literal)] == (literal > 0)
                    for literal in clausula
                )
                for clausula in clausulas
            )

        verificacao_certificado = None

        if certificado is not None:
            if isinstance(certificado, dict):
                atribuicao_c = {
                    int(chave): bool(valor)
                    for chave, valor in certificado.items()
                }
            elif isinstance(certificado, (list, tuple)):
                atribuicao_c = {
                    variavel: bool(valor)
                    for variavel, valor in zip(variaveis, certificado)
                }
            else:
                return {"erro": "Certificado deve ser dicionário ou lista."}

            if any(v not in atribuicao_c for v in variaveis):
                return {"erro": "O certificado não atribui todas as variáveis."}

            verificacao_certificado = satisfaz(atribuicao_c)

        solucao = None
        tentativas = 0

        for bits in itertools.product((False, True), repeat=len(variaveis)):
            tentativas += 1
            atribuicao = dict(zip(variaveis, bits))

            if satisfaz(atribuicao):
                solucao = atribuicao
                break

        return {
            "tipo": "experimento finito de P versus NP por SAT",
            "dados": {
                "variáveis": variaveis,
                "cláusulas": clausulas,
                "estado_problema": STATUS_PROBLEMAS_MATEMATICOS_PSF["p_vs_np"],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF["atualizado_em"],
            },
            "pedido": "Resolver a instância SAT e comparar procura com verificação",
            "formula": (
                "SAT∈NP: uma atribuição candidata é verificada em tempo "
                "polinomial no tamanho da fórmula"
            ),
            "passos": [
                f"Existem {len(variaveis)} variáveis e "
                f"até {2**len(variaveis)} atribuições.",
                f"Testamos {tentativas} atribuições até a decisão.",
                (
                    f"Certificado fornecido válido: {verificacao_certificado}."
                    if certificado is not None
                    else "Nenhum certificado externo foi fornecido."
                ),
            ],
            "resultado": {
                "satisfatível": solucao is not None,
                "atribuição": solucao,
                "tentativas_busca": tentativas,
                "certificado_fornecido_válido": verificacao_certificado,
                "P_igual_NP": "não determinado",
            },
            "verificacao": (
                "A atribuição encontrada satisfaz todas as cláusulas."
                if solucao is not None
                else "A enumeração completa não encontrou atribuição."
            ),
            "justificacao": (
                "Resolver uma instância finita, ou mesmo muitas instâncias, "
                "não determina se todo problema de NP possui algoritmo "
                "polinomial. P versus NP é uma afirmação sobre famílias "
                "infinitas de entradas e continua aberto."
            ),
        }


class MotorNavierStokesDiagnosticoPSF:
    """Diagnósticos discretos de campos de velocidade bidimensionais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"navier\s+stokes\s+diagnostico\s+"
            r"(.+?)\s*;\s*(.+?)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)",
            texto,
        )

        if not padrao:
            return None

        try:
            u = ParserEstatisticaAvancadaPSF.matriz(padrao.group(1))
            v = ParserEstatisticaAvancadaPSF.matriz(padrao.group(2))
        except ValueError as erro:
            return {"erro": str(erro)}

        dx = float(padrao.group(3))
        dy = float(padrao.group(4))
        nu = float(padrao.group(5))

        if u.shape != v.shape:
            return {"erro": "u e v devem possuir a mesma forma."}
        if min(u.shape) < 2:
            return {"erro": "Cada dimensão da malha deve ter pelo menos 2 pontos."}
        if dx <= 0 or dy <= 0 or nu < 0:
            return {"erro": "dx e dy devem ser positivos; ν não pode ser negativo."}

        du_dy, du_dx = np.gradient(u, dy, dx)
        dv_dy, dv_dx = np.gradient(v, dy, dx)
        divergencia = du_dx+dv_dy
        vorticidade = dv_dx-du_dy
        energia = 0.5*float(np.sum(u*u+v*v))*dx*dy
        enstrofia = 0.5*float(np.sum(vorticidade**2))*dx*dy
        dissipacao = nu*float(
            np.sum(
                du_dx**2+du_dy**2+dv_dx**2+dv_dy**2
            )
        )*dx*dy
        max_div = float(np.max(np.abs(divergencia)))
        norma_div = float(np.sqrt(np.sum(divergencia**2)*dx*dy))

        return {
            "tipo": "diagnóstico numérico de Navier–Stokes",
            "dados": {
                "forma_malha": list(u.shape),
                "dx": dx,
                "dy": dy,
                "viscosidade": nu,
                "estado_problema": STATUS_PROBLEMAS_MATEMATICOS_PSF["navier_stokes"],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF["atualizado_em"],
            },
            "pedido": "Medir incompressibilidade, vorticidade e energia do campo",
            "formula": (
                "∇·u=∂u/∂x+∂v/∂y; "
                "ω=∂v/∂x−∂u/∂y; E=½∫|u|²"
            ),
            "passos": [
                "Calculamos derivadas discretas nas duas direções.",
                f"Divergência discreta: {divergencia.tolist()}.",
                f"Vorticidade discreta: {vorticidade.tolist()}.",
                f"Norma L2 da divergência: {norma_div}.",
                f"Máxima divergência absoluta: {max_div}.",
                f"Energia cinética: {energia}.",
                f"Enstrofia: {enstrofia}.",
                f"Dissipação viscosa aproximada: {dissipacao}.",
            ],
            "resultado": {
                "divergência": divergencia.tolist(),
                "vorticidade": vorticidade.tolist(),
                "norma_divergência": norma_div,
                "máxima_divergência": max_div,
                "energia_cinética": energia,
                "enstrofia": enstrofia,
                "dissipação": dissipacao,
                "existência_suavidade_3D_geral": "não determinado",
            },
            "verificacao": {
                "campo_aproximadamente_incompressível": max_div < 1e-6,
            },
            "justificacao": (
                "Diagnósticos numa malha finita não demonstram existência e "
                "suavidade global das soluções tridimensionais contínuas. "
                "O problema do milénio continua aberto; o cálculo apenas mede "
                "o campo discreto fornecido."
            ),
        }


class MotorBSDNumericoPSF:
    """Evidência aritmética finita para curvas elípticas."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"bsd\s+([+-]?\d+)\s+([+-]?\d+)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)",
            texto,
        )

        if not padrao:
            return None

        a = int(padrao.group(1))
        b = int(padrao.group(2))
        limite_x = int(padrao.group(3))
        limite_primo = int(padrao.group(4))
        discriminante = -16*(4*a**3+27*b**2)

        if discriminante == 0:
            return {"erro": "A curva é singular."}
        if limite_x < 1 or limite_x > 1_000_000:
            return {"erro": "O limite de x deve estar entre 1 e 1000000."}
        if limite_primo < 2 or limite_primo > 100000:
            return {"erro": "O limite de primos deve estar entre 2 e 100000."}

        pontos_inteiros = []

        for x in range(-limite_x, limite_x+1):
            rhs = x**3+a*x+b

            if rhs < 0:
                continue

            y = math.isqrt(rhs)

            if y*y == rhs:
                pontos_inteiros.append((x, y))

                if y != 0:
                    pontos_inteiros.append((x, -y))

        dados_primos = []
        produto_euler_parcial = mp.mpf("1")

        for p in list(sp.primerange(2, limite_primo+1)):
            if discriminante % p == 0:
                dados_primos.append({
                    "p": p,
                    "redução": "má",
                })
                continue

            quantidade = 1

            for x in range(p):
                rhs = (x**3+a*x+b) % p
                quantidade += sum(
                    1
                    for y in range(p)
                    if (y*y-rhs) % p == 0
                )

            ap = p+1-quantidade
            fator_s1 = 1-ap/p+1/p
            produto_euler_parcial *= 1/fator_s1
            dados_primos.append({
                "p": p,
                "#E(F_p)": quantidade,
                "a_p": ap,
                "fator_local_em_s1": fator_s1,
            })

        return {
            "tipo": "evidência numérica de Birch e Swinnerton-Dyer",
            "dados": {
                "curva": f"y²=x³+({a})x+({b})",
                "discriminante": discriminante,
                "busca_inteira": limite_x,
                "primos_até": limite_primo,
                "estado_problema": STATUS_PROBLEMAS_MATEMATICOS_PSF[
                    "birch_swinnerton_dyer"
                ],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF[
                    "atualizado_em"
                ],
            },
            "pedido": "Calcular pontos e dados locais finitos da curva",
            "formula": "a_p=p+1−#E(F_p); L_p(s)=(1−a_pp^{-s}+p^{1−2s})^{-1}",
            "passos": [
                f"Pontos inteiros encontrados: {pontos_inteiros}.",
                f"Dados locais: {dados_primos}.",
                f"Produto de Euler parcial formal em s=1: {produto_euler_parcial}.",
            ],
            "resultado": {
                "pontos_inteiros": pontos_inteiros,
                "dados_primos": dados_primos,
                "produto_euler_parcial_s1": str(produto_euler_parcial),
                "posto_racional_exato": "não determinado",
                "conjectura_geral": "não determinado",
            },
            "verificacao": (
                "Cada contagem modular foi feita por enumeração completa em F_p."
            ),
            "justificacao": (
                "Uma busca limitada de pontos e um produto de Euler truncado "
                "não determinam o posto do grupo de pontos racionais nem a "
                "ordem de anulação exata de L(E,s) em s=1. A conjectura "
                "Birch–Swinnerton-Dyer continua aberta em geral."
            ),
        }


class MotorHodgeComputacionalPSF:
    """Diamantes de Hodge conhecidos e validação de simetrias."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        projetivo = re.fullmatch(
            r"hodge\s+cp\s+(\d+)",
            texto,
        )

        if projetivo:
            n = int(projetivo.group(1))

            if n < 0 or n > 100:
                return {"erro": "A dimensão deve estar entre 0 e 100."}

            matriz = [
                [
                    1 if p == q else 0
                    for q in range(n+1)
                ]
                for p in range(n+1)
            ]
            betti = [
                sum(
                    matriz[p][k-p]
                    for p in range(n+1)
                    if 0 <= k-p <= n
                )
                for k in range(2*n+1)
            ]

            return {
                "tipo": "diamante de Hodge do espaço projetivo complexo",
                "dados": {
                    "variedade": f"CP^{n}",
                    "dimensão_complexa": n,
                },
                "pedido": "Calcular os números de Hodge",
                "formula": "h^{p,q}(CP^n)=1 se p=q; 0 caso contrário",
                "passos": [
                    "Enumeramos 0≤p,q≤n.",
                    "Colocamos 1 apenas na diagonal p=q.",
                    f"Números de Betti pela soma p+q=k: {betti}.",
                ],
                "resultado": {
                    "hodge_matriz": matriz,
                    "betti": betti,
                    "euler": sum(betti),
                },
                "verificacao": {
                    "simetria_conjugação": True,
                    "dualidade_serre": True,
                },
            }

        validar = re.fullmatch(
            r"hodge\s+validar\s+(.+)",
            texto,
        )

        if not validar:
            return None

        try:
            matriz = ParserEstatisticaAvancadaPSF.matriz(
                validar.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if matriz.shape[0] != matriz.shape[1]:
            return {"erro": "A matriz de Hodge deve ser quadrada."}
        if not np.allclose(matriz, np.round(matriz)) or np.any(matriz < 0):
            return {"erro": "Os números de Hodge devem ser inteiros não negativos."}

        matriz = np.round(matriz).astype(int)
        n = matriz.shape[0]-1
        conjugacao = bool(np.array_equal(matriz, matriz.T))
        serre = all(
            matriz[p, q] == matriz[n-p, n-q]
            for p in range(n+1)
            for q in range(n+1)
        )
        betti = [
            int(sum(
                matriz[p, k-p]
                for p in range(n+1)
                if 0 <= k-p <= n
            ))
            for k in range(2*n+1)
        ]

        return {
            "tipo": "validação de dados de Hodge",
            "dados": {
                "dimensão_complexa_inferida": n,
                "estado_conjectura": STATUS_PROBLEMAS_MATEMATICOS_PSF["hodge"],
                "estado_atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF["atualizado_em"],
            },
            "pedido": "Verificar simetrias necessárias do diamante de Hodge",
            "formula": "h^{p,q}=h^{q,p}=h^{n−p,n−q}",
            "passos": [
                f"Simetria por conjugação: {conjugacao}.",
                f"Dualidade de Serre: {serre}.",
                f"Números de Betti: {betti}.",
            ],
            "resultado": {
                "matriz": matriz.tolist(),
                "simetria_conjugação": conjugacao,
                "dualidade_serre": serre,
                "betti": betti,
                "dados_formalmente_compatíveis": conjugacao and serre,
            },
            "verificacao": (
                "As simetrias testadas são necessárias, mas não suficientes "
                "para realizar uma variedade projetiva específica."
            ),
        }


class MotorYangMillsLatticePSF:
    """Ação de Wilson U(1) numa rede periódica bidimensional."""

    @staticmethod
    def _envolver(angulo):
        return (angulo+math.pi) % (2*math.pi)-math.pi

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        lattice = re.fullmatch(
            r"yang\s+mills\s+u1\s+(.+?)\s*;\s*(.+?)\s*;\s*"
            r"([0-9.eE+-]+)",
            texto,
        )

        if lattice:
            try:
                ux = ParserEstatisticaAvancadaPSF.matriz(lattice.group(1))
                uy = ParserEstatisticaAvancadaPSF.matriz(lattice.group(2))
            except ValueError as erro:
                return {"erro": str(erro)}

            beta = float(lattice.group(3))

            if ux.shape != uy.shape:
                return {"erro": "Ux e Uy devem possuir a mesma forma."}
            if beta < 0:
                return {"erro": "β não pode ser negativo."}

            nx_t, ny_t = ux.shape
            plaquetas = np.zeros_like(ux)

            for i in range(nx_t):
                for j in range(ny_t):
                    plaquetas[i, j] = self._envolver(
                        ux[i, j]
                        + uy[i, (j+1) % ny_t]
                        - ux[(i+1) % nx_t, j]
                        - uy[i, j]
                    )

            acao = beta*float(np.sum(1-np.cos(plaquetas)))
            media_plaqueta = float(np.mean(np.cos(plaquetas)))

            # Transformação de gauge determinística para verificar invariância.
            gauge = np.fromfunction(
                lambda i, j: 0.137*i+0.211*j,
                ux.shape,
                dtype=float,
            )
            ux_g = np.zeros_like(ux)
            uy_g = np.zeros_like(uy)

            for i in range(nx_t):
                for j in range(ny_t):
                    ux_g[i, j] = self._envolver(
                        ux[i, j]
                        + gauge[i, j]
                        - gauge[(i+1) % nx_t, j]
                    )
                    uy_g[i, j] = self._envolver(
                        uy[i, j]
                        + gauge[i, j]
                        - gauge[i, (j+1) % ny_t]
                    )

            plaquetas_g = np.zeros_like(ux)

            for i in range(nx_t):
                for j in range(ny_t):
                    plaquetas_g[i, j] = self._envolver(
                        ux_g[i, j]
                        + uy_g[i, (j+1) % ny_t]
                        - ux_g[(i+1) % nx_t, j]
                        - uy_g[i, j]
                    )

            acao_g = beta*float(np.sum(1-np.cos(plaquetas_g)))

            return {
                "tipo": "Yang–Mills U(1) em rede",
                "dados": {
                    "forma_rede": list(ux.shape),
                    "beta": beta,
                },
                "pedido": "Calcular plaquetas, ação de Wilson e invariância de gauge",
                "formula": "S=βΣ_p(1−cos θ_p)",
                "passos": [
                    "Combinamos as quatro ligações orientadas de cada plaqueta.",
                    f"Ângulos de plaqueta: {plaquetas.tolist()}.",
                    f"Ação de Wilson: {acao}.",
                    f"Plaqueta média: {media_plaqueta}.",
                    "Aplicamos uma transformação de gauge nos vértices.",
                    f"Ação após transformação: {acao_g}.",
                ],
                "resultado": {
                    "plaquetas": plaquetas.tolist(),
                    "ação_Wilson": acao,
                    "plaqueta_média": media_plaqueta,
                    "ação_transformada": acao_g,
                },
                "verificacao": {
                    "invariância_gauge_numérica": bool(
                        np.isclose(acao, acao_g, atol=1e-10)
                    ),
                    "diferença_ação": abs(acao-acao_g),
                },
            }

        mass_gap = re.fullmatch(
            r"yang\s+mills\s+mass\s+gap",
            texto,
        )

        if not mass_gap:
            return None

        return {
            "tipo": "estado do problema Yang–Mills e mass gap",
            "dados": {
                "estado": STATUS_PROBLEMAS_MATEMATICOS_PSF[
                    "yang_mills_mass_gap"
                ],
                "atualizado_em": STATUS_PROBLEMAS_MATEMATICOS_PSF[
                    "atualizado_em"
                ],
            },
            "pedido": "Determinar a existência matemática rigorosa e o mass gap",
            "formula": "teoria quântica de Yang–Mills em R⁴ com Δ>0",
            "passos": [
                "Experimentos e simulações fornecem evidência física.",
                "Uma prova matemática completa ainda não é conhecida.",
            ],
            "resultado": {"prova_geral": "não determinado"},
            "justificacao": (
                "A existência rigorosa da teoria quântica de Yang–Mills em "
                "quatro dimensões e a demonstração de um mass gap positivo "
                "continuam abertas. Cálculos em rede finita não constituem "
                "uma construção do limite contínuo exigido."
            ),
        }


class MotorModelosConscienciaPSF:
    """Métricas informacionais de um modelo de estados; não mede consciência real."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"consciencia\s+markov\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            transicao = ParserEstatisticaAvancadaPSF.matriz(
                padrao.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if transicao.shape[0] != transicao.shape[1]:
            return {"erro": "A matriz de transição deve ser quadrada."}
        if np.any(transicao < 0):
            return {"erro": "Probabilidades não podem ser negativas."}

        somas = np.sum(transicao, axis=1)

        if not np.allclose(somas, 1, atol=1e-8):
            return {"erro": "Cada linha da matriz deve somar 1."}

        valores, vetores = np.linalg.eig(transicao.T)
        indice = int(np.argmin(np.abs(valores-1)))
        estacionaria = np.real(vetores[:, indice])
        estacionaria = np.maximum(estacionaria, 0)

        if np.sum(estacionaria) == 0:
            estacionaria = np.abs(np.real(vetores[:, indice]))

        estacionaria = estacionaria/np.sum(estacionaria)
        conjunta = estacionaria[:, None]*transicao
        marginal_futuro = np.sum(conjunta, axis=0)

        def h(probabilidades):
            valores_p = np.asarray(probabilidades, dtype=float)
            valores_p = valores_p[valores_p > 0]
            return float(-np.sum(valores_p*np.log2(valores_p)))

        entropia_estado = h(estacionaria)
        entropia_condicional = sum(
            estacionaria[i]*h(transicao[i])
            for i in range(len(estacionaria))
        )
        informacao_preditiva = entropia_estado-entropia_condicional
        divergencia_uniforme = sum(
            estacionaria[i]
            * sum(
                p*math.log2(p/(1/len(estacionaria)))
                for p in transicao[i]
                if p > 0
            )
            for i in range(len(estacionaria))
        )

        return {
            "tipo": "modelo informacional de estados mentais",
            "dados": {
                "estados": transicao.shape[0],
                "matriz_transição": transicao.tolist(),
            },
            "pedido": "Calcular métricas matemáticas do processo de estados",
            "formula": (
                "H(S)=−Σπ_i log₂π_i; "
                "I(S_t;S_{t+1})=H(S_{t+1})−H(S_{t+1}|S_t)"
            ),
            "passos": [
                f"Distribuição estacionária: {estacionaria.tolist()}.",
                f"Entropia estacionária: {entropia_estado}.",
                f"Entropia condicional/taxa: {entropia_condicional}.",
                f"Informação preditiva: {informacao_preditiva}.",
                (
                    "Divergência média das transições em relação à "
                    f"distribuição uniforme: {divergencia_uniforme}."
                ),
            ],
            "resultado": {
                "distribuição_estacionária": estacionaria.tolist(),
                "entropia_estado_bits": entropia_estado,
                "taxa_entropia_bits": entropia_condicional,
                "informação_preditiva_bits": informacao_preditiva,
                "informação_efetiva_proxy_bits": divergencia_uniforme,
            },
            "verificacao": {
                "estacionariedade": bool(
                    np.allclose(
                        estacionaria @ transicao,
                        estacionaria,
                        atol=1e-8,
                    )
                ),
                "probabilidades_somam_um": bool(
                    np.isclose(np.sum(estacionaria), 1)
                ),
            },
            "observacao": (
                "Estas são métricas de um processo de Markov. Elas não provam, "
                "detectam nem quantificam consciência real; apenas analisam o "
                "modelo matemático fornecido."
            ),
        }


class MotorProvasAutomaticasPSF:
    """Verificação simbólica de identidades e procura de contraexemplos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"prova\s+automatica\s+identidade\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        esquerda_texto = padrao.group(1).replace("^", "**")
        direita_texto = padrao.group(2).replace("^", "**")
        nomes = sorted(set(
            re.findall(r"[A-Za-z][A-Za-z0-9_]*", esquerda_texto+direita_texto)
        )-{
            "sin", "cos", "tan", "exp", "log", "ln", "sqrt", "pi", "e"
        })
        simbolos = {
            nome: sp.Symbol(nome, real=True)
            for nome in nomes
        }
        locais = {
            **simbolos,
            "sin": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "pi": sp.pi,
            "e": sp.E,
        }

        try:
            esquerda = sp.sympify(esquerda_texto, locals=locais)
            direita = sp.sympify(direita_texto, locals=locais)
        except Exception as erro:
            return {"erro": f"Expressão inválida: {erro}"}

        diferenca = sp.simplify(esquerda-direita)
        fatorada = sp.factor(diferenca)
        expandida = sp.expand(diferenca)
        provada = diferenca == 0
        contraexemplo = None

        if not provada and simbolos:
            rng = np.random.default_rng(0)

            for _ in range(200):
                atribuicao = {
                    simbolo: int(rng.integers(-10, 11))
                    for simbolo in simbolos.values()
                }

                try:
                    valor_e = sp.N(esquerda.subs(atribuicao))
                    valor_d = sp.N(direita.subs(atribuicao))

                    if (
                        valor_e.is_finite
                        and valor_d.is_finite
                        and abs(complex(valor_e)-complex(valor_d)) > 1e-9
                    ):
                        contraexemplo = {
                            str(chave): valor
                            for chave, valor in atribuicao.items()
                        }
                        contraexemplo["esquerda"] = str(valor_e)
                        contraexemplo["direita"] = str(valor_d)
                        break
                except Exception:
                    continue

        if provada:
            estado = "identidade verificada simbolicamente"
            justificacao = None
        elif contraexemplo is not None:
            estado = "afirmação falsa"
            justificacao = None
        else:
            estado = "não determinado"
            justificacao = (
                "A simplificação simbólica não reduziu a diferença a zero e "
                "a busca numérica limitada não encontrou contraexemplo. Isso "
                "não prova nem refuta a identidade; podem ser necessárias "
                "hipóteses de domínio ou uma estratégia de prova diferente."
            )

        return {
            "tipo": "verificação automática de identidade",
            "dados": {
                "lado_esquerdo": sp.sstr(esquerda),
                "lado_direito": sp.sstr(direita),
                "variáveis": nomes,
            },
            "pedido": "Provar a identidade ou encontrar contraexemplo",
            "formula": "L=R ⇔ simplificar(L−R)=0",
            "passos": [
                f"Diferença inicial: {sp.sstr(esquerda-direita)}.",
                f"Forma expandida: {sp.sstr(expandida)}.",
                f"Forma fatorada: {sp.sstr(fatorada)}.",
                f"Simplificação final: {sp.sstr(diferenca)}.",
                f"Contraexemplo encontrado: {contraexemplo}.",
            ],
            "resultado": {
                "estado": estado,
                "provada": provada,
                "contraexemplo": contraexemplo,
            },
            "verificacao": (
                "A diferença é identicamente zero."
                if provada
                else (
                    "A avaliação contradiz a igualdade."
                    if contraexemplo is not None
                    else "Nenhuma decisão completa foi obtida."
                )
            ),
            "justificacao": justificacao,
            "observacao": (
                "A automação verifica a transformação simbólica executada; "
                "não substitui a auditoria formal de todas as hipóteses."
            ),
        }


class MotorSinteseMatematicaPSF:
    """Síntese calculável de uma sequência numérica."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"sintese\s+matematica\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            valores = ParserEstatisticaAvancadaPSF.literal(
                padrao.group(1),
                "sequência",
            )
            vetor = np.asarray(valores, dtype=float)
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if vetor.ndim != 1 or len(vetor) == 0:
            return {"erro": "Forneça uma sequência numérica não vazia."}
        if not np.isfinite(vetor).all():
            return {"erro": "A sequência contém valor não finito."}

        inteiros = bool(np.allclose(vetor, np.round(vetor)))
        diferencas = [vetor.tolist()]
        ordem_constante = None

        for ordem in range(1, min(len(vetor), 10)):
            proxima = np.diff(np.asarray(diferencas[-1], dtype=float))
            diferencas.append(proxima.tolist())

            if len(proxima) and np.allclose(proxima, proxima[0]):
                ordem_constante = ordem
                break

        x = sp.Symbol("x")
        pontos = [
            (indice, sp.Rational(str(valor)))
            for indice, valor in enumerate(vetor.tolist())
        ]
        polinomio = (
            sp.expand(sp.interpolate(pontos, x))
            if len(vetor) <= 30
            else None
        )
        proximo_polinomial = (
            sp.simplify(polinomio.subs(x, len(vetor)))
            if polinomio is not None
            else None
        )
        gcd_valor = None
        lcm_valor = None
        primos = None

        if inteiros:
            lista_i = [int(round(v)) for v in vetor]
            gcd_valor = abs(math.gcd(*lista_i))
            lcm_valor = abs(math.lcm(*lista_i)) if all(lista_i) else 0
            primos = [bool(sp.isprime(v)) for v in lista_i]

        simetrica = bool(
            np.allclose(vetor, vetor[::-1])
        )
        media = float(np.mean(vetor))
        mediana = float(np.median(vetor))
        variancia = float(np.var(vetor))
        entropia = None
        unicos, contagens = np.unique(vetor, return_counts=True)
        probabilidades = contagens/len(vetor)
        entropia = float(
            -np.sum(probabilidades*np.log2(probabilidades))
        )

        return {
            "tipo": "síntese matemática de sequência",
            "dados": {
                "sequência": vetor.tolist(),
                "quantidade": len(vetor),
            },
            "pedido": "Reunir propriedades aritméticas, estatísticas e estruturais",
            "formula": (
                "estatística descritiva + diferenças finitas + "
                "interpolação polinomial"
            ),
            "passos": [
                f"Soma={float(np.sum(vetor))}; média={media}; mediana={mediana}.",
                f"Variância populacional={variancia}.",
                f"Tabela de diferenças até ordem testada: {diferencas}.",
                f"Primeira ordem constante encontrada: {ordem_constante}.",
                (
                    f"Polinômio interpolador: {sp.sstr(polinomio)}."
                    if polinomio is not None
                    else "Interpolação omitida para mais de 30 valores."
                ),
                f"Simetria por reversão: {simetrica}.",
                f"Entropia das frequências: {entropia} bits.",
            ],
            "resultado": {
                "soma": float(np.sum(vetor)),
                "média": media,
                "mediana": mediana,
                "variância": variancia,
                "mínimo": float(np.min(vetor)),
                "máximo": float(np.max(vetor)),
                "inteiros": inteiros,
                "mdc": gcd_valor,
                "mmc": lcm_valor,
                "primalidade": primos,
                "palíndroma": simetrica,
                "diferenças": diferencas,
                "ordem_diferença_constante": ordem_constante,
                "polinômio_interpolador": (
                    sp.sstr(polinomio)
                    if polinomio is not None
                    else None
                ),
                "próximo_valor_pelo_polinômio": (
                    sp.sstr(proximo_polinomial)
                    if proximo_polinomial is not None
                    else None
                ),
                "entropia_frequências_bits": entropia,
            },
            "verificacao": (
                "O polinômio interpolador reproduz exatamente os pontos "
                "fornecidos, mas não garante a lei geradora futura da sequência."
            ),
        }



class ParserNosVariedadesPSF:
    """Estruturas seguras para diagramas de nós e dados de 3-variedades."""

    @staticmethod
    def literal(texto, nome="estrutura"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválida.") from erro

    @classmethod
    def gauss(cls, texto):
        dados = cls.literal(texto, "código de Gauss")

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("O código de Gauss deve ser uma lista não vazia.")

        try:
            codigo = [int(v) for v in dados]
        except (TypeError, ValueError) as erro:
            raise ValueError("O código de Gauss deve conter inteiros.") from erro

        if any(v == 0 for v in codigo):
            raise ValueError("O rótulo zero não é permitido.")

        return codigo

    @classmethod
    def pd(cls, texto):
        dados = cls.literal(texto, "diagrama PD")

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("O diagrama PD deve ser uma lista não vazia.")

        cruzamentos = []

        for item in dados:
            if isinstance(item, dict):
                arestas = item.get("arestas")
                sinal = item.get("sinal", 1)
            elif isinstance(item, (list, tuple)) and len(item) == 5:
                arestas = item[:4]
                sinal = item[4]
            elif isinstance(item, (list, tuple)) and len(item) == 4:
                arestas = item
                sinal = 1
            else:
                raise ValueError(
                    "Cada cruzamento deve ser (a,b,c,d,sinal) "
                    "ou {'arestas':[a,b,c,d],'sinal':±1}."
                )

            try:
                arestas = tuple(int(v) for v in arestas)
                sinal = int(sinal)
            except (TypeError, ValueError) as erro:
                raise ValueError("Rótulos e sinais devem ser inteiros.") from erro

            if len(arestas) != 4 or sinal not in (-1, 1):
                raise ValueError("Cada cruzamento exige quatro arestas e sinal ±1.")

            cruzamentos.append({
                "arestas": arestas,
                "sinal": sinal,
            })

        ocorrencias = {}

        for cruzamento in cruzamentos:
            for aresta in cruzamento["arestas"]:
                ocorrencias[aresta] = ocorrencias.get(aresta, 0)+1

        incorretas = {
            aresta: quantidade
            for aresta, quantidade in ocorrencias.items()
            if quantidade != 2
        }

        if incorretas:
            raise ValueError(
                "Num diagrama PD fechado, cada rótulo deve aparecer duas vezes. "
                f"Ocorrências inválidas: {incorretas}."
            )

        return cruzamentos

    @classmethod
    def matriz_inteira(cls, texto):
        dados = cls.literal(texto, "matriz")

        try:
            matriz = sp.Matrix([
                [int(valor) for valor in linha]
                for linha in dados
            ])
        except (TypeError, ValueError) as erro:
            raise ValueError("A matriz deve conter inteiros.") from erro

        if matriz.rows == 0 or matriz.cols == 0:
            raise ValueError("A matriz deve ser não vazia.")

        return matriz


class FerramentasNosPSF:
    """Operações combinatórias em códigos e diagramas de nós."""

    @staticmethod
    def canonizar_gauss(codigo):
        def renomear(sequencia):
            mapa = {}
            proximo = 1
            saida = []

            for valor in sequencia:
                absoluto = abs(valor)

                if absoluto not in mapa:
                    mapa[absoluto] = proximo
                    proximo += 1

                novo = mapa[absoluto]
                saida.append(novo if valor > 0 else -novo)

            return tuple(saida)

        variantes = []
        bases = (codigo, list(reversed(codigo)))

        for base in bases:
            for deslocamento in range(len(base)):
                rotacao = base[deslocamento:]+base[:deslocamento]
                variantes.append(renomear(rotacao))

        return min(variantes)

    @staticmethod
    def validar_gauss(codigo):
        contagens = {}
        sinais = {}

        for valor in codigo:
            absoluto = abs(valor)
            contagens[absoluto] = contagens.get(absoluto, 0)+1
            sinais.setdefault(absoluto, []).append(1 if valor > 0 else -1)

        duas_ocorrencias = all(v == 2 for v in contagens.values())
        sinais_opostos = all(
            sorted(valores) == [-1, 1]
            for valores in sinais.values()
        )

        return {
            "comprimento": len(codigo),
            "cruzamentos_rotulados": len(contagens),
            "cada_rótulo_duas_vezes": duas_ocorrencias,
            "um_sinal_de_cada_tipo": sinais_opostos,
            "código_formalmente_válido": (
                duas_ocorrencias and sinais_opostos
            ),
        }

    @staticmethod
    def posto_modulo(matriz, modulo):
        a = np.asarray(matriz, dtype=int) % modulo

        if a.size == 0:
            return 0

        linhas, colunas = a.shape
        posto = 0

        for coluna in range(colunas):
            pivot = next(
                (
                    linha
                    for linha in range(posto, linhas)
                    if math.gcd(int(a[linha, coluna]), modulo) == 1
                ),
                None,
            )

            if pivot is None:
                continue

            a[[posto, pivot]] = a[[pivot, posto]]
            inverso = pow(int(a[posto, coluna]), -1, modulo)
            a[posto] = (a[posto]*inverso) % modulo

            for linha in range(linhas):
                if linha != posto and a[linha, coluna] % modulo:
                    fator = int(a[linha, coluna])
                    a[linha] = (a[linha]-fator*a[posto]) % modulo

            posto += 1

            if posto == linhas:
                break

        return posto

    @staticmethod
    def numero_lacos_pd(cruzamentos, estado):
        rotulos = sorted({
            aresta
            for cruzamento in cruzamentos
            for aresta in cruzamento["arestas"]
        })
        pai = {rotulo: rotulo for rotulo in rotulos}

        def encontrar(x):
            while pai[x] != x:
                pai[x] = pai[pai[x]]
                x = pai[x]
            return x

        def unir(a, b):
            ra = encontrar(a)
            rb = encontrar(b)

            if ra != rb:
                pai[rb] = ra

        for bit, cruzamento in zip(estado, cruzamentos):
            a, b, c, d = cruzamento["arestas"]

            if bit == 0:
                unir(a, b)
                unir(c, d)
            else:
                unir(a, d)
                unir(b, c)

        return len({encontrar(rotulo) for rotulo in rotulos})

    @staticmethod
    def invariantes_smith(matriz):
        smith = smith_normal_form(matriz, domain=sp.ZZ)
        diagonal = [
            abs(int(smith[i, i]))
            for i in range(min(smith.rows, smith.cols))
            if smith[i, i] != 0
        ]
        posto = len(diagonal)
        livre = matriz.cols-posto
        torsao = [valor for valor in diagonal if valor > 1]

        return {
            "forma_smith": smith.tolist(),
            "posto": posto,
            "posto_livre": livre,
            "fatores_torsão": torsao,
            "grupo": (
                ["Z"]*livre
                + [f"Z/{valor}Z" for valor in torsao]
                or ["0"]
            ),
        }


class MotorNosDefinicaoEquivalenciaPSF:
    """Validação de códigos de Gauss e equivalência combinatória básica."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        analisar = re.fullmatch(
            r"no\s+gauss\s+analisar\s+(.+)",
            texto,
        )

        if analisar:
            try:
                codigo = ParserNosVariedadesPSF.gauss(analisar.group(1))
            except ValueError as erro:
                return {"erro": str(erro)}

            validacao = FerramentasNosPSF.validar_gauss(codigo)
            canonico = FerramentasNosPSF.canonizar_gauss(codigo)

            return {
                "tipo": "código combinatório de nó",
                "dados": {"código_Gauss": codigo},
                "pedido": "Validar e canonizar a representação fornecida",
                "formula": (
                    "cada cruzamento aparece exatamente duas vezes, "
                    "uma com cada sinal"
                ),
                "passos": [
                    f"Contamos {validacao['cruzamentos_rotulados']} rótulos.",
                    (
                        "Verificamos duas ocorrências por rótulo: "
                        f"{validacao['cada_rótulo_duas_vezes']}."
                    ),
                    (
                        "Verificamos sinais opostos: "
                        f"{validacao['um_sinal_de_cada_tipo']}."
                    ),
                    (
                        "Canonizamos por rotações, inversão da orientação "
                        "de percurso e renumeração pela primeira ocorrência."
                    ),
                ],
                "resultado": {
                    **validacao,
                    "forma_canônica_limitada": canonico,
                },
                "verificacao": (
                    "A forma canônica é invariável sob as transformações "
                    "combinatórias implementadas."
                ),
                "observacao": (
                    "Um código formalmente válido e a canonização usada não "
                    "substituem um algoritmo completo de equivalência de nós."
                ),
            }

        equivalencia = re.fullmatch(
            r"no\s+gauss\s+equivalencia\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not equivalencia:
            return None

        try:
            primeiro = ParserNosVariedadesPSF.gauss(equivalencia.group(1))
            segundo = ParserNosVariedadesPSF.gauss(equivalencia.group(2))
        except ValueError as erro:
            return {"erro": str(erro)}

        v1 = FerramentasNosPSF.validar_gauss(primeiro)
        v2 = FerramentasNosPSF.validar_gauss(segundo)

        if not v1["código_formalmente_válido"] or not v2["código_formalmente_válido"]:
            return {"erro": "Um dos códigos não satisfaz a validação formal."}

        c1 = FerramentasNosPSF.canonizar_gauss(primeiro)
        c2 = FerramentasNosPSF.canonizar_gauss(segundo)
        iguais = c1 == c2

        return {
            "tipo": "equivalência combinatória limitada de nós",
            "dados": {"primeiro": primeiro, "segundo": segundo},
            "pedido": "Comparar as representações sob as transformações implementadas",
            "formula": "comparar formas canônicas dos códigos",
            "passos": [
                f"Forma canônica do primeiro: {c1}.",
                f"Forma canônica do segundo: {c2}.",
                f"As formas {'coincidem' if iguais else 'não coincidem'}.",
            ],
            "resultado": {
                "equivalentes_neste_teste": iguais,
                "equivalência_topológica_completa": (
                    True if iguais else "não determinado"
                ),
            },
            "verificacao": (
                "A coincidência prova equivalência pelas transformações usadas."
                if iguais
                else "A diferença não prova que os nós sejam inequivalentes."
            ),
            "justificacao": (
                None
                if iguais
                else (
                    "O teste considera apenas rotações do percurso, reversão "
                    "e renumeração. Dois diagramas topologicamente equivalentes "
                    "podem exigir movimentos de Reidemeister que alteram o código; "
                    "por isso a equivalência completa fica não determinada."
                )
            ),
        }


class MotorInvariantesNosPSF:
    """Número de cruzamentos do diagrama e tricolorabilidade de Fox."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"no\s+tricolorabilidade\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            cruzamentos = ParserNosVariedadesPSF.literal(
                padrao.group(1),
                "cruzamentos",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(cruzamentos, (list, tuple)) or not cruzamentos:
            return {"erro": "Forneça uma lista não vazia de cruzamentos."}

        normalizados = []

        try:
            for item in cruzamentos:
                if not isinstance(item, (list, tuple)) or len(item) != 3:
                    raise ValueError(
                        "Cada cruzamento deve ser (arco_sobre, arco_baixo_1, arco_baixo_2)."
                    )

                normalizados.append(tuple(int(v) for v in item))
        except (TypeError, ValueError) as erro:
            return {"erro": str(erro)}

        arcos = sorted({
            arco
            for cruzamento in normalizados
            for arco in cruzamento
        })
        indice = {arco: i for i, arco in enumerate(arcos)}
        matriz = np.zeros(
            (len(normalizados), len(arcos)),
            dtype=int,
        )

        for linha, (sobre, baixo1, baixo2) in enumerate(normalizados):
            matriz[linha, indice[sobre]] += 2
            matriz[linha, indice[baixo1]] -= 1
            matriz[linha, indice[baixo2]] -= 1

        matriz %= 3
        posto = FerramentasNosPSF.posto_modulo(matriz, 3)
        dimensao_nucleo = len(arcos)-posto
        coloracoes = 3**dimensao_nucleo
        nao_triviais = coloracoes-3 if dimensao_nucleo >= 1 else coloracoes
        tricoloravel = nao_triviais > 0

        exemplos = []

        if len(arcos) <= 12:
            for cores in itertools.product(range(3), repeat=len(arcos)):
                vetor = np.asarray(cores, dtype=int)

                if np.all((matriz@vetor) % 3 == 0) and len(set(cores)) > 1:
                    exemplos.append({
                        arco: int(cor)
                        for arco, cor in zip(arcos, cores)
                    })

                    if len(exemplos) >= 20:
                        break

        return {
            "tipo": "invariantes combinatórios de diagrama de nó",
            "dados": {
                "cruzamentos": normalizados,
                "arcos": arcos,
            },
            "pedido": "Contar cruzamentos do diagrama e testar tricolorabilidade",
            "formula": "2c_sobre−c_baixo1−c_baixo2≡0 (mod 3)",
            "passos": [
                f"O diagrama recebido possui {len(normalizados)} cruzamentos.",
                f"Matriz das restrições módulo 3: {matriz.tolist()}.",
                f"Posto módulo 3: {posto}.",
                f"Dimensão do núcleo: {dimensao_nucleo}.",
                f"Quantidade total de soluções: {coloracoes}.",
                f"Colorações não constantes: {nao_triviais}.",
            ],
            "resultado": {
                "número_cruzamentos_do_diagrama": len(normalizados),
                "número_cruzamentos_mínimo_do_nó": "não determinado",
                "tricolorável": tricoloravel,
                "colorações_totais": coloracoes,
                "colorações_não_triviais": nao_triviais,
                "exemplos": exemplos,
            },
            "verificacao": (
                "Cada exemplo satisfaz todas as congruências módulo 3."
            ),
            "justificacao": (
                "A entrada fornece um diagrama específico. Contar os seus "
                "cruzamentos não prova que essa quantidade seja mínima entre "
                "todos os diagramas equivalentes do mesmo nó; portanto o "
                "número de cruzamentos do nó permanece não determinado."
            ),
        }


class MotorPolinomioJonesPSF:
    """Polinômio de Jones por soma de estados do colchete de Kauffman."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"jones\s+pd\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            cruzamentos = ParserNosVariedadesPSF.pd(padrao.group(1))
        except ValueError as erro:
            return {"erro": str(erro)}

        quantidade = len(cruzamentos)

        if quantidade > 20:
            return {
                "erro": (
                    "A soma exata de estados está limitada a 20 cruzamentos "
                    "(2^20 estados)."
                )
            }

        a = sp.Symbol("A", nonzero=True)
        t = sp.Symbol("t", positive=True)
        delta = -a**2-a**-2
        bracket = 0
        distribuicao_lacos = {}
        termos = []

        for estado in itertools.product((0, 1), repeat=quantidade):
            a_suavizacoes = estado.count(0)
            b_suavizacoes = quantidade-a_suavizacoes
            lacos = FerramentasNosPSF.numero_lacos_pd(
                cruzamentos,
                estado,
            )
            termo = a**(a_suavizacoes-b_suavizacoes)*delta**(lacos-1)
            bracket += termo
            distribuicao_lacos[lacos] = distribuicao_lacos.get(lacos, 0)+1

            if len(termos) < 100:
                termos.append({
                    "estado": estado,
                    "A": a_suavizacoes,
                    "B": b_suavizacoes,
                    "laços": lacos,
                    "termo": sp.sstr(termo),
                })

        bracket = sp.expand(bracket)
        writhe = sum(
            cruzamento["sinal"]
            for cruzamento in cruzamentos
        )
        normalizado_a = sp.expand(
            (-a)**(-3*writhe)*bracket
        )
        jones_t = sp.simplify(
            normalizado_a.subs(a, t**sp.Rational(-1, 4))
        )

        return {
            "tipo": "polinômio de Jones por diagrama PD",
            "dados": {
                "cruzamentos": quantidade,
                "writhe": writhe,
                "estados": 2**quantidade,
            },
            "pedido": "Calcular o colchete de Kauffman e normalizar pela orientação",
            "formula": (
                "<D>=Σ_s A^{a(s)−b(s)}(−A²−A⁻²)^{|s|−1}; "
                "V(t)=(-A)^{-3w(D)}<D>, A=t^{-1/4}"
            ),
            "passos": [
                f"Enumeramos {2**quantidade} estados de suavização.",
                f"Distribuição da quantidade de laços: {distribuicao_lacos}.",
                f"Primeiros termos da soma: {termos}.",
                f"Colchete expandido: {sp.sstr(bracket)}.",
                f"Writhe do diagrama: {writhe}.",
                f"Normalização em A: {sp.sstr(normalizado_a)}.",
            ],
            "resultado": {
                "colchete_Kauffman_A": sp.sstr(bracket),
                "Jones_em_A": sp.sstr(normalizado_a),
                "Jones_em_t": sp.sstr(jones_t),
            },
            "verificacao": (
                "O valor foi reconstruído pela soma completa dos estados "
                "do diagrama fornecido."
            ),
            "observacao": (
                "A convenção de orientação e a ordem das quatro arestas "
                "de cada cruzamento devem seguir o formato PD declarado."
            ),
        }


class MotorPolinomioAlexanderPSF:
    """Polinômio de Alexander calculado a partir de matriz de Seifert."""

    @staticmethod
    def normalizar_laurent(expressao, variavel):
        expressao = sp.expand(expressao)

        if expressao == 0:
            return sp.Integer(0)

        termos = sp.Add.make_args(expressao)
        expoentes = []

        for termo in termos:
            expoentes.append(
                int(termo.as_powers_dict().get(variavel, 0))
            )

        minimo = min(expoentes)
        normalizado = sp.expand(
            expressao*variavel**(-minimo)
        )
        polinomio = sp.Poly(normalizado, variavel)

        if polinomio.LC() < 0:
            normalizado = -normalizado

        return sp.expand(normalizado)

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"alexander\s+seifert\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            v = ParserNosVariedadesPSF.matriz_inteira(padrao.group(1))
        except ValueError as erro:
            return {"erro": str(erro)}

        if v.rows != v.cols:
            return {"erro": "A matriz de Seifert deve ser quadrada."}

        t = sp.Symbol("t", nonzero=True)
        matriz_alexander = v-t*v.T
        determinante = sp.expand(matriz_alexander.det())
        normalizado = self.normalizar_laurent(
            determinante,
            t,
        )
        valor_um = sp.simplify(normalizado.subs(t, 1))
        reciproco = sp.expand(
            t**sp.degree(normalizado, t)
            * normalizado.subs(t, 1/t)
        ) if normalizado != 0 else 0
        simetrico_ate_sinal = bool(
            sp.simplify(reciproco-normalizado) == 0
            or sp.simplify(reciproco+normalizado) == 0
        )

        return {
            "tipo": "polinômio de Alexander",
            "dados": {
                "matriz_Seifert": v.tolist(),
                "ordem": v.rows,
            },
            "pedido": "Calcular det(V−tVᵀ) e normalizar por unidades ±t^k",
            "formula": "Δ_K(t) ≍ det(V−tVᵀ)",
            "passos": [
                f"V−tVᵀ={matriz_alexander.tolist()}.",
                f"Determinante bruto: {sp.sstr(determinante)}.",
                f"Normalização escolhida: {sp.sstr(normalizado)}.",
                f"Δ(1)={sp.sstr(valor_um)}.",
            ],
            "resultado": {
                "Alexander": sp.sstr(normalizado),
                "determinante_bruto": sp.sstr(determinante),
                "valor_em_1": sp.sstr(valor_um),
                "simetria_recíproca_até_sinal": simetrico_ate_sinal,
            },
            "verificacao": (
                "A normalização altera apenas por uma unidade ±t^k."
            ),
        }


class MotorHomologiaKhovanovPSF:
    """Homologia de um complexo graduado sobre GF(2), fornecido externamente."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"khovanov\s+gf2\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserNosVariedadesPSF.literal(
                padrao.group(1),
                "complexo de cadeias",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {"erro": "Forneça {'dimensões':{i:n}, 'diferenciais':{i:matriz}}."}

        dimensoes_brutas = (
            dados.get("dimensoes")
            or dados.get("dimensões")
            or dados.get("dims")
        )
        diferenciais_brutos = (
            dados.get("diferenciais")
            or dados.get("d")
            or {}
        )

        if not isinstance(dimensoes_brutas, dict):
            return {"erro": "As dimensões dos grupos de cadeias são obrigatórias."}

        try:
            dimensoes = {
                int(grau): int(dim)
                for grau, dim in dimensoes_brutas.items()
            }
        except (TypeError, ValueError):
            return {"erro": "Graus e dimensões devem ser inteiros."}

        if any(dim < 0 for dim in dimensoes.values()):
            return {"erro": "Dimensões não podem ser negativas."}

        diferenciais = {}
        postos = {}

        for grau_bruto, matriz_bruta in diferenciais_brutos.items():
            grau = int(grau_bruto)
            matriz = np.asarray(matriz_bruta, dtype=int) % 2
            esperado = (
                dimensoes.get(grau+1, 0),
                dimensoes.get(grau, 0),
            )

            if matriz.shape != esperado:
                return {
                    "erro": (
                        f"d_{grau} deve possuir forma {esperado}, "
                        f"mas recebeu {matriz.shape}."
                    )
                }

            diferenciais[grau] = matriz
            postos[grau] = FerramentasNosPSF.posto_modulo(
                matriz,
                2,
            )

        falhas_complexo = []

        for grau, matriz in diferenciais.items():
            seguinte = diferenciais.get(grau+1)

            if seguinte is None:
                continue

            produto = (seguinte@matriz) % 2

            if np.any(produto):
                falhas_complexo.append({
                    "grau": grau,
                    "d_{i+1}d_i": produto.tolist(),
                })

        if falhas_complexo:
            return {
                "erro": (
                    "As matrizes não formam um complexo: "
                    f"{falhas_complexo}."
                )
            }

        homologia = {}

        for grau in sorted(dimensoes):
            dim_c = dimensoes[grau]
            rank_saida = postos.get(grau, 0)
            rank_entrada = postos.get(grau-1, 0)
            dim_h = dim_c-rank_saida-rank_entrada

            if dim_h < 0:
                return {
                    "erro": (
                        f"Dimensão de homologia negativa no grau {grau}; "
                        "revise as matrizes."
                    )
                }

            homologia[grau] = {
                "dim_C": dim_c,
                "rank_d_saida": rank_saida,
                "rank_d_entrada": rank_entrada,
                "dim_H": dim_h,
            }

        euler_cadeias = sum(
            (-1)**grau*dimensoes[grau]
            for grau in dimensoes
        )
        euler_homologia = sum(
            (-1)**grau*valor["dim_H"]
            for grau, valor in homologia.items()
        )

        return {
            "tipo": "homologia de complexo do tipo Khovanov sobre GF(2)",
            "dados": {
                "dimensões_cadeias": dimensoes,
                "diferenciais_fornecidos": sorted(diferenciais),
            },
            "pedido": "Calcular ker(d_i)/im(d_{i−1}) em cada grau",
            "formula": "dim H_i=dim C_i−rank d_i−rank d_{i−1}",
            "passos": [
                "Reduzimos cada diferencial módulo 2.",
                "Verificamos d_{i+1}∘d_i=0.",
                f"Postos dos diferenciais: {postos}.",
                f"Dimensões calculadas: {homologia}.",
            ],
            "resultado": {
                "homologia": homologia,
                "característica_Euler_cadeias": euler_cadeias,
                "característica_Euler_homologia": euler_homologia,
            },
            "verificacao": {
                "complexo_válido": True,
                "Euler_preservada": euler_cadeias == euler_homologia,
            },
            "observacao": (
                "A calculadora recebe o complexo já construído. A geração "
                "automática do complexo bigraduado a partir de um diagrama "
                "não está implícita nesta operação."
            ),
        }


class MotorHeegaardPSF:
    """Homologia de primeira ordem a partir da matriz de interseção de Heegaard."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"heegaard\s+(\d+)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        genero = int(padrao.group(1))

        try:
            matriz = ParserNosVariedadesPSF.matriz_inteira(
                padrao.group(2)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if genero < 0:
            return {"erro": "O gênero não pode ser negativo."}
        if matriz.rows != genero or matriz.cols != genero:
            return {
                "erro": (
                    f"A matriz de apresentação deve possuir forma "
                    f"{genero}×{genero}."
                )
            }

        invariantes = FerramentasNosPSF.invariantes_smith(matriz)
        determinante = int(matriz.det())
        esfera_homologica = (
            invariantes["posto_livre"] == 0
            and not invariantes["fatores_torsão"]
        )

        return {
            "tipo": "decomposição de Heegaard",
            "dados": {
                "gênero": genero,
                "matriz_interseção": matriz.tolist(),
            },
            "pedido": "Calcular invariantes homológicos da apresentação",
            "formula": "H₁(M;Z)=coker(A)=Z^g/AZ^g",
            "passos": [
                f"A superfície de Heegaard possui χ=2−2g={2-2*genero}.",
                f"det(A)={determinante}.",
                f"Forma normal de Smith: {invariantes['forma_smith']}.",
                f"Decomposição de H₁: {invariantes['grupo']}.",
            ],
            "resultado": {
                "Euler_superfície": 2-2*genero,
                "determinante_apresentação": determinante,
                "H1": invariantes["grupo"],
                "posto_livre_H1": invariantes["posto_livre"],
                "torsão_H1": invariantes["fatores_torsão"],
                "esfera_homológica_inteira": esfera_homologica,
            },
            "verificacao": (
                "A forma de Smith preserva o módulo apresentado pela matriz."
            ),
            "observacao": (
                "H₁ e o gênero da apresentação não classificam sozinhos "
                "uma 3-variedade."
            ),
        }


class MotorCirurgiaDehnPSF:
    """Homologia de cirurgias inteiras e racionais em um componente."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        racional = re.fullmatch(
            r"cirurgia\s+dehn\s+racional\s+"
            r"([+-]?\d+)\s*/\s*([+-]?\d+)",
            texto,
        )

        if racional:
            p = int(racional.group(1))
            q = int(racional.group(2))

            if q == 0:
                return {"erro": "O denominador q não pode ser zero."}

            divisor = math.gcd(p, q)
            p_reduzido = p//divisor
            q_reduzido = q//divisor

            if p_reduzido == 0:
                h1 = ["Z"]
            elif abs(p_reduzido) == 1:
                h1 = ["0"]
            else:
                h1 = [f"Z/{abs(p_reduzido)}Z"]

            return {
                "tipo": "cirurgia de Dehn racional em um nó",
                "dados": {
                    "inclinação_original": f"{p}/{q}",
                    "inclinação_reduzida": f"{p_reduzido}/{q_reduzido}",
                },
                "pedido": "Calcular H₁ da variedade obtida pela cirurgia",
                "formula": "H₁(M_{p/q}(K);Z)≅Z/|p|Z para p≠0; p=0 dá Z",
                "passos": [
                    f"Reduzimos a inclinação por mdc({p},{q})={divisor}.",
                    f"O coeficiente meridional reduzido é p={p_reduzido}.",
                    f"Logo, H₁={h1}.",
                ],
                "resultado": {"H1": h1},
                "verificacao": (
                    "A homologia depende do numerador reduzido da inclinação."
                ),
            }

        link = re.fullmatch(
            r"cirurgia\s+dehn\s+link\s+(.+)",
            texto,
        )

        if not link:
            return None

        try:
            matriz = ParserNosVariedadesPSF.matriz_inteira(
                link.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if matriz.rows != matriz.cols:
            return {"erro": "A matriz de cirurgia deve ser quadrada."}
        if matriz != matriz.T:
            return {
                "erro": (
                    "A matriz de enquadramentos e linking deve ser simétrica."
                )
            }

        invariantes = FerramentasNosPSF.invariantes_smith(matriz)
        determinante = int(matriz.det())

        return {
            "tipo": "cirurgia inteira em link enquadrado",
            "dados": {"matriz_cirurgia": matriz.tolist()},
            "pedido": "Calcular a homologia apresentada pela matriz de cirurgia",
            "formula": "H₁(M;Z)=coker(L)",
            "passos": [
                "Usamos a diagonal para os enquadramentos.",
                "Usamos os termos fora da diagonal para linking numbers.",
                f"Forma de Smith: {invariantes['forma_smith']}.",
                f"det(L)={determinante}.",
            ],
            "resultado": {
                "H1": invariantes["grupo"],
                "posto_livre": invariantes["posto_livre"],
                "torsão": invariantes["fatores_torsão"],
                "determinante": determinante,
                "esfera_homológica": (
                    invariantes["posto_livre"] == 0
                    and not invariantes["fatores_torsão"]
                ),
            },
            "verificacao": (
                "A decomposição resulta da apresentação abeliana dada por L."
            ),
        }


class MotorHiperbolizacaoThurstonPSF:
    """Equações de colagem e volume de tetraedros ideais."""

    @staticmethod
    def bloch_wigner(z):
        z = mp.mpc(z)
        return mp.im(mp.polylog(2, z))+mp.arg(1-z)*mp.log(abs(z))

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"hiperbolizacao\s+formas\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            formas_brutas = ParserNosVariedadesPSF.literal(
                padrao.group(1),
                "formas",
            )
            equacoes = ParserNosVariedadesPSF.literal(
                padrao.group(2),
                "equações de colagem",
            )
            formas = [complex(valor) for valor in formas_brutas]
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if not formas:
            return {"erro": "Forneça ao menos uma forma tetraédrica."}
        if any(
            abs(z) < 1e-14 or abs(z-1) < 1e-14 or z.imag <= 0
            for z in formas
        ):
            return {
                "erro": (
                    "Cada forma deve estar no semiplano superior e ser "
                    "diferente de 0 e 1."
                )
            }

        if not isinstance(equacoes, (list, tuple)):
            return {"erro": "As equações devem formar uma lista."}

        residuos = []

        for indice_eq, equacao in enumerate(equacoes):
            if not isinstance(equacao, (list, tuple)) or len(equacao) != len(formas):
                return {
                    "erro": (
                        "Cada equação deve fornecer um par de expoentes "
                        "(a_i,b_i) por tetraedro."
                    )
                }

            produto = 1+0j

            for z, expoentes in zip(formas, equacao):
                if not isinstance(expoentes, (list, tuple)) or len(expoentes) != 2:
                    return {"erro": "Use expoentes (a,b) para z^a(1−z)^b."}

                a_exp = int(expoentes[0])
                b_exp = int(expoentes[1])
                produto *= z**a_exp*(1-z)**b_exp

            residuos.append({
                "equação": indice_eq,
                "produto": produto,
                "erro_para_1": abs(produto-1),
            })

        volumes = [
            float(self.bloch_wigner(z))
            for z in formas
        ]
        volume_total = float(sum(volumes))
        max_erro = max(
            (item["erro_para_1"] for item in residuos),
            default=0.0,
        )
        colagem = max_erro < 1e-8

        return {
            "tipo": "teste de estrutura hiperbólica ideal",
            "dados": {
                "formas": formas,
                "tetraedros": len(formas),
                "equações": len(equacoes),
            },
            "pedido": "Verificar equações de colagem e somar volumes",
            "formula": (
                "∏z_i^{a_i}(1−z_i)^{b_i}=1; "
                "Vol(M)=ΣD(z_i)"
            ),
            "passos": [
                f"Resíduos das equações de colagem: {residuos}.",
                f"Volumes de Bloch–Wigner: {volumes}.",
                f"Volume total orientado: {volume_total}.",
            ],
            "resultado": {
                "equações_satisfeitas_numericamente": colagem,
                "erro_máximo_colagem": max_erro,
                "volume_total": volume_total,
                "volumes_tetraedros": volumes,
                "hiperbolização_completa": (
                    "não determinado"
                ),
            },
            "verificacao": (
                "As equações fornecidas foram avaliadas numericamente."
            ),
            "justificacao": (
                "Satisfazer numericamente as equações fornecidas é evidência "
                "de uma estrutura ideal, mas não verifica automaticamente "
                "completude, compatibilidade de todas as cúspides, topologia "
                "da triangulação e ausência de degenerações. Por isso a "
                "hiperbolização completa fica não determinada."
            ),
        }


class MotorGeometrizacaoPSF:
    """Triagem de geometrias de Thurston a partir de invariantes fornecidos."""

    GEOMETRIAS = (
        "S3",
        "E3",
        "H3",
        "S2xR",
        "H2xR",
        "Nil",
        "Sol",
        "SL2R",
    )

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"geometrizacao\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserNosVariedadesPSF.literal(
                padrao.group(1),
                "invariantes",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {"erro": "Forneça os invariantes num dicionário."}

        candidatos = set(self.GEOMETRIAS)
        motivos = []

        if dados.get("hiperbolica") is True or dados.get("volume_hiperbolico", 0) > 0:
            candidatos &= {"H3"}
            motivos.append("Volume/estrutura hiperbólica indicada.")

        if dados.get("grupo_fundamental_finito") is True:
            candidatos &= {"S3"}
            motivos.append("Grupo fundamental finito favorece geometria esférica.")

        if dados.get("plana") is True or dados.get("euclidiana") is True:
            candidatos &= {"E3"}
            motivos.append("Estrutura euclidiana declarada.")

        if dados.get("seifert") is True:
            candidatos &= {"S3", "S2xR", "E3", "H2xR", "Nil", "SL2R"}
            motivos.append("Estrutura de Seifert exclui tipicamente H3 e Sol.")

        if dados.get("solv") is True or dados.get("torus_bundle_hiperbolico") is True:
            candidatos &= {"Sol"}
            motivos.append("Fibrado de toro hiperbólico/estrutura solvável.")

        if dados.get("nilpotente") is True:
            candidatos &= {"Nil"}
            motivos.append("Estrutura nilpotente indicada.")

        if dados.get("base_orbifold_euler") is not None:
            chi = float(dados["base_orbifold_euler"])
            euler_number = float(dados.get("euler_fibration", 0))

            if chi > 0:
                candidatos &= {"S3", "S2xR"}
            elif abs(chi) < 1e-12:
                candidatos &= {"E3", "Nil"}
            else:
                candidatos &= {"H2xR", "SL2R"}

            if abs(euler_number) > 1e-12:
                candidatos -= {"S2xR", "E3", "H2xR"}

            motivos.append(
                f"χ_orb={chi} e número de Euler={euler_number}."
            )

        candidatos = sorted(candidatos)

        if len(candidatos) == 1:
            classificacao = candidatos[0]
            justificacao = None
        else:
            classificacao = "não determinado"
            justificacao = (
                "Os invariantes fornecidos não selecionam uma única geometria "
                "entre as oito de Thurston. A geometrização exige decompor a "
                "3-variedade em peças primas e tori incompressíveis e verificar "
                "invariantes adicionais de cada peça."
            )

        return {
            "tipo": "triagem pela Geometrização",
            "dados": dados,
            "pedido": "Restringir as geometrias de Thurston compatíveis",
            "formula": "classificação por invariantes topológicos e estruturas geométricas",
            "passos": [
                f"Começamos com as oito geometrias: {list(self.GEOMETRIAS)}.",
                *motivos,
                f"Candidatos restantes: {candidatos}.",
            ],
            "resultado": {
                "geometria": classificacao,
                "candidatos": candidatos,
            },
            "verificacao": (
                "Cada filtro aplicado corresponde a um invariante fornecido."
            ),
            "justificacao": justificacao,
            "observacao": (
                "A Conjectura da Geometrização foi demonstrada no trabalho "
                "de Perelman; esta operação apenas classifica dados de entrada."
            ),
        }


class MotorNosBiologiaPSF:
    """Topologia de DNA pela relação de Călugăreanu–White–Fuller."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        calcular = re.fullmatch(
            r"dna\s+topologia\s+"
            r"(lk|tw|wr)\s*=\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"(lk|tw|wr)\s*=\s*([+-]?[0-9.eE]+)",
            texto,
        )

        if calcular:
            primeira = calcular.group(1)
            segunda = calcular.group(3)

            if primeira == segunda:
                return {"erro": "Forneça duas grandezas diferentes."}

            valores = {
                primeira: float(calcular.group(2)),
                segunda: float(calcular.group(4)),
            }
            faltante = ({"lk", "tw", "wr"}-set(valores)).pop()

            if faltante == "lk":
                valores["lk"] = valores["tw"]+valores["wr"]
                substituicao = f"Lk={valores['tw']}+{valores['wr']}"
            elif faltante == "tw":
                valores["tw"] = valores["lk"]-valores["wr"]
                substituicao = f"Tw={valores['lk']}−{valores['wr']}"
            else:
                valores["wr"] = valores["lk"]-valores["tw"]
                substituicao = f"Wr={valores['lk']}−{valores['tw']}"

            return {
                "tipo": "topologia de DNA circular",
                "dados": {
                    primeira.upper(): valores[primeira],
                    segunda.upper(): valores[segunda],
                },
                "pedido": f"Calcular {faltante.upper()}",
                "formula": "Lk = Tw + Wr",
                "passos": [
                    (
                        "Usamos a decomposição do número de ligação em "
                        "torção e writhe."
                    ),
                    f"Isolando a incógnita: {substituicao}.",
                    f"{faltante.upper()}={valores[faltante]}.",
                ],
                "resultado": {
                    "Lk": valores["lk"],
                    "Tw": valores["tw"],
                    "Wr": valores["wr"],
                },
                "verificacao": (
                    f"{valores['tw']}+{valores['wr']}={valores['lk']}."
                ),
                "observacao": (
                    "A relação descreve uma curva fechada com fita/framing; "
                    "a interpretação biológica depende do modelo molecular."
                ),
            }

        topo = re.fullmatch(
            r"dna\s+topoisomerase\s+"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)",
            texto,
        )

        if not topo:
            return None

        lk_inicial = float(topo.group(1))
        delta = float(topo.group(2))
        lk_final = lk_inicial+delta

        return {
            "tipo": "alteração topológica por topoisomerase",
            "dados": {
                "Lk_inicial": lk_inicial,
                "ΔLk": delta,
            },
            "pedido": "Calcular o número de ligação após a alteração",
            "formula": "Lk_final=Lk_inicial+ΔLk",
            "passos": [
                f"Lk_final={lk_inicial}+({delta}).",
                f"Lk_final={lk_final}.",
            ],
            "resultado": {"Lk_final": lk_final},
            "verificacao": (
                f"Lk_final−Lk_inicial={lk_final-lk_inicial}=ΔLk."
            ),
        }



class ParserDinamicaPSF:
    """Expressões seguras para mapas, fluxos e modelos dinâmicos."""

    x = sp.Symbol("x", real=True)
    mu = sp.Symbol("mu", real=True)
    t = sp.Symbol("t", real=True)

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @staticmethod
    def _validar_texto(texto):
        expressao = texto.strip().replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            raise ValueError("Expressão contém símbolos não permitidos.")

        return expressao

    @classmethod
    def expressao_mapa(cls, texto, parametros=None):
        expressao = cls._validar_texto(texto)
        parametros = parametros or {}
        simbolos_parametros = {
            nome: sp.Symbol(nome, real=True)
            for nome in parametros
        }
        locais = {
            "x": cls.x,
            "mu": cls.mu,
            "sin": sp.sin,
            "sen": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "abs": sp.Abs,
            "pi": sp.pi,
            "e": sp.E,
            **simbolos_parametros,
        }

        try:
            expr = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            raise ValueError("Expressão dinâmica inválida.") from erro

        substituicoes = {
            simbolos_parametros[nome]: float(valor)
            for nome, valor in parametros.items()
        }
        expr = sp.simplify(expr.subs(substituicoes))

        if expr.free_symbols - {cls.x, cls.mu}:
            raise ValueError(
                "Após substituir parâmetros, só podem restar x e mu."
            )

        return expr

    @classmethod
    def funcao_x(cls, texto, parametros=None):
        expr = cls.expressao_mapa(texto, parametros)

        if cls.mu in expr.free_symbols:
            raise ValueError("O parâmetro mu precisa receber um valor.")

        return expr, sp.lambdify(cls.x, expr, modules=["numpy"])

    @classmethod
    def observavel_x(cls, texto):
        expr = cls.expressao_mapa(texto, {})

        if cls.mu in expr.free_symbols:
            raise ValueError("O observável não pode depender de mu.")

        return expr, sp.lambdify(cls.x, expr, modules=["numpy"])

    @classmethod
    def sistema(cls, expressoes_texto):
        dados = cls.literal(expressoes_texto, "sistema")

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("O sistema deve ser uma lista de expressões.")

        simbolos = sp.symbols(
            " ".join(f"x{i}" for i in range(len(dados))),
            real=True,
        )

        if len(dados) == 1:
            simbolos = (simbolos,)

        locais = {
            "t": cls.t,
            "sin": sp.sin,
            "sen": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "abs": sp.Abs,
            "pi": sp.pi,
            "e": sp.E,
            **{
                str(simbolo): simbolo
                for simbolo in simbolos
            },
        }
        expressoes = []

        for texto in dados:
            expressao = cls._validar_texto(str(texto))

            try:
                expr = sp.sympify(expressao, locals=locais)
            except Exception as erro:
                raise ValueError(
                    f"Expressão de fluxo inválida: {texto}."
                ) from erro

            if expr.free_symbols - ({cls.t} | set(simbolos)):
                raise ValueError("O sistema contém variável desconhecida.")

            expressoes.append(expr)

        funcao = sp.lambdify(
            (cls.t, *simbolos),
            expressoes,
            modules=["numpy"],
        )
        return simbolos, expressoes, funcao


class MotorSistemasDinamicosDiscretosPSF:
    """Iteração explícita de mapas unidimensionais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"dinamica\s+discreta\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*(\d+)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        parametros = {}

        if padrao.group(4):
            try:
                parametros = ParserDinamicaPSF.literal(
                    padrao.group(4),
                    "parâmetros",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if not isinstance(parametros, dict):
                return {"erro": "Os parâmetros devem formar um dicionário."}

        try:
            expr, funcao = ParserDinamicaPSF.funcao_x(
                padrao.group(1),
                parametros,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        atual = float(padrao.group(2))
        iteracoes = int(padrao.group(3))

        if iteracoes < 1 or iteracoes > 2_000_000:
            return {"erro": "As iterações devem estar entre 1 e 2000000."}

        orbita = [atual]
        passos = []

        for indice in range(1, iteracoes+1):
            proximo = float(funcao(atual))

            if not np.isfinite(proximo):
                return {
                    "erro": (
                        f"A órbita tornou-se não finita na iteração {indice}."
                    )
                }

            if len(passos) < 500:
                passos.append(
                    f"x_{indice}=f(x_{indice-1})="
                    f"f({atual})={proximo}."
                )

            atual = proximo

            if len(orbita) < 10000:
                orbita.append(atual)

        cauda = np.asarray(
            orbita[-min(len(orbita), 1000):],
            dtype=float,
        )
        periodo_detectado = None
        tolerancia = 1e-9

        for periodo in range(1, min(100, len(cauda)//2)+1):
            if np.allclose(
                cauda[-periodo:],
                cauda[-2*periodo:-periodo],
                atol=tolerancia,
                rtol=0,
            ):
                periodo_detectado = periodo
                break

        return {
            "tipo": "sistema dinâmico discreto",
            "dados": {
                "mapa": sp.sstr(expr),
                "x0": float(padrao.group(2)),
                "iterações": iteracoes,
                "parâmetros": parametros,
            },
            "pedido": "Construir a órbita x_{n+1}=f(x_n)",
            "formula": "x_{n+1}=f(x_n)",
            "passos": passos,
            "resultado": {
                "valor_final": atual,
                "órbita_armazenada": orbita,
                "período_numérico_detectado": periodo_detectado,
                "mínimo_cauda": float(np.min(cauda)),
                "máximo_cauda": float(np.max(cauda)),
            },
            "verificacao": (
                "Cada termo armazenado foi obtido pela aplicação direta do mapa."
            ),
        }


class MotorPontosFixosEstabilidadePSF:
    """Pontos fixos e classificação local de mapas discretos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"pontos\s+fixos\s+(.+?)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        parametros = {}

        if padrao.group(2):
            try:
                parametros = ParserDinamicaPSF.literal(
                    padrao.group(2),
                    "parâmetros",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

        try:
            expr, _ = ParserDinamicaPSF.funcao_x(
                padrao.group(1),
                parametros,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        x = ParserDinamicaPSF.x
        equacao = sp.simplify(expr-x)

        try:
            solucoes = sp.solve(
                sp.Eq(expr, x),
                x,
            )
        except Exception:
            solucoes = []

        reais = []

        for solucao in solucoes:
            aproximacao = sp.N(solucao)

            if aproximacao.is_real is True:
                reais.append(sp.simplify(solucao))

        derivada = sp.diff(expr, x)
        classificacoes = []

        for ponto in reais:
            multiplicador = sp.simplify(
                derivada.subs(x, ponto)
            )
            valor_abs = abs(complex(sp.N(multiplicador)))

            if valor_abs < 1-1e-10:
                classe = "assintoticamente estável"
                justificacao = None
            elif valor_abs > 1+1e-10:
                classe = "instável"
                justificacao = None
            else:
                classe = "não determinado"
                justificacao = (
                    "O teste linear possui |f'(x*)|=1. Nesse caso, o termo "
                    "linear não decide a estabilidade e são necessários termos "
                    "de ordem superior ou análise direta da órbita."
                )

            classificacoes.append({
                "ponto": sp.sstr(ponto),
                "multiplicador": sp.sstr(multiplicador),
                "módulo": valor_abs,
                "estabilidade": classe,
                "justificação": justificacao,
            })

        possui_indeterminacao = any(
            item["estabilidade"] == "não determinado"
            for item in classificacoes
        )

        return {
            "tipo": "pontos fixos e estabilidade",
            "dados": {
                "mapa": sp.sstr(expr),
                "parâmetros": parametros,
            },
            "pedido": "Resolver f(x)=x e classificar cada solução",
            "formula": (
                "|f'(x*)|<1 estável; |f'(x*)|>1 instável; "
                "|f'(x*)|=1 exige análise superior"
            ),
            "passos": [
                f"Equação de ponto fixo: {sp.sstr(equacao)}=0.",
                f"Soluções reais encontradas: {[sp.sstr(v) for v in reais]}.",
                f"Derivada do mapa: {sp.sstr(derivada)}.",
                f"Classificações: {classificacoes}.",
            ],
            "resultado": {
                "pontos_fixos": classificacoes,
                "quantidade": len(classificacoes),
            },
            "verificacao": {
                item["ponto"]: sp.sstr(
                    sp.simplify(
                        expr.subs(x, sp.sympify(item["ponto"]))-
                        sp.sympify(item["ponto"])
                    )
                )
                for item in classificacoes
            },
            "justificacao": (
                "Ao menos um ponto possui multiplicador de módulo 1; "
                "a linearização não determina a estabilidade nesse caso."
                if possui_indeterminacao
                else None
            ),
        }


class MotorBifurcacoesPSF:
    """Testes locais de sela-nó e Hopf."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        sela = re.fullmatch(
            r"bifurcacao\s+sela\s+no\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)",
            texto,
        )

        if sela:
            try:
                expr = ParserDinamicaPSF.expressao_mapa(
                    sela.group(1),
                    {},
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            x = ParserDinamicaPSF.x
            mu = ParserDinamicaPSF.mu
            x0 = float(sela.group(2))
            mu0 = float(sela.group(3))
            f = sp.simplify(expr)
            fx = sp.diff(f, x)
            fxx = sp.diff(fx, x)
            fmu = sp.diff(f, mu)
            substituicao = {x: x0, mu: mu0}
            valores = {
                "F": float(sp.N(f.subs(substituicao))),
                "F_x": float(sp.N(fx.subs(substituicao))),
                "F_xx": float(sp.N(fxx.subs(substituicao))),
                "F_mu": float(sp.N(fmu.subs(substituicao))),
            }
            tolerancia = 1e-8
            condicoes = {
                "F=0": abs(valores["F"]) < tolerancia,
                "F_x=0": abs(valores["F_x"]) < tolerancia,
                "F_xx≠0": abs(valores["F_xx"]) > tolerancia,
                "F_mu≠0": abs(valores["F_mu"]) > tolerancia,
            }
            sela_no = all(condicoes.values())

            return {
                "tipo": "bifurcação sela-nó",
                "dados": {
                    "F(x,mu)": sp.sstr(f),
                    "x0": x0,
                    "mu0": mu0,
                },
                "pedido": "Testar as condições não degeneradas de sela-nó",
                "formula": "F=0, F_x=0, F_xx≠0 e F_mu≠0",
                "passos": [
                    f"F_x={sp.sstr(fx)}.",
                    f"F_xx={sp.sstr(fxx)}.",
                    f"F_mu={sp.sstr(fmu)}.",
                    f"Valores no ponto: {valores}.",
                ],
                "resultado": {
                    "condições": condicoes,
                    "sela_nó_local": sela_no,
                },
                "verificacao": (
                    "Todas as condições locais foram testadas numericamente."
                ),
            }

        hopf = re.fullmatch(
            r"bifurcacao\s+hopf\s+(.+)",
            texto,
        )

        if not hopf:
            return None

        try:
            matriz = np.asarray(
                ParserDinamicaPSF.literal(
                    hopf.group(1),
                    "Jacobiano",
                ),
                dtype=float,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if matriz.shape != (2, 2):
            return {"erro": "O teste planar de Hopf exige Jacobiano 2×2."}

        autovalores = np.linalg.eigvals(matriz)
        traco = float(np.trace(matriz))
        determinante = float(np.linalg.det(matriz))
        discriminante = traco**2-4*determinante
        imaginarios = bool(discriminante < 0)
        parte_real_zero = abs(traco) < 1e-8
        frequencia = math.sqrt(determinante) if determinante > 0 else None
        candidato = imaginarios and parte_real_zero and determinante > 0

        return {
            "tipo": "teste linear de bifurcação de Hopf",
            "dados": {"Jacobiano": matriz.tolist()},
            "pedido": "Verificar autovalores imaginários puros no ponto crítico",
            "formula": "tr(J)=0, det(J)>0 e autovalores ±iω",
            "passos": [
                f"tr(J)={traco}.",
                f"det(J)={determinante}.",
                f"Discriminante={discriminante}.",
                f"Autovalores={autovalores.tolist()}.",
            ],
            "resultado": {
                "candidato_Hopf_linear": candidato,
                "frequência_linear": frequencia,
                "autovalores": [
                    complex(v)
                    for v in autovalores
                ],
                "bifurcação_Hopf_completa": (
                    "não determinado" if candidato else False
                ),
            },
            "verificacao": (
                "O teste espectral linear foi aplicado ao Jacobiano."
            ),
            "justificacao": (
                "Autovalores imaginários puros são uma condição necessária. "
                "Para confirmar uma bifurcação de Hopf é preciso ainda verificar "
                "a transversalidade da passagem pela parte real zero e uma "
                "condição de não degeneração, como o primeiro coeficiente de "
                "Lyapunov; por isso o resultado completo fica não determinado."
                if candidato
                else None
            ),
        }


class MotorCaosLyapunovPSF:
    """Expoente de Lyapunov de mapas unidimensionais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"lyapunov\s+mapa\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*(\d+)\s*;\s*(\d+)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        parametros = {}

        if padrao.group(5):
            try:
                parametros = ParserDinamicaPSF.literal(
                    padrao.group(5),
                    "parâmetros",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

        try:
            expr, funcao = ParserDinamicaPSF.funcao_x(
                padrao.group(1),
                parametros,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        derivada_expr = sp.diff(expr, ParserDinamicaPSF.x)
        derivada = sp.lambdify(
            ParserDinamicaPSF.x,
            derivada_expr,
            modules=["numpy"],
        )
        atual = float(padrao.group(2))
        iteracoes = int(padrao.group(3))
        descarte = int(padrao.group(4))

        if iteracoes < 1 or iteracoes > 5_000_000:
            return {"erro": "As iterações devem estar entre 1 e 5000000."}
        if descarte < 0 or descarte >= iteracoes:
            return {"erro": "O descarte deve estar entre 0 e iterações−1."}

        soma = 0.0
        usados = 0
        menores_derivadas = []
        amostra_orbita = []

        for indice in range(iteracoes):
            valor_derivada = abs(float(derivada(atual)))

            if indice >= descarte:
                if valor_derivada <= 0:
                    soma = -math.inf
                    usados += 1
                elif math.isfinite(soma):
                    soma += math.log(valor_derivada)
                    usados += 1

                if len(menores_derivadas) < 100:
                    menores_derivadas.append(valor_derivada)

            atual = float(funcao(atual))

            if not np.isfinite(atual):
                return {"erro": f"A órbita divergiu na iteração {indice+1}."}

            if len(amostra_orbita) < 1000 and indice >= descarte:
                amostra_orbita.append(atual)

        expoente = (
            soma/usados
            if usados and math.isfinite(soma)
            else -math.inf
        )

        if expoente > 1e-6:
            classe = "sensibilidade exponencial; comportamento caótico provável"
        elif expoente < -1e-6:
            classe = "contração média; órbita localmente estável"
        else:
            classe = "não determinado"

        return {
            "tipo": "expoente de Lyapunov",
            "dados": {
                "mapa": sp.sstr(expr),
                "derivada": sp.sstr(derivada_expr),
                "iterações": iteracoes,
                "descarte": descarte,
            },
            "pedido": "Medir a taxa média de separação de órbitas próximas",
            "formula": "λ≈(1/N)Σ log|f'(x_n)|",
            "passos": [
                "Iteramos o mapa após o transiente.",
                "Em cada ponto calculamos log|f'(x_n)|.",
                f"Primeiros módulos de derivada: {menores_derivadas}.",
                f"Expoente médio: {expoente}.",
            ],
            "resultado": {
                "expoente_Lyapunov": expoente,
                "classificação": classe,
                "amostra_órbita": amostra_orbita,
            },
            "verificacao": (
                "O expoente foi calculado ao longo da órbita fornecida."
            ),
            "justificacao": (
                "Um expoente numericamente próximo de zero pode representar "
                "quase-periodicidade, bifurcação, convergência lenta ou erro "
                "finito. A amostra usada não determina uma classificação única."
                if classe == "não determinado"
                else None
            ),
        }


class MotorAtratoresEstranhosPSF:
    """Atrator de Hénon e sistema de Lorenz."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        henon = re.fullmatch(
            r"atrator\s+henon\s+"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)",
            texto,
        )

        if henon:
            a = float(henon.group(1))
            b = float(henon.group(2))
            x = float(henon.group(3))
            y = float(henon.group(4))
            iteracoes = int(henon.group(5))
            descarte = int(henon.group(6))

            if iteracoes < 1 or iteracoes > 5_000_000:
                return {"erro": "As iterações devem estar entre 1 e 5000000."}
            if descarte < 0 or descarte >= iteracoes:
                return {"erro": "Descarte inválido."}

            pontos = []
            soma_lyapunov = 0.0
            vetor_tangente = np.asarray([1.0, 0.0])

            for indice in range(iteracoes):
                jacobiano = np.asarray([
                    [-2*a*x, 1],
                    [b, 0],
                ])
                vetor_tangente = jacobiano@vetor_tangente
                norma = float(np.linalg.norm(vetor_tangente))

                if norma == 0:
                    soma_lyapunov = -math.inf
                elif indice >= descarte and math.isfinite(soma_lyapunov):
                    soma_lyapunov += math.log(norma)
                    vetor_tangente /= norma
                else:
                    vetor_tangente /= norma

                x, y = 1-a*x*x+y, b*x

                if not np.isfinite([x, y]).all():
                    return {"erro": "A órbita de Hénon divergiu."}

                if indice >= descarte and len(pontos) < 200000:
                    pontos.append((x, y))

            expoente = (
                soma_lyapunov/(iteracoes-descarte)
                if math.isfinite(soma_lyapunov)
                else -math.inf
            )
            arr = np.asarray(pontos)

            diretorio = Path.cwd() / "graficos_psf"
            diretorio.mkdir(parents=True, exist_ok=True)
            caminho = diretorio / "atrator_henon.png"
            figura, eixo = plt.subplots(figsize=(7, 7))
            eixo.scatter(arr[:, 0], arr[:, 1], s=1)
            eixo.set_xlabel("x")
            eixo.set_ylabel("y")
            eixo.set_title("Atrator de Hénon")
            figura.tight_layout()
            figura.savefig(caminho, dpi=180)
            plt.close(figura)

            return {
                "tipo": "atrator de Hénon",
                "dados": {
                    "a": a,
                    "b": b,
                    "iterações": iteracoes,
                    "descarte": descarte,
                },
                "pedido": "Gerar a órbita e estimar sensibilidade caótica",
                "formula": "x_{n+1}=1−ax_n²+y_n; y_{n+1}=bx_n",
                "passos": [
                    "Iteramos simultaneamente o estado e um vetor tangente.",
                    f"Pontos armazenados: {len(pontos)}.",
                    f"Expoente tangente aproximado: {expoente}.",
                ],
                "resultado": {
                    "expoente_Lyapunov_aproximado": expoente,
                    "mínimos": arr.min(axis=0).tolist(),
                    "máximos": arr.max(axis=0).tolist(),
                    "últimos_pontos": arr[-100:].tolist(),
                    "gráfico": str(caminho.resolve()),
                },
                "verificacao": (
                    "Todos os pontos armazenados resultam das equações de Hénon."
                ),
            }

        lorenz = re.fullmatch(
            r"atrator\s+lorenz\s+"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*(\d+)",
            texto,
        )

        if not lorenz:
            return None

        sigma = float(lorenz.group(1))
        rho = float(lorenz.group(2))
        beta = float(lorenz.group(3))
        inicial = [
            float(lorenz.group(4)),
            float(lorenz.group(5)),
            float(lorenz.group(6)),
        ]
        tf = float(lorenz.group(7))
        passos = int(lorenz.group(8))

        if sigma <= 0 or beta <= 0 or tf <= 0 or passos < 10 or passos > 1_000_000:
            return {"erro": "Parâmetros/intervalo inválidos."}

        tempos = np.linspace(0, tf, passos)

        def sistema(_, estado):
            x, y, z = estado
            return [
                sigma*(y-x),
                x*(rho-z)-y,
                x*y-beta*z,
            ]

        solucao = scipy_solve_ivp(
            sistema,
            (0, tf),
            inicial,
            t_eval=tempos,
            rtol=1e-9,
            atol=1e-11,
        )

        if not solucao.success:
            return {"erro": solucao.message}

        x, y, z = solucao.y
        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "atrator_lorenz.png"
        figura = plt.figure(figsize=(8, 7))
        eixo = figura.add_subplot(111, projection="3d")
        eixo.plot(x, y, z, linewidth=0.6)
        eixo.set_xlabel("x")
        eixo.set_ylabel("y")
        eixo.set_zlabel("z")
        eixo.set_title("Sistema de Lorenz")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "atrator de Lorenz",
            "dados": {
                "sigma": sigma,
                "rho": rho,
                "beta": beta,
                "estado_inicial": inicial,
                "tempo_final": tf,
            },
            "pedido": "Integrar o fluxo de Lorenz",
            "formula": (
                "x'=σ(y−x); y'=x(ρ−z)−y; z'=xy−βz"
            ),
            "passos": [
                f"Usamos {passos} instantes de saída.",
                f"Estado final: {[x[-1], y[-1], z[-1]]}.",
                (
                    f"Intervalos: x∈[{x.min()},{x.max()}], "
                    f"y∈[{y.min()},{y.max()}], z∈[{z.min()},{z.max()}]."
                ),
            ],
            "resultado": {
                "estado_final": [float(x[-1]), float(y[-1]), float(z[-1])],
                "mínimos": [float(x.min()), float(y.min()), float(z.min())],
                "máximos": [float(x.max()), float(y.max()), float(z.max())],
                "amostra_final": solucao.y[:, -100:].T.tolist(),
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "integração_concluída": bool(solucao.success),
                "avaliações_função": int(solucao.nfev),
            },
        }


class MotorTeoriaErgodicaPSF:
    """Ergodicidade de transformações finitas que preservam medida uniforme."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"ergodico\s+transformacao\s+(.+?)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            mapa = [
                int(v)
                for v in ParserDinamicaPSF.literal(
                    padrao.group(1),
                    "transformação",
                )
            ]
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        n = len(mapa)

        if n == 0 or sorted(mapa) != list(range(n)):
            return {
                "erro": (
                    "Para preservar a medida uniforme, a transformação deve "
                    "ser uma permutação de 0,...,n−1."
                )
            }

        visitados = set()
        ciclos = []

        for inicio in range(n):
            if inicio in visitados:
                continue

            ciclo = []
            atual = inicio

            while atual not in visitados:
                visitados.add(atual)
                ciclo.append(atual)
                atual = mapa[atual]

            ciclos.append(ciclo)

        ergodica = len(ciclos) == 1
        observavel = None
        medias = None

        if padrao.group(2):
            try:
                observavel = [
                    float(v)
                    for v in ParserDinamicaPSF.literal(
                        padrao.group(2),
                        "observável",
                    )
                ]
            except (ValueError, TypeError) as erro:
                return {"erro": str(erro)}

            if len(observavel) != n:
                return {"erro": "O observável deve ter um valor por estado."}

            media_espacial = float(np.mean(observavel))
            medias = []

            for ciclo in ciclos:
                media_ciclo = float(np.mean([
                    observavel[estado]
                    for estado in ciclo
                ]))
                medias.append({
                    "ciclo": ciclo,
                    "média_temporal": media_ciclo,
                    "média_espacial_global": media_espacial,
                })

        return {
            "tipo": "ergodicidade em espaço finito",
            "dados": {
                "transformação": mapa,
                "estados": n,
                "observável": observavel,
            },
            "pedido": "Decompor em órbitas e testar ergodicidade uniforme",
            "formula": (
                "uma permutação finita uniforme é ergódica "
                "se possui uma única órbita"
            ),
            "passos": [
                f"Decomposição em ciclos: {ciclos}.",
                f"Quantidade de componentes invariantes: {len(ciclos)}.",
                f"Médias do observável: {medias}.",
            ],
            "resultado": {
                "ciclos": ciclos,
                "ergódica": ergodica,
                "médias": medias,
            },
            "verificacao": (
                "Uma única órbita visita todos os estados."
                if ergodica
                else "Cada ciclo próprio é um conjunto invariante não trivial."
            ),
        }


class MotorBirkhoffPSF:
    """Médias temporais ao longo de uma órbita discreta."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"birkhoff\s+mapa\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*(\d+)\s*;\s*(.+?)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        parametros = {}

        if padrao.group(5):
            try:
                parametros = ParserDinamicaPSF.literal(
                    padrao.group(5),
                    "parâmetros",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

        try:
            mapa_expr, mapa = ParserDinamicaPSF.funcao_x(
                padrao.group(1),
                parametros,
            )
            obs_expr, observavel = ParserDinamicaPSF.observavel_x(
                padrao.group(4)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        atual = float(padrao.group(2))
        n = int(padrao.group(3))

        if n < 1 or n > 5_000_000:
            return {"erro": "n deve estar entre 1 e 5000000."}

        soma = 0.0
        medias_parciais = []
        valores = []

        for indice in range(1, n+1):
            valor = float(observavel(atual))

            if not np.isfinite(valor):
                return {"erro": "O observável tornou-se não finito."}

            soma += valor

            if len(valores) < 10000:
                valores.append(valor)

            if indice <= 100 or indice in {
                n,
                max(1, n//10),
                max(1, n//2),
            }:
                medias_parciais.append({
                    "N": indice,
                    "média": soma/indice,
                })

            atual = float(mapa(atual))

            if not np.isfinite(atual):
                return {"erro": "A órbita tornou-se não finita."}

        media = soma/n

        return {
            "tipo": "média ergódica de Birkhoff",
            "dados": {
                "mapa": sp.sstr(mapa_expr),
                "observável": sp.sstr(obs_expr),
                "x0": float(padrao.group(2)),
                "iterações": n,
            },
            "pedido": "Calcular a média temporal do observável",
            "formula": "A_N(x)=1/N Σ_{k=0}^{N−1} φ(T^k x)",
            "passos": [
                "Iteramos o ponto e avaliamos o observável.",
                f"Médias parciais selecionadas: {medias_parciais}.",
                f"Média final: {media}.",
            ],
            "resultado": {
                "média_temporal": media,
                "médias_parciais": medias_parciais,
                "valores_armazenados": valores,
                "limite_Birkhoff_exato": "não determinado",
            },
            "verificacao": (
                "A média apresentada usa exatamente N termos da órbita."
            ),
            "justificacao": (
                "Uma média finita não prova a existência nem identifica o "
                "limite assintótico. O Teorema de Birkhoff requer hipóteses "
                "de preservação de medida e integrabilidade, e sua conclusão "
                "é quase em toda parte; por isso o limite exato fica não determinado."
            ),
        }


class MotorEntropiaDinamicaPSF:
    """Entropia estacionária e taxa de entropia de cadeia de Markov."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"entropia\s+markov\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            matriz = np.asarray(
                ParserDinamicaPSF.literal(
                    padrao.group(1),
                    "matriz de transição",
                ),
                dtype=float,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if matriz.ndim != 2 or matriz.shape[0] != matriz.shape[1]:
            return {"erro": "A matriz deve ser quadrada."}
        if np.any(matriz < 0) or not np.allclose(
            np.sum(matriz, axis=1),
            1,
            atol=1e-9,
        ):
            return {"erro": "Cada linha deve ser uma distribuição de probabilidade."}

        valores, vetores = np.linalg.eig(matriz.T)
        indice = int(np.argmin(np.abs(valores-1)))
        pi = np.real(vetores[:, indice])

        if np.sum(pi) < 0:
            pi = -pi

        pi = np.maximum(pi, 0)
        pi = pi/np.sum(pi)

        def entropia(probabilidades):
            p = np.asarray(probabilidades, dtype=float)
            p = p[p > 0]
            return float(-np.sum(p*np.log2(p)))

        h_estado = entropia(pi)
        taxas_linhas = [
            entropia(linha)
            for linha in matriz
        ]
        taxa = float(np.dot(pi, taxas_linhas))
        informacao_mutua = h_estado-taxa
        reversibilidade_residuos = np.zeros_like(matriz)

        for i in range(len(pi)):
            for j in range(len(pi)):
                reversibilidade_residuos[i, j] = (
                    pi[i]*matriz[i, j]-
                    pi[j]*matriz[j, i]
                )

        return {
            "tipo": "entropia de sistema dinâmico de Markov",
            "dados": {
                "estados": matriz.shape[0],
                "matriz": matriz.tolist(),
            },
            "pedido": "Calcular distribuição estacionária e taxa de entropia",
            "formula": "h=−Σ_iπ_iΣ_jP_ij log₂P_ij",
            "passos": [
                f"Distribuição estacionária: {pi.tolist()}.",
                f"Entropias condicionais por estado: {taxas_linhas}.",
                f"Entropia estacionária H(X): {h_estado}.",
                f"Taxa de entropia h: {taxa}.",
            ],
            "resultado": {
                "distribuição_estacionária": pi.tolist(),
                "entropia_estado_bits": h_estado,
                "taxa_entropia_bits_por_passo": taxa,
                "informação_mútua_passos_consecutivos": informacao_mutua,
                "reversível": bool(
                    np.allclose(
                        reversibilidade_residuos,
                        0,
                        atol=1e-9,
                    )
                ),
            },
            "verificacao": {
                "estacionariedade": bool(
                    np.allclose(pi@matriz, pi, atol=1e-9)
                ),
                "soma_pi": float(np.sum(pi)),
            },
        }


class MotorFluxosContinuosPSF:
    """Integração de sistemas contínuos fornecidos por expressões."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"fluxo\s+sistema\s+(.+?)\s*;\s*(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*(\d+)",
            texto,
        )

        if not padrao:
            return None

        try:
            simbolos, expressoes, funcao = ParserDinamicaPSF.sistema(
                padrao.group(1)
            )
            inicial = np.asarray(
                ParserDinamicaPSF.literal(
                    padrao.group(2),
                    "estado inicial",
                ),
                dtype=float,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        t0 = float(padrao.group(3))
        tf = float(padrao.group(4))
        passos = int(padrao.group(5))

        if inicial.shape != (len(simbolos),):
            return {
                "erro": (
                    f"O estado inicial deve possuir {len(simbolos)} valores."
                )
            }
        if not t0 < tf or passos < 2 or passos > 1_000_000:
            return {"erro": "Exige-se t0<tf e 2≤passos≤1000000."}

        tempos = np.linspace(t0, tf, passos)

        def sistema(t, estado):
            valores = np.asarray(
                funcao(t, *estado),
                dtype=float,
            ).reshape(-1)
            return valores

        solucao = scipy_solve_ivp(
            sistema,
            (t0, tf),
            inicial,
            t_eval=tempos,
            rtol=1e-9,
            atol=1e-11,
        )

        if not solucao.success:
            return {"erro": solucao.message}

        return {
            "tipo": "fluxo de sistema dinâmico contínuo",
            "dados": {
                "equações": [
                    f"{simbolo}'={sp.sstr(expr)}"
                    for simbolo, expr in zip(simbolos, expressoes)
                ],
                "estado_inicial": inicial.tolist(),
                "intervalo": [t0, tf],
            },
            "pedido": "Integrar o sistema e construir o fluxo numérico",
            "formula": "x(t)=x(t₀)+∫_{t₀}^t F(s,x(s))ds",
            "passos": [
                f"Símbolos de estado: {[str(v) for v in simbolos]}.",
                f"Usamos {passos} instantes de saída.",
                f"Estado final: {solucao.y[:, -1].tolist()}.",
            ],
            "resultado": {
                "tempos": solucao.t.tolist(),
                "trajetória": solucao.y.T.tolist(),
                "estado_final": solucao.y[:, -1].tolist(),
                "mínimos": solucao.y.min(axis=1).tolist(),
                "máximos": solucao.y.max(axis=1).tolist(),
            },
            "verificacao": {
                "integração_concluída": bool(solucao.success),
                "avaliações_função": int(solucao.nfev),
            },
        }


class MotorModelosEcologiaEpidemiologiaPSF:
    """Modelos SIR e Lotka–Volterra."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        sir = re.fullmatch(
            r"modelo\s+sir\s+"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*(\d+)",
            texto,
        )

        if sir:
            beta = float(sir.group(1))
            gamma = float(sir.group(2))
            inicial = np.asarray([
                float(sir.group(3)),
                float(sir.group(4)),
                float(sir.group(5)),
            ])
            tf = float(sir.group(6))
            passos = int(sir.group(7))

            if beta < 0 or gamma <= 0 or np.any(inicial < 0):
                return {"erro": "Parâmetros e populações inválidos."}
            if inicial.sum() <= 0 or tf <= 0 or passos < 2:
                return {"erro": "População, tempo e passos devem ser positivos."}

            populacao = float(inicial.sum())

            def sistema(_, estado):
                s, i, r = estado
                incidencia = beta*s*i/populacao
                return [
                    -incidencia,
                    incidencia-gamma*i,
                    gamma*i,
                ]

            tempos = np.linspace(0, tf, passos)
            solucao = scipy_solve_ivp(
                sistema,
                (0, tf),
                inicial,
                t_eval=tempos,
                rtol=1e-9,
                atol=1e-11,
            )

            if not solucao.success:
                return {"erro": solucao.message}

            s, i, r = solucao.y
            indice_pico = int(np.argmax(i))
            r0 = beta/gamma
            conservacao = s+i+r
            diretorio = Path.cwd() / "graficos_psf"
            diretorio.mkdir(parents=True, exist_ok=True)
            caminho = diretorio / "modelo_sir.png"
            figura, eixo = plt.subplots(figsize=(9, 5))
            eixo.plot(tempos, s, label="S")
            eixo.plot(tempos, i, label="I")
            eixo.plot(tempos, r, label="R")
            eixo.legend()
            eixo.set_xlabel("tempo")
            eixo.set_ylabel("população")
            eixo.set_title("Modelo SIR")
            figura.tight_layout()
            figura.savefig(caminho, dpi=180)
            plt.close(figura)

            return {
                "tipo": "modelo epidemiológico SIR",
                "dados": {
                    "beta": beta,
                    "gamma": gamma,
                    "S0_I0_R0": inicial.tolist(),
                    "população": populacao,
                },
                "pedido": "Simular suscetíveis, infetados e recuperados",
                "formula": (
                    "S'=−βSI/N; I'=βSI/N−γI; R'=γI"
                ),
                "passos": [
                    f"N={populacao}.",
                    f"R₀=β/γ={r0}.",
                    (
                        f"Pico de I={i[indice_pico]} no tempo "
                        f"{tempos[indice_pico]}."
                    ),
                    f"Estado final={[s[-1], i[-1], r[-1]]}.",
                ],
                "resultado": {
                    "R0_básico": r0,
                    "pico_infetados": float(i[indice_pico]),
                    "tempo_pico": float(tempos[indice_pico]),
                    "estado_final": [
                        float(s[-1]),
                        float(i[-1]),
                        float(r[-1]),
                    ],
                    "gráfico": str(caminho.resolve()),
                },
                "verificacao": {
                    "erro_máximo_conservação": float(
                        np.max(np.abs(conservacao-populacao))
                    ),
                    "populações_não_negativas": bool(
                        np.min(solucao.y) >= -1e-7
                    ),
                },
            }

        lotka = re.fullmatch(
            r"modelo\s+lotka\s+volterra\s+"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s*;\s*(\d+)",
            texto,
        )

        if not lotka:
            return None

        alpha = float(lotka.group(1))
        beta = float(lotka.group(2))
        delta = float(lotka.group(3))
        gamma = float(lotka.group(4))
        inicial = [
            float(lotka.group(5)),
            float(lotka.group(6)),
        ]
        tf = float(lotka.group(7))
        passos = int(lotka.group(8))

        if min(alpha, beta, delta, gamma) <= 0:
            return {"erro": "Os quatro parâmetros devem ser positivos."}
        if min(inicial) <= 0 or tf <= 0 or passos < 2:
            return {"erro": "Populações, tempo e passos devem ser positivos."}

        def sistema(_, estado):
            presa, predador = estado
            return [
                alpha*presa-beta*presa*predador,
                delta*presa*predador-gamma*predador,
            ]

        tempos = np.linspace(0, tf, passos)
        solucao = scipy_solve_ivp(
            sistema,
            (0, tf),
            inicial,
            t_eval=tempos,
            rtol=1e-9,
            atol=1e-11,
        )

        if not solucao.success:
            return {"erro": solucao.message}

        presa, predador = solucao.y
        equilibrio = [gamma/delta, alpha/beta]
        invariante = (
            delta*presa-gamma*np.log(presa)
            + beta*predador-alpha*np.log(predador)
        )
        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "lotka_volterra.png"
        figura, eixo = plt.subplots(figsize=(7, 6))
        eixo.plot(presa, predador)
        eixo.scatter(
            [equilibrio[0]],
            [equilibrio[1]],
        )
        eixo.set_xlabel("presas")
        eixo.set_ylabel("predadores")
        eixo.set_title("Plano de fase Lotka–Volterra")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "modelo ecológico Lotka–Volterra",
            "dados": {
                "alpha_beta_delta_gamma": [
                    alpha, beta, delta, gamma
                ],
                "estado_inicial": inicial,
            },
            "pedido": "Simular a interação presa–predador",
            "formula": "x'=αx−βxy; y'=δxy−γy",
            "passos": [
                f"Equilíbrio positivo: {equilibrio}.",
                f"Estado final: {[presa[-1], predador[-1]]}.",
                (
                    f"Intervalo de presas: [{presa.min()},{presa.max()}]."
                ),
                (
                    f"Intervalo de predadores: "
                    f"[{predador.min()},{predador.max()}]."
                ),
            ],
            "resultado": {
                "equilíbrio_positivo": equilibrio,
                "estado_final": [
                    float(presa[-1]),
                    float(predador[-1]),
                ],
                "mínimos": [
                    float(presa.min()),
                    float(predador.min()),
                ],
                "máximos": [
                    float(presa.max()),
                    float(predador.max()),
                ],
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "variação_invariante_primeira_integral": float(
                    np.max(invariante)-np.min(invariante)
                ),
                "populações_positivas": bool(
                    np.min(solucao.y) > 0
                ),
            },
        }



class ParserGeometriaAlgebricaPSF:
    """Polinômios multivariados, ideais e pontos algébricos."""

    x, y, z = sp.symbols("x y z")

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @classmethod
    def expressao(cls, texto, variaveis=None):
        variaveis = variaveis or (cls.x, cls.y, cls.z)
        expressao = texto.strip().replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            raise ValueError("Expressão algébrica contém símbolos não permitidos.")

        locais = {
            str(v): v
            for v in variaveis
        }

        try:
            expr = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            raise ValueError("Expressão algébrica inválida.") from erro

        if expr.free_symbols - set(variaveis):
            raise ValueError("A expressão contém variável desconhecida.")

        return sp.expand(expr)

    @classmethod
    def lista_expressoes(cls, texto, variaveis=None):
        dados = cls.literal(texto, "lista de equações")

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("Forneça uma lista não vazia de equações.")

        return [
            cls.expressao(str(expr), variaveis)
            for expr in dados
        ]

    @staticmethod
    def grau_total(expr, variaveis):
        return sp.Poly(expr, *variaveis).total_degree()

    @staticmethod
    def ponto(texto):
        dados = ParserGeometriaAlgebricaPSF.literal(
            texto,
            "ponto",
        )

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("O ponto deve ser uma lista ou tupla não vazia.")

        try:
            return tuple(sp.Rational(str(v)) for v in dados)
        except Exception as erro:
            raise ValueError("Coordenadas do ponto inválidas.") from erro


class MotorCurvasAlgebricasPlanasPSF:
    """Grau, singularidades e tangentes de curvas planas."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"curva\s+algebrica\s+plana\s+(.+?)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not padrao:
            return None

        x = ParserGeometriaAlgebricaPSF.x
        y = ParserGeometriaAlgebricaPSF.y

        try:
            f = ParserGeometriaAlgebricaPSF.expressao(
                padrao.group(1),
                (x, y),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        grau = ParserGeometriaAlgebricaPSF.grau_total(
            f,
            (x, y),
        )
        fx = sp.diff(f, x)
        fy = sp.diff(f, y)

        try:
            singularidades = sp.solve(
                [f, fx, fy],
                [x, y],
                dict=True,
            )
        except Exception:
            singularidades = []

        singularidades_formatadas = [
            {
                "x": sp.sstr(solucao.get(x)),
                "y": sp.sstr(solucao.get(y)),
            }
            for solucao in singularidades
            if x in solucao and y in solucao
        ]
        ponto_resultado = None

        if padrao.group(2):
            try:
                ponto = ParserGeometriaAlgebricaPSF.ponto(
                    padrao.group(2)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if len(ponto) != 2:
                return {"erro": "O ponto plano deve possuir duas coordenadas."}

            substituicao = {x: ponto[0], y: ponto[1]}
            valor = sp.simplify(f.subs(substituicao))
            gradiente = (
                sp.simplify(fx.subs(substituicao)),
                sp.simplify(fy.subs(substituicao)),
            )
            pertence = valor == 0
            singular = pertence and gradiente == (0, 0)

            if pertence and not singular:
                tangente = sp.expand(
                    gradiente[0]*(x-ponto[0])
                    + gradiente[1]*(y-ponto[1])
                )
            else:
                tangente = None

            ponto_resultado = {
                "ponto": tuple(map(sp.sstr, ponto)),
                "pertence": pertence,
                "gradiente": tuple(map(sp.sstr, gradiente)),
                "singular": singular,
                "tangente": sp.sstr(tangente) if tangente is not None else None,
            }

        genero_suave_projetivo = (
            (grau-1)*(grau-2)//2
            if grau >= 1 and not singularidades_formatadas
            else None
        )

        return {
            "tipo": "curva algébrica plana",
            "dados": {
                "equação": sp.sstr(f),
                "variáveis": ["x", "y"],
            },
            "pedido": "Calcular grau, derivadas, singularidades e tangente",
            "formula": "singular ⇔ f=f_x=f_y=0",
            "passos": [
                f"Grau total: {grau}.",
                f"f_x={sp.sstr(fx)}.",
                f"f_y={sp.sstr(fy)}.",
                f"Singularidades afins encontradas: {singularidades_formatadas}.",
                f"Análise do ponto fornecido: {ponto_resultado}.",
            ],
            "resultado": {
                "grau": grau,
                "singularidades_afins": singularidades_formatadas,
                "ponto_analisado": ponto_resultado,
                "gênero_curva_projetiva_plana_suave": genero_suave_projetivo,
            },
            "verificacao": (
                "Cada singularidade listada anula a equação e as duas derivadas."
            ),
            "observacao": (
                "A ausência de soluções afins encontradas não exclui "
                "singularidades no infinito ou limitações do solucionador."
            ),
        }


class MotorBezoutPSF:
    """Resultante e interseções afins de duas curvas planas."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"bezout\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        x = ParserGeometriaAlgebricaPSF.x
        y = ParserGeometriaAlgebricaPSF.y

        try:
            f = ParserGeometriaAlgebricaPSF.expressao(
                padrao.group(1),
                (x, y),
            )
            g = ParserGeometriaAlgebricaPSF.expressao(
                padrao.group(2),
                (x, y),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        grau_f = ParserGeometriaAlgebricaPSF.grau_total(
            f,
            (x, y),
        )
        grau_g = ParserGeometriaAlgebricaPSF.grau_total(
            g,
            (x, y),
        )
        gcd = sp.gcd(
            sp.Poly(f, x, y),
            sp.Poly(g, x, y),
        )
        componente_comum = gcd.total_degree() > 0
        resultante_x = sp.factor(
            sp.resultant(f, g, y)
        )
        resultante_y = sp.factor(
            sp.resultant(f, g, x)
        )

        try:
            solucoes = sp.solve_poly_system(
                [f, g],
                x,
                y,
            )
        except Exception:
            solucoes = []

        solucoes_formatadas = [
            (sp.sstr(a), sp.sstr(b))
            for a, b in solucoes
        ]
        esperado = grau_f*grau_g

        return {
            "tipo": "Teorema de Bézout e interseção de curvas",
            "dados": {
                "f": sp.sstr(f),
                "g": sp.sstr(g),
            },
            "pedido": "Eliminar variáveis e calcular interseções afins",
            "formula": (
                "sem componente comum, duas curvas projetivas de graus m,n "
                "intersectam-se em mn pontos contando multiplicidades"
            ),
            "passos": [
                f"grau(f)={grau_f}; grau(g)={grau_g}.",
                f"mdc multivariado={sp.sstr(gcd.as_expr())}.",
                f"Resultante eliminando y: {sp.sstr(resultante_x)}.",
                f"Resultante eliminando x: {sp.sstr(resultante_y)}.",
                f"Soluções afins obtidas: {solucoes_formatadas}.",
            ],
            "resultado": {
                "componente_comum": componente_comum,
                "limite_Bezout_projetivo_com_multiplicidades": (
                    None if componente_comum else esperado
                ),
                "interseções_afins_encontradas": solucoes_formatadas,
                "quantidade_afim_distinta": len(set(solucoes_formatadas)),
                "resultante_x": sp.sstr(resultante_x),
                "resultante_y": sp.sstr(resultante_y),
            },
            "verificacao": (
                "Cada solução listada anula simultaneamente f e g."
            ),
            "observacao": (
                "A quantidade afim distinta pode ser menor que mn por "
                "multiplicidades e pontos de interseção no infinito."
            ),
        }


class MotorVariedadesAfinsProjetivasPSF:
    """Soluções afins, homogeneização e teste de pontos projetivos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        afim = re.fullmatch(
            r"variedade\s+afim\s+(.+)",
            texto,
        )

        if afim:
            x = ParserGeometriaAlgebricaPSF.x
            y = ParserGeometriaAlgebricaPSF.y

            try:
                equacoes = ParserGeometriaAlgebricaPSF.lista_expressoes(
                    afim.group(1),
                    (x, y),
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            groebner = sp.groebner(
                equacoes,
                x,
                y,
                order="lex",
            )

            try:
                solucoes = sp.solve(
                    equacoes,
                    [x, y],
                    dict=True,
                )
            except Exception:
                solucoes = []

            return {
                "tipo": "variedade afim",
                "dados": {
                    "equações": [sp.sstr(v) for v in equacoes],
                    "corpo_base_formal": "Q/C",
                },
                "pedido": "Calcular base de Gröbner e soluções afins",
                "formula": "V(I)={p : f(p)=0 para todo f∈I}",
                "passos": [
                    f"Base de Gröbner lexicográfica: "
                    f"{[sp.sstr(v.as_expr()) for v in groebner.polys]}.",
                    f"Soluções encontradas: {solucoes}.",
                ],
                "resultado": {
                    "base_Groebner": [
                        sp.sstr(v.as_expr())
                        for v in groebner.polys
                    ],
                    "soluções": [
                        {
                            str(chave): sp.sstr(valor)
                            for chave, valor in solucao.items()
                        }
                        for solucao in solucoes
                    ],
                    "ideal_unitário": bool(
                        len(groebner.polys) == 1
                        and groebner.polys[0].as_expr() == 1
                    ),
                },
                "verificacao": (
                    "As soluções listadas foram obtidas do sistema polinomial."
                ),
            }

        projetiva = re.fullmatch(
            r"variedade\s+projetiva\s+(.+?)"
            r"(?:\s*;\s*(.+))?",
            texto,
        )

        if not projetiva:
            return None

        x = ParserGeometriaAlgebricaPSF.x
        y = ParserGeometriaAlgebricaPSF.y
        z = ParserGeometriaAlgebricaPSF.z

        try:
            equacoes_afins = ParserGeometriaAlgebricaPSF.lista_expressoes(
                projetiva.group(1),
                (x, y),
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        homogeneas = []
        graus = []

        for f in equacoes_afins:
            poly = sp.Poly(f, x, y)
            grau = poly.total_degree()
            graus.append(grau)
            homogenea = sp.Poly(
                f,
                x,
                y,
            ).homogenize(z).as_expr()
            homogeneas.append(sp.expand(homogenea))

        ponto_resultado = None

        if projetiva.group(2):
            try:
                ponto = ParserGeometriaAlgebricaPSF.ponto(
                    projetiva.group(2)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if len(ponto) != 3 or all(coordenada == 0 for coordenada in ponto):
                return {
                    "erro": (
                        "Um ponto projetivo deve ter três coordenadas, "
                        "não todas nulas."
                    )
                }

            valores = [
                sp.simplify(
                    f.subs({x: ponto[0], y: ponto[1], z: ponto[2]})
                )
                for f in homogeneas
            ]
            ponto_resultado = {
                "ponto": tuple(map(sp.sstr, ponto)),
                "valores": list(map(sp.sstr, valores)),
                "pertence": all(valor == 0 for valor in valores),
                "no_infinito": ponto[2] == 0,
            }

        return {
            "tipo": "fecho projetivo de variedade afim",
            "dados": {
                "equações_afins": [sp.sstr(v) for v in equacoes_afins],
            },
            "pedido": "Homogeneizar as equações e testar um ponto projetivo",
            "formula": "F(x,y,z)=z^d f(x/z,y/z)",
            "passos": [
                f"Graus: {graus}.",
                f"Equações homogêneas: {[sp.sstr(v) for v in homogeneas]}.",
                f"Análise do ponto: {ponto_resultado}.",
            ],
            "resultado": {
                "equações_homogêneas": [
                    sp.sstr(v)
                    for v in homogeneas
                ],
                "ponto_analisado": ponto_resultado,
            },
            "verificacao": (
                "Cada equação resultante é homogênea no seu grau."
            ),
        }


class MotorAnelCoordenadasZariskiPSF:
    """Redução módulo ideal e teste de conjuntos fechados de Zariski."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        anel = re.fullmatch(
            r"anel\s+coordenadas\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if anel:
            x = ParserGeometriaAlgebricaPSF.x
            y = ParserGeometriaAlgebricaPSF.y

            try:
                geradores = ParserGeometriaAlgebricaPSF.lista_expressoes(
                    anel.group(1),
                    (x, y),
                )
                elemento = ParserGeometriaAlgebricaPSF.expressao(
                    anel.group(2),
                    (x, y),
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            base = sp.groebner(
                geradores,
                x,
                y,
                order="lex",
            )
            quociente, resto = base.reduce(elemento)

            return {
                "tipo": "anel de coordenadas",
                "dados": {
                    "ideal": [sp.sstr(v) for v in geradores],
                    "elemento": sp.sstr(elemento),
                },
                "pedido": "Reduzir o elemento em k[x,y]/I",
                "formula": "[f]=[r], onde f=Σq_i g_i+r pela base de Gröbner",
                "passos": [
                    f"Base de Gröbner: "
                    f"{[sp.sstr(v.as_expr()) for v in base.polys]}.",
                    f"Quocientes da divisão: {[sp.sstr(v) for v in quociente]}.",
                    f"Resto normal: {sp.sstr(resto)}.",
                ],
                "resultado": {
                    "representante_normal": sp.sstr(resto),
                    "elemento_nulo_no_quociente": sp.simplify(resto) == 0,
                },
                "verificacao": (
                    "A diferença entre o elemento e o resto pertence ao ideal."
                ),
            }

        zariski = re.fullmatch(
            r"zariski\s+ponto\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not zariski:
            return None

        x = ParserGeometriaAlgebricaPSF.x
        y = ParserGeometriaAlgebricaPSF.y

        try:
            geradores = ParserGeometriaAlgebricaPSF.lista_expressoes(
                zariski.group(1),
                (x, y),
            )
            ponto = ParserGeometriaAlgebricaPSF.ponto(
                zariski.group(2)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if len(ponto) != 2:
            return {"erro": "O ponto afim deve possuir duas coordenadas."}

        valores = [
            sp.simplify(
                f.subs({x: ponto[0], y: ponto[1]})
            )
            for f in geradores
        ]
        pertence = all(valor == 0 for valor in valores)

        return {
            "tipo": "topologia de Zariski",
            "dados": {
                "fechado": [sp.sstr(v) for v in geradores],
                "ponto": tuple(map(sp.sstr, ponto)),
            },
            "pedido": "Testar se o ponto pertence a V(I)",
            "formula": "p∈V(I) ⇔ f(p)=0 para todo f∈I",
            "passos": [
                f"Valores dos geradores no ponto: {list(map(sp.sstr, valores))}.",
                (
                    "Todos anulam."
                    if pertence
                    else "Pelo menos um gerador não anula."
                ),
            ],
            "resultado": {"pertence_ao_fechado": pertence},
            "verificacao": (
                "A pertença foi testada em todos os geradores fornecidos."
            ),
        }


class MotorFeixesEsquemasPSF:
    """Espectro de Z/nZ e validação de presheaf linear finito."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        spec = re.fullmatch(
            r"esquema\s+spec\s+zn\s+(\d+)",
            texto,
        )

        if spec:
            n = int(spec.group(1))

            if n < 1:
                return {"erro": "n deve ser positivo."}

            fatores = sp.factorint(n)
            primos = sorted(int(p) for p in fatores)
            nilpotentes = [
                a
                for a in range(n)
                if any(
                    pow(a, k, n) == 0
                    for k in range(1, max(2, n+1))
                )
            ] if n <= 5000 else "omitidos para n>5000"
            reduzido = all(expoente == 1 for expoente in fatores.values())
            corpo = bool(sp.isprime(n))
            pontos = [
                {
                    "ideal_primo": f"({p})",
                    "corpo_resíduo": f"F_{p}",
                }
                for p in primos
            ]

            return {
                "tipo": "esquema afim Spec(Z/nZ)",
                "dados": {"n": n, "fatoração": fatores},
                "pedido": "Calcular os pontos primos e propriedades do anel",
                "formula": "Spec(Z/nZ)={ideais primos (p): p|n}",
                "passos": [
                    f"Fatoramos n: {fatores}.",
                    f"Primos divisores: {primos}.",
                    f"Pontos do espectro: {pontos}.",
                    f"Anel reduzido: {reduzido}.",
                    f"Anel é corpo: {corpo}.",
                ],
                "resultado": {
                    "pontos": pontos,
                    "quantidade_pontos": len(pontos),
                    "reduzido": reduzido,
                    "corpo": corpo,
                    "nilpotentes": nilpotentes,
                },
                "verificacao": (
                    "Cada ponto corresponde a um primo divisor de n."
                ),
            }

        presheaf = re.fullmatch(
            r"feixe\s+linear\s+validar\s+(.+)",
            texto,
        )

        if not presheaf:
            return None

        try:
            dados = ParserGeometriaAlgebricaPSF.literal(
                presheaf.group(1),
                "presheaf",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {
                "erro": (
                    "Forneça {'dimensoes':{U:n}, "
                    "'restricoes':{(U,V):matriz}} com V⊆U."
                )
            }

        dimensoes = (
            dados.get("dimensoes")
            or dados.get("dimensões")
        )
        restricoes_brutas = (
            dados.get("restricoes")
            or dados.get("restrições")
            or {}
        )

        if not isinstance(dimensoes, dict):
            return {"erro": "As dimensões das secções são obrigatórias."}

        try:
            dimensoes = {
                str(aberto): int(dim)
                for aberto, dim in dimensoes.items()
            }
        except (TypeError, ValueError):
            return {"erro": "As dimensões devem ser inteiras."}

        restricoes = {}

        for chave, matriz_bruta in restricoes_brutas.items():
            if isinstance(chave, str):
                partes = tuple(v.strip() for v in chave.split(","))
            else:
                partes = tuple(chave)

            if len(partes) != 2:
                return {"erro": "Cada restrição usa a chave (U,V)."}

            u, v = map(str, partes)
            matriz = np.asarray(matriz_bruta, dtype=float)
            esperado = (
                dimensoes.get(v),
                dimensoes.get(u),
            )

            if None in esperado or matriz.shape != esperado:
                return {
                    "erro": (
                        f"Restrição {u}→{v} deve ter forma {esperado}."
                    )
                }

            restricoes[(u, v)] = matriz

        falhas = []

        for aberto, dim in dimensoes.items():
            identidade = restricoes.get((aberto, aberto))

            if identidade is None or not np.allclose(
                identidade,
                np.eye(dim),
            ):
                falhas.append(f"Identidade ausente/incorreta em {aberto}.")

        for (u, v), r_uv in restricoes.items():
            for (v2, w), r_vw in restricoes.items():
                if v2 != v:
                    continue

                r_uw = restricoes.get((u, w))

                if r_uw is None:
                    falhas.append(f"Restrição composta {u}→{w} ausente.")
                elif not np.allclose(r_vw@r_uv, r_uw):
                    falhas.append(f"Composição falhou em {u}→{v}→{w}.")

        return {
            "tipo": "presheaf linear finito",
            "dados": {
                "dimensões_secções": dimensoes,
                "restrições": [
                    f"{u}→{v}"
                    for u, v in restricoes
                ],
            },
            "pedido": "Verificar identidades e composição das restrições",
            "formula": "ρ_UU=id; ρ_VW∘ρ_UV=ρ_UW",
            "passos": [
                "Verificamos a identidade em cada aberto.",
                "Verificamos toda composição de restrições disponível.",
                f"Falhas: {falhas}.",
            ],
            "resultado": {
                "presheaf_válido": not falhas,
                "falhas": falhas,
                "feixe_completo": "não determinado",
            },
            "verificacao": (
                "As leis contravariantes do presheaf foram verificadas."
            ),
            "justificacao": (
                "Identidades e composição definem um presheaf. Para concluir "
                "que é feixe, ainda é necessário testar localidade e colagem "
                "para todas as coberturas relevantes; esses dados não foram "
                "fornecidos, portanto a condição de feixe fica não determinada."
            ),
        }


class MotorCohomologiaFeixesPSF:
    """Cohomologia de um complexo de cochains sobre GF(2) ou Q."""

    @staticmethod
    def posto_racional(matriz):
        return int(sp.Matrix(matriz.tolist()).rank())

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"cohomologia\s+feixe\s+(gf2|q)\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        corpo = padrao.group(1)

        try:
            dados = ParserGeometriaAlgebricaPSF.literal(
                padrao.group(2),
                "complexo de cochains",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {"erro": "Forneça {'dimensoes':{i:n},'diferenciais':{i:M}}."}

        dims_brutas = (
            dados.get("dimensoes")
            or dados.get("dimensões")
            or dados.get("dims")
        )
        ds_brutas = (
            dados.get("diferenciais")
            or dados.get("d")
            or {}
        )

        try:
            dims = {
                int(grau): int(dim)
                for grau, dim in dims_brutas.items()
            }
        except Exception:
            return {"erro": "Dimensões e graus inválidos."}

        diferenciais = {}
        postos = {}

        for grau_bruto, matriz_bruta in ds_brutas.items():
            grau = int(grau_bruto)
            matriz = np.asarray(
                matriz_bruta,
                dtype=int if corpo == "gf2" else float,
            )
            esperado = (
                dims.get(grau+1, 0),
                dims.get(grau, 0),
            )

            if matriz.shape != esperado:
                return {
                    "erro": (
                        f"d^{grau} deve possuir forma {esperado}, "
                        f"recebeu {matriz.shape}."
                    )
                }

            if corpo == "gf2":
                matriz %= 2
                posto = FerramentasNosPSF.posto_modulo(matriz, 2)
            else:
                posto = self.posto_racional(matriz)

            diferenciais[grau] = matriz
            postos[grau] = posto

        falhas = []

        for grau, matriz in diferenciais.items():
            seguinte = diferenciais.get(grau+1)

            if seguinte is None:
                continue

            produto = seguinte@matriz

            if corpo == "gf2":
                produto %= 2

            if not np.allclose(produto, 0):
                falhas.append({
                    "grau": grau,
                    "produto": produto.tolist(),
                })

        if falhas:
            return {"erro": f"d^(i+1)d^i≠0: {falhas}."}

        cohomologia = {}

        for grau in sorted(dims):
            dim_h = (
                dims[grau]
                - postos.get(grau, 0)
                - postos.get(grau-1, 0)
            )
            cohomologia[grau] = {
                "dim_C": dims[grau],
                "rank_d_saida": postos.get(grau, 0),
                "rank_d_entrada": postos.get(grau-1, 0),
                "dim_H": dim_h,
            }

        euler_c = sum(
            (-1)**grau*dim
            for grau, dim in dims.items()
        )
        euler_h = sum(
            (-1)**grau*valor["dim_H"]
            for grau, valor in cohomologia.items()
        )

        return {
            "tipo": "cohomologia de feixe por complexo de Čech fornecido",
            "dados": {
                "corpo": corpo.upper(),
                "dimensões": dims,
            },
            "pedido": "Calcular H^i=ker d^i/im d^{i−1}",
            "formula": "dim H^i=dim C^i−rank d^i−rank d^{i−1}",
            "passos": [
                "Verificamos a condição d^{i+1}d^i=0.",
                f"Postos: {postos}.",
                f"Dimensões de cohomologia: {cohomologia}.",
            ],
            "resultado": {
                "cohomologia": cohomologia,
                "Euler_cochains": euler_c,
                "Euler_cohomologia": euler_h,
            },
            "verificacao": {
                "complexo_válido": True,
                "Euler_preservada": euler_c == euler_h,
            },
            "observacao": (
                "O resultado corresponde ao complexo fornecido; identificar "
                "esse complexo com cohomologia de um feixe exige uma cobertura "
                "e restrições adequadas."
            ),
        }


class MotorCurvasElipticasLeiGrupoPSF:
    """Lei de grupo sobre Q e contagem de pontos sobre GF(p)."""

    @staticmethod
    def ponto_racional(texto):
        valor = ParserGeometriaAlgebricaPSF.literal(
            texto,
            "ponto elíptico",
        )

        if valor is None or valor in ("O", "o"):
            return None

        if not isinstance(valor, (list, tuple)) or len(valor) != 2:
            raise ValueError("O ponto deve ser (x,y) ou None.")

        return (
            sp.Rational(str(valor[0])),
            sp.Rational(str(valor[1])),
        )

    @staticmethod
    def pertence_q(a, b, p):
        if p is None:
            return True

        x, y = p
        return sp.simplify(y**2-x**3-a*x-b) == 0

    @classmethod
    def somar_q(cls, a, b, p, q):
        if p is None:
            return q, ["O+Q=Q."]
        if q is None:
            return p, ["P+O=P."]

        x1, y1 = p
        x2, y2 = q
        passos = []

        if x1 == x2 and y1 == -y2:
            return None, ["P e Q são opostos; P+Q=O."]

        if p == q:
            if y1 == 0:
                return None, ["A tangente é vertical; 2P=O."]

            lam = sp.simplify(
                (3*x1**2+a)/(2*y1)
            )
            passos.append(
                f"λ=(3x₁²+a)/(2y₁)={sp.sstr(lam)}."
            )
        else:
            lam = sp.simplify(
                (y2-y1)/(x2-x1)
            )
            passos.append(
                f"λ=(y₂−y₁)/(x₂−x₁)={sp.sstr(lam)}."
            )

        x3 = sp.simplify(lam**2-x1-x2)
        y3 = sp.simplify(lam*(x1-x3)-y1)
        r = (x3, y3)
        passos.append(
            f"x₃={sp.sstr(x3)}; y₃={sp.sstr(y3)}."
        )
        return r, passos

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        racional = re.fullmatch(
            r"curva\s+eliptica\s+racional\s+"
            r"([+-]?\d+)\s+([+-]?\d+)\s*;\s*"
            r"(.+?)\s*;\s*(.+)",
            texto,
        )

        if racional:
            a = sp.Integer(racional.group(1))
            b = sp.Integer(racional.group(2))
            discriminante = -16*(4*a**3+27*b**2)

            if discriminante == 0:
                return {"erro": "A curva é singular."}

            try:
                p = self.ponto_racional(racional.group(3))
                q = self.ponto_racional(racional.group(4))
            except ValueError as erro:
                return {"erro": str(erro)}

            if not self.pertence_q(a, b, p):
                return {"erro": "P não pertence à curva."}
            if not self.pertence_q(a, b, q):
                return {"erro": "Q não pertence à curva."}

            r, passos = self.somar_q(a, b, p, q)

            return {
                "tipo": "lei de grupo em curva elíptica sobre Q",
                "dados": {
                    "curva": f"y²=x³+({a})x+({b})",
                    "P": p,
                    "Q": q,
                },
                "pedido": "Calcular P+Q pela lei da corda e tangente",
                "formula": (
                    "x₃=λ²−x₁−x₂; y₃=λ(x₁−x₃)−y₁"
                ),
                "passos": passos,
                "resultado": {
                    "P+Q": (
                        None
                        if r is None
                        else tuple(map(sp.sstr, r))
                    )
                },
                "verificacao": {
                    "resultado_na_curva": self.pertence_q(a, b, r),
                    "discriminante": sp.sstr(discriminante),
                },
            }

        finita = re.fullmatch(
            r"curva\s+eliptica\s+ordem\s+"
            r"(\d+)\s+([+-]?\d+)\s+([+-]?\d+)",
            texto,
        )

        if not finita:
            return None

        p = int(finita.group(1))
        a = int(finita.group(2)) % p
        b = int(finita.group(3)) % p

        try:
            FerramentasCurvaElipticaPSF.validar_curva(p, a, b)
        except ValueError as erro:
            return {"erro": str(erro)}

        pontos = []

        for x in range(p):
            rhs = (x**3+a*x+b) % p

            for y in range(p):
                if y*y % p == rhs:
                    pontos.append((x, y))

        ordem = len(pontos)+1
        limite_hasse = 2*math.sqrt(p)
        desvio = ordem-(p+1)

        return {
            "tipo": "grupo de pontos de curva elíptica sobre corpo finito",
            "dados": {
                "p": p,
                "a": a,
                "b": b,
            },
            "pedido": "Enumerar E(F_p) e calcular a ordem do grupo",
            "formula": "#E(F_p)=1+#{(x,y):y²=x³+ax+b mod p}",
            "passos": [
                "Enumeramos todos os pares (x,y) de GF(p)².",
                f"Pontos afins: {pontos}.",
                "Acrescentamos o ponto no infinito O.",
                f"#E(F_p)={ordem}.",
            ],
            "resultado": {
                "pontos_afins": pontos,
                "ponto_infinito": "O",
                "ordem_grupo": ordem,
                "a_p": p+1-ordem,
            },
            "verificacao": {
                "Hasse": abs(desvio) <= limite_hasse+1e-12,
                "desvio_de_p_mais_1": desvio,
                "limite": limite_hasse,
            },
        }


class MotorSuperficiesRiemannPSF:
    """Gênero por Riemann–Hurwitz em coberturas ramificadas."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"riemann\s+hurwitz\s+"
            r"(\d+)\s+(\d+)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        grau = int(padrao.group(1))
        genero_base = int(padrao.group(2))

        try:
            indices = [
                int(v)
                for v in ParserGeometriaAlgebricaPSF.literal(
                    padrao.group(3),
                    "índices de ramificação",
                )
            ]
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if grau < 1 or genero_base < 0:
            return {"erro": "Grau e gênero base inválidos."}
        if any(e < 1 for e in indices):
            return {"erro": "Cada índice de ramificação deve ser ≥1."}

        ramificacao = sum(e-1 for e in indices)
        dois_g_menos_dois = (
            grau*(2*genero_base-2)+ramificacao
        )
        genero = (dois_g_menos_dois+2)/2
        inteiro = float(genero).is_integer() and genero >= 0

        return {
            "tipo": "superfície de Riemann e fórmula de Riemann–Hurwitz",
            "dados": {
                "grau_cobertura": grau,
                "gênero_base": genero_base,
                "índices_ramificação": indices,
            },
            "pedido": "Calcular o gênero da superfície cobrinte",
            "formula": "2g_X−2=d(2g_Y−2)+Σ(e_p−1)",
            "passos": [
                f"Ramificação total: Σ(e_p−1)={ramificacao}.",
                (
                    f"2g_X−2={grau}×({2*genero_base-2})"
                    f"+{ramificacao}={dois_g_menos_dois}."
                ),
                f"g_X={genero}.",
            ],
            "resultado": {
                "gênero": int(genero) if inteiro else genero,
                "dados_consistentes": inteiro,
                "ramificação_total": ramificacao,
            },
            "verificacao": (
                "O gênero deve ser inteiro não negativo."
            ),
        }


class MotorRiemannRochPSF:
    """Cálculo pela fórmula de Riemann–Roch."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"riemann\s+roch\s+(\d+)\s+([+-]?\d+)"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        genero = int(padrao.group(1))
        grau_d = int(padrao.group(2))
        l_k_menos_d = (
            int(padrao.group(3))
            if padrao.group(3) is not None
            else None
        )

        if genero < 0:
            return {"erro": "O gênero não pode ser negativo."}

        grau_k = 2*genero-2
        termo = grau_d+1-genero

        if l_k_menos_d is not None:
            l_d = termo+l_k_menos_d
            estado = "determinado pelos dados"
            justificacao = None
        elif grau_d < 0:
            l_d = 0
            l_k_menos_d = -termo
            estado = "determinado porque deg(D)<0"
            justificacao = None
        elif grau_d > grau_k:
            l_k_menos_d = 0
            l_d = termo
            estado = "determinado porque deg(K−D)<0"
            justificacao = None
        else:
            l_d = "não determinado"
            estado = "não determinado"
            justificacao = (
                "Na faixa 0≤deg(D)≤2g−2, o grau e o gênero não determinam "
                "sozinhos l(D). É necessário conhecer a classe do divisor, "
                "l(K−D) ou dados geométricos adicionais."
            )

        return {
            "tipo": "Teorema de Riemann–Roch",
            "dados": {
                "gênero": genero,
                "grau_D": grau_d,
                "grau_K": grau_k,
                "l(K−D)_fornecido": (
                    int(padrao.group(3))
                    if padrao.group(3) is not None
                    else None
                ),
            },
            "pedido": "Calcular l(D)",
            "formula": "l(D)−l(K−D)=deg(D)+1−g",
            "passos": [
                f"deg(K)=2g−2={grau_k}.",
                f"deg(D)+1−g={termo}.",
                (
                    f"l(K−D)={l_k_menos_d}."
                    if l_k_menos_d is not None
                    else "l(K−D) não foi determinado pelos dados."
                ),
                f"Estado do cálculo: {estado}.",
            ],
            "resultado": {
                "l(D)": l_d,
                "l(K−D)": l_k_menos_d,
            },
            "verificacao": (
                (
                    f"{l_d}−{l_k_menos_d}={termo}."
                )
                if isinstance(l_d, int) and isinstance(l_k_menos_d, int)
                else "A igualdade não pode ser fechada sem dados adicionais."
            ),
            "justificacao": justificacao,
        }


class MotorECCAplicacoesPSF:
    """ECDSA didático com parâmetros e nonce fornecidos externamente."""

    @staticmethod
    def hash_reduzido(valor, n):
        return int(valor) % n

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        assinar = re.fullmatch(
            r"ecdsa\s+assinar\s+"
            r"(\d+)\s+([+-]?\d+)\s+([+-]?\d+)\s*;\s*"
            r"(.+?)\s*;\s*(\d+)\s*;\s*(\d+)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)",
            texto,
        )

        if assinar:
            p = int(assinar.group(1))
            a = int(assinar.group(2)) % p
            b = int(assinar.group(3)) % p

            try:
                g = FerramentasCurvaElipticaPSF.ponto(
                    assinar.group(4)
                )
                FerramentasCurvaElipticaPSF.validar_curva(p, a, b)
            except ValueError as erro:
                return {"erro": str(erro)}

            n = int(assinar.group(5))
            d = int(assinar.group(6))
            z = self.hash_reduzido(assinar.group(7), n)
            k = int(assinar.group(8))

            if not FerramentasCurvaElipticaPSF.pertence(p, a, b, g):
                return {"erro": "G não pertence à curva."}
            if n <= 1 or not (1 <= d < n) or not (1 <= k < n):
                return {"erro": "Exige-se n>1, 1≤d<n e 1≤k<n."}
            if math.gcd(k, n) != 1:
                return {"erro": "O nonce k deve ser invertível módulo n."}

            r_ponto, trilha_r = FerramentasCurvaElipticaPSF.multiplicar(
                p, a, b, k, g
            )

            if r_ponto is None:
                return {"erro": "kG resultou no ponto no infinito."}

            r = r_ponto[0] % n

            if r == 0:
                return {"erro": "A assinatura produziu r=0; escolha outro k."}

            s = (
                pow(k, -1, n)*(z+r*d)
            ) % n

            if s == 0:
                return {"erro": "A assinatura produziu s=0; escolha outro k."}

            q, trilha_q = FerramentasCurvaElipticaPSF.multiplicar(
                p, a, b, d, g
            )

            return {
                "tipo": "assinatura ECDSA didática",
                "dados": {
                    "curva": [p, a, b],
                    "G": g,
                    "ordem_n": n,
                    "chave_privada_d": d,
                    "hash_z": z,
                    "nonce_k": k,
                },
                "pedido": "Calcular a chave pública e a assinatura (r,s)",
                "formula": "R=kG; r=x_R mod n; s=k⁻¹(z+rd) mod n",
                "passos": [
                    f"Q=dG={q}; trilha: {trilha_q}.",
                    f"R=kG={r_ponto}; trilha: {trilha_r}.",
                    f"r={r_ponto[0]} mod {n}={r}.",
                    f"k⁻¹ mod n={pow(k, -1, n)}.",
                    f"s={s}.",
                ],
                "resultado": {
                    "chave_pública_Q": q,
                    "assinatura": [r, s],
                },
                "verificacao": (
                    "r e s estão no intervalo 1,...,n−1."
                ),
                "observacao": (
                    "Implementação educacional. Reutilizar ou expor k revela "
                    "a chave privada; sistemas reais exigem curvas, hashes, "
                    "validação e geração de nonce padronizados."
                ),
            }

        verificar = re.fullmatch(
            r"ecdsa\s+verificar\s+"
            r"(\d+)\s+([+-]?\d+)\s+([+-]?\d+)\s*;\s*"
            r"(.+?)\s*;\s*(\d+)\s*;\s*(.+?)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)\s*;\s*(\d+)",
            texto,
        )

        if not verificar:
            return None

        p = int(verificar.group(1))
        a = int(verificar.group(2)) % p
        b = int(verificar.group(3)) % p

        try:
            g = FerramentasCurvaElipticaPSF.ponto(
                verificar.group(4)
            )
            q = FerramentasCurvaElipticaPSF.ponto(
                verificar.group(6)
            )
            FerramentasCurvaElipticaPSF.validar_curva(p, a, b)
        except ValueError as erro:
            return {"erro": str(erro)}

        n = int(verificar.group(5))
        z = self.hash_reduzido(verificar.group(7), n)
        r = int(verificar.group(8))
        s = int(verificar.group(9))

        if not (
            FerramentasCurvaElipticaPSF.pertence(p, a, b, g)
            and FerramentasCurvaElipticaPSF.pertence(p, a, b, q)
        ):
            return {"erro": "G ou Q não pertence à curva."}

        if not (1 <= r < n and 1 <= s < n) or math.gcd(s, n) != 1:
            valido = False
            ponto = None
            u1 = u2 = None
            trilha = ["r/s fora do intervalo ou s não invertível."]
        else:
            w = pow(s, -1, n)
            u1 = z*w % n
            u2 = r*w % n
            p1, trilha1 = FerramentasCurvaElipticaPSF.multiplicar(
                p, a, b, u1, g
            )
            p2, trilha2 = FerramentasCurvaElipticaPSF.multiplicar(
                p, a, b, u2, q
            )
            trilha = [
                f"w=s⁻¹ mod n={w}.",
                f"u1=zw mod n={u1}.",
                f"u2=rw mod n={u2}.",
                f"u1G={p1}; trilha: {trilha1}.",
                f"u2Q={p2}; trilha: {trilha2}.",
            ]
            soma_trilha = []
            ponto = FerramentasCurvaElipticaPSF.somar(
                p, a, b, p1, p2, soma_trilha
            )
            trilha.extend(soma_trilha)
            valido = (
                ponto is not None
                and ponto[0] % n == r
            )

        return {
            "tipo": "verificação ECDSA didática",
            "dados": {
                "curva": [p, a, b],
                "G": g,
                "n": n,
                "Q": q,
                "hash_z": z,
                "assinatura": [r, s],
            },
            "pedido": "Verificar a assinatura (r,s)",
            "formula": (
                "w=s⁻¹; u1=zw; u2=rw; X=u1G+u2Q; "
                "válida ⇔ x_X mod n=r"
            ),
            "passos": trilha,
            "resultado": {
                "assinatura_válida": valido,
                "ponto_verificação": ponto,
                "u1": u1,
                "u2": u2,
            },
            "verificacao": (
                (
                    f"x_X mod n={ponto[0] % n}=r."
                    if valido and ponto is not None
                    else "A igualdade final de verificação falhou."
                )
            ),
            "observacao": (
                "Implementação educacional; não deve ser usada como "
                "biblioteca criptográfica de produção."
            ),
        }



class ParserOtimizacaoRedesPSF:
    """Leitura segura de problemas de otimização, filas e redes."""

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @classmethod
    def vetor_float(cls, valor, nome="vetor"):
        try:
            vetor = np.asarray(valor, dtype=float)
        except (TypeError, ValueError) as erro:
            raise ValueError(f"{nome.capitalize()} deve ser numérico.") from erro

        if vetor.ndim != 1 or len(vetor) == 0:
            raise ValueError(f"{nome.capitalize()} deve ser unidimensional e não vazio.")
        if not np.isfinite(vetor).all():
            raise ValueError(f"{nome.capitalize()} contém valor não finito.")

        return vetor

    @classmethod
    def matriz_float(cls, valor, nome="matriz", permitir_vazia=False):
        if valor is None and permitir_vazia:
            return None

        try:
            matriz = np.asarray(valor, dtype=float)
        except (TypeError, ValueError) as erro:
            raise ValueError(f"{nome.capitalize()} deve ser numérica.") from erro

        if permitir_vazia and matriz.size == 0:
            return None
        if matriz.ndim != 2 or matriz.shape[0] == 0 or matriz.shape[1] == 0:
            raise ValueError(f"{nome.capitalize()} deve ser bidimensional e não vazia.")
        if not np.isfinite(matriz).all():
            raise ValueError(f"{nome.capitalize()} contém valor não finito.")

        return matriz

    @classmethod
    def problema_linear(cls, texto):
        dados = cls.literal(texto, "problema linear")

        if not isinstance(dados, dict):
            raise ValueError("O problema linear deve ser um dicionário.")

        c = cls.vetor_float(dados.get("c"), "vetor de custos")
        a_ub = cls.matriz_float(
            dados.get("A_ub"),
            "A_ub",
            permitir_vazia=True,
        )
        b_ub = (
            cls.vetor_float(dados.get("b_ub"), "b_ub")
            if a_ub is not None
            else None
        )
        a_eq = cls.matriz_float(
            dados.get("A_eq"),
            "A_eq",
            permitir_vazia=True,
        )
        b_eq = (
            cls.vetor_float(dados.get("b_eq"), "b_eq")
            if a_eq is not None
            else None
        )

        if a_ub is not None:
            if a_ub.shape[1] != len(c) or len(b_ub) != a_ub.shape[0]:
                raise ValueError("Dimensões incompatíveis entre A_ub, b_ub e c.")

        if a_eq is not None:
            if a_eq.shape[1] != len(c) or len(b_eq) != a_eq.shape[0]:
                raise ValueError("Dimensões incompatíveis entre A_eq, b_eq e c.")

        limites_brutos = dados.get("bounds")

        if limites_brutos is None:
            limites = [(0, None)]*len(c)
        else:
            if len(limites_brutos) != len(c):
                raise ValueError("bounds deve possuir um par por variável.")

            limites = []

            for limite in limites_brutos:
                if limite is None:
                    limites.append((None, None))
                    continue

                if not isinstance(limite, (list, tuple)) or len(limite) != 2:
                    raise ValueError("Cada limite deve ser (inferior, superior).")

                inferior = None if limite[0] is None else float(limite[0])
                superior = None if limite[1] is None else float(limite[1])

                if (
                    inferior is not None
                    and superior is not None
                    and inferior > superior
                ):
                    raise ValueError("Limite inferior maior que o superior.")

                limites.append((inferior, superior))

        sentido = str(dados.get("sentido", "min")).lower()

        if sentido not in ("min", "max"):
            raise ValueError("sentido deve ser 'min' ou 'max'.")

        return {
            "c": c,
            "A_ub": a_ub,
            "b_ub": b_ub,
            "A_eq": a_eq,
            "b_eq": b_eq,
            "bounds": limites,
            "sentido": sentido,
            "inteiras": [
                int(v)
                for v in dados.get("inteiras", [])
            ],
        }

    @staticmethod
    def resultado_linprog(resultado, sentido):
        valor = None

        if resultado.success:
            valor = float(resultado.fun)

            if sentido == "max":
                valor = -valor

        return {
            "sucesso": bool(resultado.success),
            "estado": int(resultado.status),
            "mensagem": str(resultado.message),
            "x": (
                resultado.x.tolist()
                if resultado.success and resultado.x is not None
                else None
            ),
            "valor_objetivo": valor,
            "iterações": (
                int(resultado.nit)
                if getattr(resultado, "nit", None) is not None
                else None
            ),
        }


class MotorOtimizacaoLinearPSF:
    """Programação linear geral e dualidade da forma canônica."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"otimizacao\s+linear\s+")

        if payload is None:
            return None

        try:
            problema = ParserOtimizacaoRedesPSF.problema_linear(
                payload
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        c_original = problema["c"]
        c_scipy = (
            -c_original
            if problema["sentido"] == "max"
            else c_original
        )

        resultado = scipy_linprog(
            c_scipy,
            A_ub=problema["A_ub"],
            b_ub=problema["b_ub"],
            A_eq=problema["A_eq"],
            b_eq=problema["b_eq"],
            bounds=problema["bounds"],
            method="highs",
        )
        primal = ParserOtimizacaoRedesPSF.resultado_linprog(
            resultado,
            problema["sentido"],
        )
        dual = None
        folgas = None
        complementaridade = None

        if resultado.success:
            if problema["A_ub"] is not None:
                folgas = (
                    problema["b_ub"]
                    - problema["A_ub"]@resultado.x
                ).tolist()

            # Dual explícito para max c^T x, Ax<=b, x>=0.
            forma_canonica_dual = (
                problema["sentido"] == "max"
                and problema["A_ub"] is not None
                and problema["A_eq"] is None
                and all(
                    inferior == 0 and superior is None
                    for inferior, superior in problema["bounds"]
                )
            )

            if forma_canonica_dual:
                dual_resultado = scipy_linprog(
                    problema["b_ub"],
                    A_ub=-problema["A_ub"].T,
                    b_ub=-c_original,
                    bounds=[(0, None)]*len(problema["b_ub"]),
                    method="highs",
                )
                dual = ParserOtimizacaoRedesPSF.resultado_linprog(
                    dual_resultado,
                    "min",
                )

                if dual_resultado.success:
                    y = dual_resultado.x
                    reduzidos = (
                        problema["A_ub"].T@y-c_original
                    )
                    complementaridade = {
                        "y_i_folga_i": (
                            y*np.asarray(folgas)
                        ).tolist(),
                        "x_j_custo_reduzido_j": (
                            resultado.x*reduzidos
                        ).tolist(),
                        "diferença_primal_dual": abs(
                            primal["valor_objetivo"]
                            - dual["valor_objetivo"]
                        ),
                    }

        passos = [
            f"Sentido do problema: {problema['sentido']}.",
            f"Vetor objetivo c={c_original.tolist()}.",
            (
                f"Restrições de desigualdade: "
                f"{None if problema['A_ub'] is None else problema['A_ub'].tolist()} "
                f"≤ {None if problema['b_ub'] is None else problema['b_ub'].tolist()}."
            ),
            (
                f"Restrições de igualdade: "
                f"{None if problema['A_eq'] is None else problema['A_eq'].tolist()} "
                f"= {None if problema['b_eq'] is None else problema['b_eq'].tolist()}."
            ),
            f"Limites das variáveis: {problema['bounds']}.",
            f"Estado do solucionador: {primal['mensagem']}.",
        ]

        if primal["sucesso"]:
            passos.extend([
                f"Solução primal x={primal['x']}.",
                f"Valor ótimo={primal['valor_objetivo']}.",
                f"Folgas={folgas}.",
            ])

        if dual is not None:
            passos.extend([
                f"Solução dual y={dual['x']}.",
                f"Valor dual={dual['valor_objetivo']}.",
                f"Complementaridade={complementaridade}.",
            ])

        return {
            "tipo": "otimização linear e dualidade",
            "dados": {
                "variáveis": len(c_original),
                "sentido": problema["sentido"],
            },
            "pedido": "Resolver o programa linear e verificar dualidade quando aplicável",
            "formula": (
                "primal canônico: max cᵀx, Ax≤b, x≥0; "
                "dual: min bᵀy, Aᵀy≥c, y≥0"
            ),
            "passos": passos,
            "resultado": {
                "primal": primal,
                "dual_canônico": dual,
                "folgas": folgas,
                "complementaridade": complementaridade,
            },
            "verificacao": (
                (
                    "Ótimo primal encontrado e condições de viabilidade verificadas."
                    if primal["sucesso"]
                    else primal["mensagem"]
                )
            ),
            "observacao": (
                "O dual explícito é construído apenas para a forma canônica "
                "max Ax≤b, x≥0. Outras formas são resolvidas pelo solucionador, "
                "mas não recebem esta apresentação dual simplificada."
            ),
        }


class MotorSimplexTableauPSF:
    """Método simplex por tableau para max cᵀx, Ax≤b, x≥0."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"simplex\s+tableau\s+")

        if payload is None:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                payload,
                "problema simplex",
            )
            c = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("c"),
                "c",
            )
            a = ParserOtimizacaoRedesPSF.matriz_float(
                dados.get("A"),
                "A",
            )
            b = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("b"),
                "b",
            )
        except (ValueError, AttributeError) as erro:
            return {"erro": str(erro)}

        if a.shape != (len(b), len(c)):
            return {"erro": "A deve possuir forma m×n compatível com b e c."}
        if np.any(b < 0):
            return {
                "erro": (
                    "Esta implementação exige b≥0 para iniciar com as folgas "
                    "como base viável."
                )
            }
        if len(c) > 100 or len(b) > 100:
            return {"erro": "O tableau está limitado a 100 variáveis e 100 restrições."}

        m, n = a.shape
        tableau = np.zeros((m+1, n+m+1), dtype=float)
        tableau[:m, :n] = a
        tableau[:m, n:n+m] = np.eye(m)
        tableau[:m, -1] = b
        tableau[-1, :n] = -c
        base = list(range(n, n+m))
        historico = []
        limite = int(dados.get("max_iter", 1000))
        estado = "ótimo"

        for iteracao in range(limite):
            custos = tableau[-1, :-1]
            coluna = int(np.argmin(custos))

            if custos[coluna] >= -1e-12:
                break

            coeficientes = tableau[:m, coluna]
            candidatos = [
                (
                    tableau[linha, -1]/coeficientes[linha],
                    linha,
                )
                for linha in range(m)
                if coeficientes[linha] > 1e-12
            ]

            if not candidatos:
                estado = "ilimitado"
                break

            _, linha = min(
                candidatos,
                key=lambda item: (item[0], item[1]),
            )
            pivot = tableau[linha, coluna]
            antes_base = base[linha]
            tableau[linha] /= pivot

            for outra in range(m+1):
                if outra == linha:
                    continue

                tableau[outra] -= (
                    tableau[outra, coluna]*tableau[linha]
                )

            base[linha] = coluna

            if len(historico) < 300:
                historico.append({
                    "iteração": iteracao+1,
                    "entra": coluna,
                    "sai": antes_base,
                    "pivô": pivot,
                    "base": base[:],
                    "tableau": tableau.tolist(),
                })
        else:
            estado = "limite de iterações"

        x = np.zeros(n+m)

        if estado == "ótimo":
            for linha, variavel in enumerate(base):
                x[variavel] = tableau[linha, -1]

            valor = float(tableau[-1, -1])
            solucao = x[:n].tolist()
        else:
            valor = None
            solucao = None

        return {
            "tipo": "método simplex por tableau",
            "dados": {
                "c": c.tolist(),
                "A": a.tolist(),
                "b": b.tolist(),
            },
            "pedido": "Executar pivoteamentos até ao tableau ótimo",
            "formula": (
                "entra uma coluna de custo reduzido negativo; "
                "sai pela razão mínima positiva"
            ),
            "passos": [
                "Acrescentamos uma variável de folga por restrição.",
                f"Tableau inicial: {historico[0]['tableau'] if historico else tableau.tolist()}.",
                f"Pivoteamentos: {historico}.",
                f"Estado final: {estado}.",
            ],
            "resultado": {
                "estado": estado,
                "x": solucao,
                "valor_objetivo": valor,
                "base_final": base,
                "tableau_final": tableau.tolist(),
                "iterações": len(historico),
            },
            "verificacao": (
                (
                    {
                        "Ax≤b": bool(np.all(a@np.asarray(solucao) <= b+1e-8)),
                        "x≥0": bool(np.all(np.asarray(solucao) >= -1e-8)),
                        "cTx": float(c@np.asarray(solucao)),
                    }
                    if solucao is not None
                    else estado
                )
            ),
            "justificacao": (
                "O limite de pivoteamentos foi atingido antes de um tableau "
                "ótimo ou de uma prova de ilimitabilidade. O resultado fica "
                "não determinado sem aumentar o limite ou usar regra anti-ciclagem."
                if estado == "limite de iterações"
                else None
            ),
        }


class MotorOtimizacaoInteiraPSF:
    """Branch-and-bound usando relaxações lineares."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"branch\s+and\s+bound\s+")

        if payload is None:
            return None

        try:
            problema = ParserOtimizacaoRedesPSF.problema_linear(
                payload
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        n = len(problema["c"])
        inteiras = sorted(set(problema["inteiras"] or range(n)))

        if any(indice < 0 or indice >= n for indice in inteiras):
            return {"erro": "Índice de variável inteira fora do intervalo."}

        limite_nos = 10000
        tolerancia = 1e-8
        c_scipy = (
            -problema["c"]
            if problema["sentido"] == "max"
            else problema["c"]
        )
        melhor_x = None
        melhor_valor = (
            -math.inf
            if problema["sentido"] == "max"
            else math.inf
        )
        fila = []
        contador = itertools.count()
        heapq.heappush(
            fila,
            (0.0, next(contador), problema["bounds"], 0),
        )
        nos = []
        explorados = 0

        def valor_original(fun):
            return -float(fun) if problema["sentido"] == "max" else float(fun)

        def pior_que_incumbente(valor):
            if melhor_x is None:
                return False

            if problema["sentido"] == "max":
                return valor <= melhor_valor+tolerancia

            return valor >= melhor_valor-tolerancia

        while fila and explorados < limite_nos:
            _, _, limites, profundidade = heapq.heappop(fila)
            explorados += 1
            relaxacao = scipy_linprog(
                c_scipy,
                A_ub=problema["A_ub"],
                b_ub=problema["b_ub"],
                A_eq=problema["A_eq"],
                b_eq=problema["b_eq"],
                bounds=limites,
                method="highs",
            )

            registro = {
                "nó": explorados,
                "profundidade": profundidade,
                "bounds": limites,
                "sucesso": bool(relaxacao.success),
                "mensagem": str(relaxacao.message),
            }

            if not relaxacao.success:
                registro["ação"] = "podado por inviabilidade"
                nos.append(registro)
                continue

            valor = valor_original(relaxacao.fun)
            registro["limite_relaxação"] = valor
            registro["x_relaxação"] = relaxacao.x.tolist()

            if pior_que_incumbente(valor):
                registro["ação"] = "podado pelo limite"
                nos.append(registro)
                continue

            fracionarias = [
                indice
                for indice in inteiras
                if abs(
                    relaxacao.x[indice]-round(relaxacao.x[indice])
                ) > tolerancia
            ]

            if not fracionarias:
                candidato = relaxacao.x.copy()
                candidato[inteiras] = np.round(candidato[inteiras])

                if (
                    melhor_x is None
                    or (
                        problema["sentido"] == "max"
                        and valor > melhor_valor+tolerancia
                    )
                    or (
                        problema["sentido"] == "min"
                        and valor < melhor_valor-tolerancia
                    )
                ):
                    melhor_x = candidato
                    melhor_valor = valor
                    registro["ação"] = "novo incumbente"
                else:
                    registro["ação"] = "solução inteira não melhor"

                nos.append(registro)
                continue

            indice = max(
                fracionarias,
                key=lambda j: abs(
                    relaxacao.x[j]-round(relaxacao.x[j])
                ),
            )
            valor_frac = relaxacao.x[indice]
            piso = math.floor(valor_frac)
            teto = math.ceil(valor_frac)
            filhos = []

            for lado, novo_limite in (
                ("≤", piso),
                ("≥", teto),
            ):
                novos = list(limites)
                inferior, superior = novos[indice]

                if lado == "≤":
                    superior_novo = (
                        novo_limite
                        if superior is None
                        else min(superior, novo_limite)
                    )
                    novos[indice] = (inferior, superior_novo)
                else:
                    inferior_novo = (
                        novo_limite
                        if inferior is None
                        else max(inferior, novo_limite)
                    )
                    novos[indice] = (inferior_novo, superior)

                inf, sup = novos[indice]

                if inf is not None and sup is not None and inf > sup:
                    continue

                prioridade = (
                    -valor
                    if problema["sentido"] == "max"
                    else valor
                )
                heapq.heappush(
                    fila,
                    (
                        prioridade,
                        next(contador),
                        novos,
                        profundidade+1,
                    ),
                )
                filhos.append({
                    "variável": indice,
                    "ramo": lado,
                    "limite": novo_limite,
                })

            registro["ação"] = "ramificar"
            registro["variável_ramificada"] = indice
            registro["valor_fracionário"] = valor_frac
            registro["filhos"] = filhos
            nos.append(registro)

        completo = not fila
        estado = (
            "ótimo inteiro"
            if melhor_x is not None and completo
            else (
                "não determinado"
                if fila
                else "inviável"
            )
        )

        return {
            "tipo": "otimização inteira por branch-and-bound",
            "dados": {
                "variáveis_inteiras": inteiras,
                "sentido": problema["sentido"],
                "limite_nós": limite_nos,
            },
            "pedido": "Resolver o problema inteiro por relaxações e ramificações",
            "formula": (
                "resolver relaxação LP; podar por inviabilidade/limite; "
                "ramificar x_j≤⌊x_j*⌋ ou x_j≥⌈x_j*⌉"
            ),
            "passos": [
                f"Nós explorados: {explorados}.",
                f"Registos: {nos[:1000]}.",
                f"Nós ainda pendentes: {len(fila)}.",
            ],
            "resultado": {
                "estado": estado,
                "x": (
                    melhor_x.tolist()
                    if melhor_x is not None
                    else None
                ),
                "valor_objetivo": (
                    melhor_valor
                    if melhor_x is not None
                    else None
                ),
                "nós_explorados": explorados,
                "busca_completa": completo,
            },
            "verificacao": (
                (
                    "Todas as variáveis indicadas são inteiras e a árvore foi esgotada."
                    if melhor_x is not None and completo
                    else estado
                )
            ),
            "justificacao": (
                "O limite de nós foi atingido antes de esgotar a árvore. "
                "Existe um incumbente possível, mas a otimalidade global não "
                "foi demonstrada; por isso o resultado fica não determinado."
                if fila
                else None
            ),
        }


class ParserNaoLinearPSF:
    """Expressões multivariadas para otimização diferenciável."""

    @staticmethod
    def preparar(expressao_texto, variaveis_texto):
        variaveis_nomes = [
            str(v)
            for v in variaveis_texto
        ]

        if not variaveis_nomes:
            raise ValueError("Forneça ao menos uma variável.")
        if len(set(variaveis_nomes)) != len(variaveis_nomes):
            raise ValueError("Os nomes das variáveis devem ser distintos.")
        if any(
            not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", nome)
            for nome in variaveis_nomes
        ):
            raise ValueError("Nome de variável inválido.")

        simbolos = sp.symbols(
            " ".join(variaveis_nomes),
            real=True,
        )

        if len(variaveis_nomes) == 1:
            simbolos = (simbolos,)

        expressao = str(expressao_texto).replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            raise ValueError("Expressão contém símbolos não permitidos.")

        locais = {
            str(simbolo): simbolo
            for simbolo in simbolos
        }
        locais.update({
            "sin": sp.sin,
            "sen": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "abs": sp.Abs,
            "pi": sp.pi,
            "e": sp.E,
        })

        try:
            expr = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            raise ValueError("Função objetivo inválida.") from erro

        if expr.free_symbols - set(simbolos):
            raise ValueError("A expressão contém variável não declarada.")

        gradiente = sp.Matrix([
            sp.diff(expr, simbolo)
            for simbolo in simbolos
        ])
        hessiana = sp.hessian(expr, simbolos)
        funcao = sp.lambdify(
            (simbolos,),
            expr,
            modules=["numpy"],
        )
        grad = sp.lambdify(
            (simbolos,),
            gradiente,
            modules=["numpy"],
        )
        hess = sp.lambdify(
            (simbolos,),
            hessiana,
            modules=["numpy"],
        )

        return simbolos, expr, gradiente, hessiana, funcao, grad, hess


class MotorOtimizacaoNaoLinearPSF:
    """Otimização por gradiente/Newton e análise da Hessiana."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"otimizacao\s+nao\s+linear\s+")

        if payload is None:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                payload,
                "problema não linear",
            )
            variaveis = list(dados.get("variaveis", []))
            inicial = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("inicial"),
                "ponto inicial",
            )
            (
                simbolos,
                expr,
                grad_expr,
                hess_expr,
                funcao,
                grad,
                hess,
            ) = ParserNaoLinearPSF.preparar(
                dados.get("funcao"),
                variaveis,
            )
        except (ValueError, AttributeError) as erro:
            return {"erro": str(erro)}

        if len(inicial) != len(simbolos):
            return {"erro": "O ponto inicial deve ter uma coordenada por variável."}

        metodo = str(dados.get("metodo", "bfgs")).lower()
        mapa_metodos = {
            "bfgs": "BFGS",
            "newton": "trust-exact",
            "cg": "CG",
            "nelder-mead": "Nelder-Mead",
        }

        if metodo not in mapa_metodos:
            return {
                "erro": (
                    "Método deve ser bfgs, newton, cg ou nelder-mead."
                )
            }

        sentido = str(dados.get("sentido", "min")).lower()

        if sentido not in ("min", "max"):
            return {"erro": "sentido deve ser min ou max."}

        sinal = -1.0 if sentido == "max" else 1.0

        def f_np(x):
            return sinal*float(np.asarray(funcao(x)).reshape(-1)[0])

        def g_np(x):
            return sinal*np.asarray(
                grad(x),
                dtype=float,
            ).reshape(-1)

        def h_np(x):
            return sinal*np.asarray(
                hess(x),
                dtype=float,
            )

        argumentos = {
            "fun": f_np,
            "x0": inicial,
            "method": mapa_metodos[metodo],
            "options": {
                "maxiter": int(dados.get("max_iter", 5000)),
            },
        }

        if metodo not in ("nelder-mead",):
            argumentos["jac"] = g_np

        if metodo == "newton":
            argumentos["hess"] = h_np

        limites = dados.get("bounds")

        if limites is not None:
            argumentos["bounds"] = limites

        resultado = scipy_minimize(**argumentos)
        x_otimo = np.asarray(resultado.x, dtype=float)
        valor_original = float(np.asarray(funcao(x_otimo)).reshape(-1)[0])
        grad_final = np.asarray(
            grad(x_otimo),
            dtype=float,
        ).reshape(-1)
        hess_final = np.asarray(
            hess(x_otimo),
            dtype=float,
        )
        autovalores = np.linalg.eigvalsh(
            (hess_final+hess_final.T)/2
        )

        if np.all(autovalores > 1e-8):
            tipo_ponto = "mínimo local estrito"
        elif np.all(autovalores < -1e-8):
            tipo_ponto = "máximo local estrito"
        elif np.any(autovalores > 1e-8) and np.any(autovalores < -1e-8):
            tipo_ponto = "ponto de sela"
        else:
            tipo_ponto = "não determinado"

        return {
            "tipo": "otimização não linear diferenciável",
            "dados": {
                "função": sp.sstr(expr),
                "variáveis": [str(v) for v in simbolos],
                "ponto_inicial": inicial.tolist(),
                "método": metodo,
                "sentido": sentido,
            },
            "pedido": "Encontrar ponto estacionário e classificá-lo",
            "formula": "∇f(x*)≈0; a Hessiana classifica a curvatura local",
            "passos": [
                f"Gradiente simbólico: {[sp.sstr(v) for v in grad_expr]}.",
                f"Hessiana simbólica: {hess_expr.tolist()}.",
                f"Mensagem do otimizador: {resultado.message}.",
                f"Ponto encontrado: {x_otimo.tolist()}.",
                f"Gradiente final: {grad_final.tolist()}.",
                f"Autovalores da Hessiana: {autovalores.tolist()}.",
            ],
            "resultado": {
                "sucesso": bool(resultado.success),
                "x": x_otimo.tolist(),
                "valor": valor_original,
                "norma_gradiente": float(np.linalg.norm(grad_final)),
                "Hessiana": hess_final.tolist(),
                "autovalores_Hessiana": autovalores.tolist(),
                "classificação_local": tipo_ponto,
                "iterações": int(getattr(resultado, "nit", 0)),
            },
            "verificacao": {
                "gradiente_pequeno": float(np.linalg.norm(grad_final)) < 1e-6,
                "mensagem": str(resultado.message),
            },
            "justificacao": (
                "A Hessiana possui autovalor próximo de zero. O teste de "
                "segunda ordem é degenerado e não determina a natureza local; "
                "termos de ordem superior ou outra análise são necessários."
                if tipo_ponto == "não determinado"
                else None
            ),
        }


class MotorOtimizacaoConvexaPSF:
    """Programação quadrática convexa e certificado espectral."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"otimizacao\s+convexa\s+quadratica\s+")

        if payload is None:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                payload,
                "problema quadrático",
            )
            q = ParserOtimizacaoRedesPSF.matriz_float(
                dados.get("Q"),
                "Q",
            )
            c = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("c"),
                "c",
            )
        except (ValueError, AttributeError) as erro:
            return {"erro": str(erro)}

        if q.shape != (len(c), len(c)):
            return {"erro": "Q deve ser quadrada e compatível com c."}

        q_simetrica = (q+q.T)/2
        autovalores = np.linalg.eigvalsh(q_simetrica)
        convexa = bool(np.min(autovalores) >= -1e-10)
        estritamente = bool(np.min(autovalores) > 1e-10)
        bounds = dados.get("bounds")
        inicial = np.asarray(
            dados.get("inicial", np.zeros(len(c))),
            dtype=float,
        )

        if inicial.shape != (len(c),):
            return {"erro": "Ponto inicial incompatível."}

        def objetivo(x):
            return 0.5*float(x@q_simetrica@x)+float(c@x)

        def jac(x):
            return q_simetrica@x+c

        resultado = scipy_minimize(
            objetivo,
            inicial,
            jac=jac,
            method="L-BFGS-B" if bounds is not None else "BFGS",
            bounds=bounds,
            options={"maxiter": int(dados.get("max_iter", 5000))},
        )
        x = np.asarray(resultado.x, dtype=float)

        if bounds is None and estritamente:
            x_analitico = np.linalg.solve(q_simetrica, -c)
        elif bounds is None and convexa:
            x_analitico = np.linalg.pinv(q_simetrica)@(-c)
        else:
            x_analitico = None

        return {
            "tipo": "otimização convexa quadrática",
            "dados": {
                "Q": q.tolist(),
                "c": c.tolist(),
                "bounds": bounds,
            },
            "pedido": "Certificar convexidade e minimizar a função quadrática",
            "formula": "f(x)=½xᵀQx+cᵀx; convexa ⇔ Q_s≽0",
            "passos": [
                f"Parte simétrica Q_s={q_simetrica.tolist()}.",
                f"Autovalores={autovalores.tolist()}.",
                f"Convexa={convexa}; estritamente convexa={estritamente}.",
                f"Solução numérica x={x.tolist()}.",
                f"Solução linear sem limites={None if x_analitico is None else x_analitico.tolist()}.",
            ],
            "resultado": {
                "convexa": convexa,
                "estritamente_convexa": estritamente,
                "x_ótimo": x.tolist(),
                "valor_ótimo": objetivo(x),
                "gradiente_final": jac(x).tolist(),
                "solução_analítica_sem_limites": (
                    x_analitico.tolist()
                    if x_analitico is not None
                    else None
                ),
                "sucesso_otimizador": bool(resultado.success),
            },
            "verificacao": {
                "mínimo_autovalor": float(np.min(autovalores)),
                "norma_gradiente": float(np.linalg.norm(jac(x))),
            },
            "observacao": (
                "Se Q não for semidefinida positiva, o problema não é "
                "certificado como convexo e o ponto numérico pode ser apenas local."
            ),
        }


class MotorAlgoritmosGeneticosPSF:
    """Algoritmo genético real para funções multivariadas."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"algoritmo\s+genetico\s+")

        if payload is None:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                payload,
                "configuração genética",
            )
            variaveis = list(dados.get("variaveis", []))
            (
                simbolos,
                expr,
                _,
                _,
                funcao,
                _,
                _,
            ) = ParserNaoLinearPSF.preparar(
                dados.get("funcao"),
                variaveis,
            )
            limites = np.asarray(
                dados.get("bounds"),
                dtype=float,
            )
        except (ValueError, AttributeError, TypeError) as erro:
            return {"erro": str(erro)}

        if limites.shape != (len(simbolos), 2):
            return {"erro": "bounds deve possuir um par por variável."}
        if np.any(limites[:, 0] >= limites[:, 1]):
            return {"erro": "Cada limite inferior deve ser menor que o superior."}

        populacao_tamanho = int(dados.get("populacao", 100))
        geracoes = int(dados.get("geracoes", 200))
        semente = int(dados.get("semente", 0))
        mutacao = float(dados.get("mutacao", 0.1))
        elitismo = max(1, int(dados.get("elitismo", 2)))
        sentido = str(dados.get("sentido", "min")).lower()

        if sentido not in ("min", "max"):
            return {"erro": "sentido deve ser min ou max."}
        if not (10 <= populacao_tamanho <= 10000):
            return {"erro": "populacao deve estar entre 10 e 10000."}
        if not (1 <= geracoes <= 100000):
            return {"erro": "geracoes deve estar entre 1 e 100000."}
        if not (0 <= mutacao <= 1):
            return {"erro": "mutacao deve estar entre 0 e 1."}

        elitismo = min(elitismo, populacao_tamanho)
        rng = np.random.default_rng(semente)
        inferior = limites[:, 0]
        superior = limites[:, 1]
        amplitude = superior-inferior
        populacao = rng.uniform(
            inferior,
            superior,
            size=(populacao_tamanho, len(simbolos)),
        )
        historico = []
        melhor_global = None
        melhor_valor = math.inf if sentido == "min" else -math.inf

        def avaliar(individuos):
            valores = np.empty(len(individuos), dtype=float)

            for i, individuo in enumerate(individuos):
                try:
                    valores[i] = float(
                        np.asarray(funcao(individuo)).reshape(-1)[0]
                    )
                except Exception:
                    valores[i] = (
                        math.inf
                        if sentido == "min"
                        else -math.inf
                    )

            return valores

        for geracao in range(geracoes):
            valores = avaliar(populacao)
            ordem = np.argsort(valores)

            if sentido == "max":
                ordem = ordem[::-1]

            populacao = populacao[ordem]
            valores = valores[ordem]
            candidato = populacao[0].copy()
            valor_candidato = float(valores[0])
            melhorou = (
                valor_candidato < melhor_valor
                if sentido == "min"
                else valor_candidato > melhor_valor
            )

            if melhorou:
                melhor_global = candidato
                melhor_valor = valor_candidato

            if geracao < 200 or geracao == geracoes-1:
                historico.append({
                    "geração": geracao,
                    "melhor": valor_candidato,
                    "média": float(np.mean(valores[np.isfinite(valores)])),
                    "indivíduo": candidato.tolist(),
                })

            elites = populacao[:elitismo].copy()
            nova = [individuo.copy() for individuo in elites]

            def torneio():
                indices = rng.integers(
                    0,
                    populacao_tamanho,
                    size=3,
                )
                candidatos = populacao[indices]
                candidatos_valores = valores[indices]
                indice = (
                    int(np.argmin(candidatos_valores))
                    if sentido == "min"
                    else int(np.argmax(candidatos_valores))
                )
                return candidatos[indice].copy()

            while len(nova) < populacao_tamanho:
                pai = torneio()
                mae = torneio()
                alpha = rng.random(len(simbolos))
                filho = alpha*pai+(1-alpha)*mae
                mascara = rng.random(len(simbolos)) < mutacao
                ruido = rng.normal(
                    0,
                    0.1*amplitude,
                    size=len(simbolos),
                )
                filho[mascara] += ruido[mascara]
                filho = np.clip(filho, inferior, superior)
                nova.append(filho)

            populacao = np.asarray(nova[:populacao_tamanho])

        return {
            "tipo": "algoritmo genético",
            "dados": {
                "função": sp.sstr(expr),
                "variáveis": [str(v) for v in simbolos],
                "bounds": limites.tolist(),
                "população": populacao_tamanho,
                "gerações": geracoes,
                "semente": semente,
            },
            "pedido": "Procurar uma solução por seleção, cruzamento e mutação",
            "formula": "evolução populacional com aptidão derivada da função objetivo",
            "passos": [
                "Geramos a população inicial uniformemente nos limites.",
                "Selecionamos por torneio.",
                "Cruzamos por combinação convexa.",
                "Aplicamos mutação gaussiana e elitismo.",
                f"Histórico resumido: {historico}.",
            ],
            "resultado": {
                "melhor_indivíduo": melhor_global.tolist(),
                "melhor_valor": melhor_valor,
                "histórico": historico,
            },
            "verificacao": {
                "dentro_dos_limites": bool(
                    np.all(melhor_global >= inferior)
                    and np.all(melhor_global <= superior)
                ),
                "valor_recalculado": float(
                    np.asarray(funcao(melhor_global)).reshape(-1)[0]
                ),
            },
            "observacao": (
                "Meta-heurísticas não garantem ótimo global; a semente e os "
                "parâmetros influenciam o resultado."
            ),
        }


class MotorTeoriaFilasPSF:
    """Modelos M/M/1 e M/M/c em regime estacionário."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        mm1 = re.fullmatch(
            r"fila\s+m\s*m\s*1\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)",
            texto,
        )

        if mm1:
            lambd = float(mm1.group(1))
            mu = float(mm1.group(2))

            if lambd < 0 or mu <= 0:
                return {"erro": "λ deve ser não negativo e μ positivo."}

            rho = lambd/mu

            if rho >= 1:
                return {
                    "tipo": "fila M/M/1",
                    "dados": {"lambda": lambd, "mu": mu},
                    "pedido": "Calcular métricas estacionárias",
                    "formula": "ρ=λ/μ; exige ρ<1",
                    "passos": [
                        f"ρ={lambd}/{mu}={rho}.",
                        "Como ρ≥1, a fila não possui regime estacionário finito.",
                    ],
                    "resultado": {
                        "estável": False,
                        "rho": rho,
                        "L": math.inf,
                        "Lq": math.inf,
                        "W": math.inf,
                        "Wq": math.inf,
                    },
                    "verificacao": "A taxa de chegada não é inferior à capacidade.",
                }

            p0 = 1-rho
            l = rho/(1-rho)
            lq = rho**2/(1-rho)
            w = 1/(mu-lambd)
            wq = rho/(mu-lambd)

            return {
                "tipo": "fila M/M/1",
                "dados": {"lambda": lambd, "mu": mu},
                "pedido": "Calcular utilização, comprimentos e tempos médios",
                "formula": (
                    "ρ=λ/μ; L=ρ/(1−ρ); Lq=ρ²/(1−ρ); "
                    "W=L/λ; Wq=Lq/λ"
                ),
                "passos": [
                    f"ρ={rho}.",
                    f"P0={p0}.",
                    f"L={l}; Lq={lq}.",
                    f"W={w}; Wq={wq}.",
                ],
                "resultado": {
                    "estável": True,
                    "rho": rho,
                    "P0": p0,
                    "L": l,
                    "Lq": lq,
                    "W": w,
                    "Wq": wq,
                },
                "verificacao": {
                    "Little_L=lambda_W": abs(l-lambd*w) < 1e-9,
                    "Little_Lq=lambda_Wq": abs(lq-lambd*wq) < 1e-9,
                },
            }

        mmc = re.fullmatch(
            r"fila\s+m\s*m\s*c\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+(\d+)",
            texto,
        )

        if not mmc:
            return None

        lambd = float(mmc.group(1))
        mu = float(mmc.group(2))
        c = int(mmc.group(3))

        if lambd < 0 or mu <= 0 or c < 1:
            return {"erro": "λ≥0, μ>0 e c≥1 são obrigatórios."}

        a = lambd/mu
        rho = lambd/(c*mu)

        if rho >= 1:
            return {
                "tipo": "fila M/M/c",
                "dados": {"lambda": lambd, "mu": mu, "servidores": c},
                "pedido": "Calcular métricas estacionárias",
                "formula": "ρ=λ/(cμ); exige ρ<1",
                "passos": [
                    f"ρ={rho}≥1.",
                    "O sistema não possui distribuição estacionária finita.",
                ],
                "resultado": {"estável": False, "rho": rho},
                "verificacao": "Capacidade total insuficiente.",
            }

        soma = sum(
            a**n/math.factorial(n)
            for n in range(c)
        )
        termo = a**c/(math.factorial(c)*(1-rho))
        p0 = 1/(soma+termo)
        p_espera = termo*p0
        lq = p_espera*rho/(1-rho)
        wq = lq/lambd if lambd > 0 else 0.0
        w = wq+1/mu
        l = lambd*w
        servidores_ocupados = lambd/mu

        return {
            "tipo": "fila M/M/c",
            "dados": {
                "lambda": lambd,
                "mu_por_servidor": mu,
                "servidores": c,
            },
            "pedido": "Calcular Erlang C e métricas da fila",
            "formula": (
                "P(espera)= [a^c/(c!(1−ρ))]P0; "
                "Lq=P(espera)ρ/(1−ρ)"
            ),
            "passos": [
                f"a=λ/μ={a}.",
                f"ρ=λ/(cμ)={rho}.",
                f"P0={p0}.",
                f"Probabilidade de espera={p_espera}.",
                f"Lq={lq}; Wq={wq}; W={w}; L={l}.",
            ],
            "resultado": {
                "estável": True,
                "rho": rho,
                "P0": p0,
                "probabilidade_espera": p_espera,
                "Lq": lq,
                "Wq": wq,
                "W": w,
                "L": l,
                "servidores_médios_ocupados": servidores_ocupados,
            },
            "verificacao": {
                "Little": abs(l-lambd*w) < 1e-8,
                "ocupação_menor_que_c": servidores_ocupados < c,
            },
        }


class MotorTransporteDesignacaoPSF:
    """Problemas de transporte e designação."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        designacao = re.fullmatch(
            r"designacao\s+(.+)",
            texto,
        )

        if designacao:
            try:
                custos = ParserOtimizacaoRedesPSF.matriz_float(
                    ParserOtimizacaoRedesPSF.literal(
                        designacao.group(1),
                        "matriz de custos",
                    ),
                    "matriz de custos",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            linhas, colunas = linear_sum_assignment(custos)
            pares = [
                {
                    "agente": int(i),
                    "tarefa": int(j),
                    "custo": float(custos[i, j]),
                }
                for i, j in zip(linhas, colunas)
            ]
            total = float(custos[linhas, colunas].sum())

            return {
                "tipo": "problema da designação",
                "dados": {
                    "matriz_custos": custos.tolist(),
                    "agentes": custos.shape[0],
                    "tarefas": custos.shape[1],
                },
                "pedido": "Encontrar a atribuição de custo mínimo",
                "formula": "min Σ c_ij x_ij, uma tarefa por agente e vice-versa",
                "passos": [
                    "Aplicamos o algoritmo húngaro.",
                    f"Pares selecionados: {pares}.",
                    f"Custo total={total}.",
                ],
                "resultado": {
                    "atribuições": pares,
                    "custo_total": total,
                },
                "verificacao": {
                    "agentes_distintos": len(set(linhas.tolist())) == len(linhas),
                    "tarefas_distintas": len(set(colunas.tolist())) == len(colunas),
                },
            }

        transporte = re.fullmatch(
            r"transporte\s+(.+)",
            texto,
        )

        if not transporte:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                transporte.group(1),
                "problema de transporte",
            )
            custos = ParserOtimizacaoRedesPSF.matriz_float(
                dados.get("custos"),
                "custos",
            )
            oferta = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("oferta"),
                "oferta",
            )
            demanda = ParserOtimizacaoRedesPSF.vetor_float(
                dados.get("demanda"),
                "demanda",
            )
        except (ValueError, AttributeError) as erro:
            return {"erro": str(erro)}

        m, n = custos.shape

        if len(oferta) != m or len(demanda) != n:
            return {"erro": "Oferta/demanda incompatíveis com a matriz."}
        if np.any(oferta < 0) or np.any(demanda < 0):
            return {"erro": "Oferta e demanda não podem ser negativas."}

        total_oferta = float(np.sum(oferta))
        total_demanda = float(np.sum(demanda))
        balanceamento = None

        if abs(total_oferta-total_demanda) > 1e-9:
            if total_oferta < total_demanda:
                custos = np.vstack([custos, np.zeros((1, n))])
                oferta = np.append(oferta, total_demanda-total_oferta)
                balanceamento = {
                    "origem_fictícia": total_demanda-total_oferta,
                }
            else:
                custos = np.column_stack([custos, np.zeros((m, 1))])
                demanda = np.append(demanda, total_oferta-total_demanda)
                balanceamento = {
                    "destino_fictício": total_oferta-total_demanda,
                }

        m2, n2 = custos.shape
        c = custos.reshape(-1)
        a_eq = []
        b_eq = []

        for i in range(m2):
            linha = np.zeros(m2*n2)
            linha[i*n2:(i+1)*n2] = 1
            a_eq.append(linha)
            b_eq.append(oferta[i])

        for j in range(n2):
            linha = np.zeros(m2*n2)
            linha[j::n2] = 1
            a_eq.append(linha)
            b_eq.append(demanda[j])

        resultado = scipy_linprog(
            c,
            A_eq=np.asarray(a_eq),
            b_eq=np.asarray(b_eq),
            bounds=[(0, None)]*(m2*n2),
            method="highs",
        )

        if not resultado.success:
            return {"erro": resultado.message}

        plano = resultado.x.reshape(m2, n2)

        return {
            "tipo": "problema do transporte",
            "dados": {
                "custos_balanceados": custos.tolist(),
                "oferta_balanceada": oferta.tolist(),
                "demanda_balanceada": demanda.tolist(),
                "balanceamento": balanceamento,
            },
            "pedido": "Minimizar o custo de atender toda a demanda",
            "formula": (
                "min Σc_ijx_ij; Σ_jx_ij=oferta_i; "
                "Σ_ix_ij=demanda_j; x_ij≥0"
            ),
            "passos": [
                f"Oferta total original={total_oferta}.",
                f"Demanda total original={total_demanda}.",
                f"Balanceamento={balanceamento}.",
                f"Plano ótimo={plano.tolist()}.",
                f"Custo ótimo={resultado.fun}.",
            ],
            "resultado": {
                "plano": plano.tolist(),
                "custo_total": float(resultado.fun),
                "balanceamento": balanceamento,
            },
            "verificacao": {
                "somas_linhas": plano.sum(axis=1).tolist(),
                "oferta": oferta.tolist(),
                "somas_colunas": plano.sum(axis=0).tolist(),
                "demanda": demanda.tolist(),
            },
        }


class MotorFluxoRedesPSF:
    """Fluxo máximo, corte mínimo e decomposição do fluxo."""

    def calcular(self, entrada):
        payload = extrair_payload_original(entrada, r"fluxo\s+maximo\s+")

        if payload is None:
            return None

        padrao = re.fullmatch(r"(.+?)\s*;\s*(.+?)\s*;\s*(.+)", payload)

        if not padrao:
            return None

        try:
            arestas = ParserOtimizacaoRedesPSF.literal(
                padrao.group(1),
                "arestas",
            )
            origem = ParserOtimizacaoRedesPSF.literal(
                padrao.group(2),
                "origem",
            )
            destino = ParserOtimizacaoRedesPSF.literal(
                padrao.group(3),
                "destino",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        grafo = nx.DiGraph()

        for aresta in arestas:
            if not isinstance(aresta, (list, tuple)) or len(aresta) != 3:
                return {"erro": "Cada aresta deve ser (u,v,capacidade)."}

            u, v, capacidade = aresta
            capacidade = float(capacidade)

            if capacidade < 0:
                return {"erro": "Capacidade não pode ser negativa."}

            if grafo.has_edge(u, v):
                grafo[u][v]["capacity"] += capacidade
            else:
                grafo.add_edge(u, v, capacity=capacidade)

        if origem not in grafo or destino not in grafo:
            return {"erro": "Origem e destino devem pertencer à rede."}

        valor, fluxo = nx.maximum_flow(
            grafo,
            origem,
            destino,
            capacity="capacity",
        )
        corte_valor, particao = nx.minimum_cut(
            grafo,
            origem,
            destino,
            capacity="capacity",
        )
        s, t = particao
        arestas_corte = [
            {
                "u": u,
                "v": v,
                "capacidade": grafo[u][v]["capacity"],
            }
            for u in s
            for v in grafo.successors(u)
            if v in t
        ]
        conservacao = {}

        for no in grafo.nodes:
            entrada_no = sum(
                fluxo[u].get(no, 0)
                for u in grafo.predecessors(no)
            )
            saida_no = sum(
                fluxo[no].values()
            )
            conservacao[no] = {
                "entrada": entrada_no,
                "saída": saida_no,
                "diferença": entrada_no-saida_no,
            }

        return {
            "tipo": "fluxo máximo e corte mínimo",
            "dados": {
                "arestas": arestas,
                "origem": origem,
                "destino": destino,
            },
            "pedido": "Calcular o fluxo máximo e um corte mínimo",
            "formula": "max fluxo = capacidade do corte mínimo",
            "passos": [
                "Construímos a rede residual.",
                "Procuramos caminhos aumentantes até não existirem.",
                f"Fluxo por aresta: {fluxo}.",
                f"Partição do corte: S={sorted(s, key=str)}, T={sorted(t, key=str)}.",
                f"Arestas do corte: {arestas_corte}.",
            ],
            "resultado": {
                "fluxo_máximo": float(valor),
                "fluxos": fluxo,
                "corte_mínimo": float(corte_valor),
                "partição": {
                    "S": sorted(s, key=str),
                    "T": sorted(t, key=str),
                },
                "arestas_corte": arestas_corte,
            },
            "verificacao": {
                "max_flow_min_cut": abs(valor-corte_valor) < 1e-9,
                "conservação": conservacao,
            },
        }


class MotorMarkovDecisaoPSF:
    """Cadeias de Markov e processos de decisão por iteração de valores."""

    def calcular(self, entrada):
        payload_cadeia = extrair_payload_original(entrada, r"cadeia\s+markov\s+")

        if payload_cadeia is not None:
            try:
                dados = ParserOtimizacaoRedesPSF.literal(
                    payload_cadeia,
                    "cadeia de Markov",
                )
                p = ParserOtimizacaoRedesPSF.matriz_float(
                    dados.get("P"),
                    "P",
                )
                inicial = ParserOtimizacaoRedesPSF.vetor_float(
                    dados.get("inicial"),
                    "distribuição inicial",
                )
            except (ValueError, AttributeError) as erro:
                return {"erro": str(erro)}

            if p.shape[0] != p.shape[1] or len(inicial) != p.shape[0]:
                return {"erro": "P deve ser quadrada e compatível com a distribuição."}
            if np.any(p < 0) or not np.allclose(p.sum(axis=1), 1, atol=1e-9):
                return {"erro": "Cada linha de P deve ser uma distribuição."}
            if np.any(inicial < 0) or not np.isclose(inicial.sum(), 1):
                return {"erro": "A distribuição inicial deve somar 1."}

            passos_n = int(dados.get("passos", 1))

            if passos_n < 0 or passos_n > 1_000_000:
                return {"erro": "passos deve estar entre 0 e 1000000."}

            p_n = np.linalg.matrix_power(p, passos_n)
            distribuicao_n = inicial@p_n
            valores, vetores = np.linalg.eig(p.T)
            candidatos = np.where(np.abs(valores-1) < 1e-8)[0]
            estacionarias = []

            for indice in candidatos:
                vetor = np.real(vetores[:, indice])

                if np.sum(vetor) < 0:
                    vetor = -vetor

                vetor = np.maximum(vetor, 0)

                if vetor.sum() > 0:
                    vetor = vetor/vetor.sum()
                    estacionarias.append(vetor.tolist())

            comunicacao = nx.DiGraph()
            comunicacao.add_nodes_from(range(len(p)))

            for i in range(len(p)):
                for j in range(len(p)):
                    if p[i, j] > 0:
                        comunicacao.add_edge(i, j)

            classes = [
                sorted(componente)
                for componente in nx.strongly_connected_components(comunicacao)
            ]
            irreducivel = len(classes) == 1

            return {
                "tipo": "cadeia de Markov",
                "dados": {
                    "P": p.tolist(),
                    "inicial": inicial.tolist(),
                    "passos": passos_n,
                },
                "pedido": "Calcular distribuição futura e distribuições estacionárias",
                "formula": "π_n=π_0P^n; π=πP",
                "passos": [
                    f"P^{passos_n}={p_n.tolist()}.",
                    f"π_{passos_n}={distribuicao_n.tolist()}.",
                    f"Autovalores={valores.tolist()}.",
                    f"Classes comunicantes={classes}.",
                ],
                "resultado": {
                    "distribuição_n": distribuicao_n.tolist(),
                    "P_n": p_n.tolist(),
                    "estacionárias": estacionarias,
                    "irreducível": irreducivel,
                    "classes_comunicantes": classes,
                },
                "verificacao": {
                    "soma_distribuição_n": float(distribuicao_n.sum()),
                    "estacionárias_verificadas": [
                        bool(np.allclose(np.asarray(pi)@p, pi, atol=1e-8))
                        for pi in estacionarias
                    ],
                },
            }

        payload_mdp = extrair_payload_original(entrada, r"mdp\s+valor\s+")

        if payload_mdp is None:
            return None

        try:
            dados = ParserOtimizacaoRedesPSF.literal(
                payload_mdp,
                "MDP",
            )
            transicoes = np.asarray(
                dados.get("P"),
                dtype=float,
            )
            recompensas = np.asarray(
                dados.get("R"),
                dtype=float,
            )
        except (ValueError, TypeError, AttributeError) as erro:
            return {"erro": str(erro)}

        if transicoes.ndim != 3:
            return {"erro": "P deve ter forma ações×estados×estados."}

        acoes, estados, estados2 = transicoes.shape

        if estados != estados2:
            return {"erro": "Cada matriz de transição deve ser quadrada."}
        if recompensas.shape == (estados, acoes):
            recompensas = recompensas.T
        if recompensas.shape != (acoes, estados):
            return {"erro": "R deve ter forma ações×estados ou estados×ações."}
        if np.any(transicoes < 0) or not np.allclose(
            transicoes.sum(axis=2),
            1,
            atol=1e-9,
        ):
            return {"erro": "Cada linha de transição deve somar 1."}

        gamma = float(dados.get("gamma", 0.95))
        tolerancia = float(dados.get("tolerancia", 1e-10))
        max_iter = int(dados.get("max_iter", 10000))

        if not (0 <= gamma < 1):
            return {"erro": "gamma deve estar em [0,1)."}
        if tolerancia <= 0 or max_iter < 1:
            return {"erro": "Tolerância e máximo devem ser positivos."}

        valor = np.zeros(estados)
        historico = []
        convergiu = False

        for iteracao in range(1, max_iter+1):
            q = recompensas+gamma*np.einsum(
                "ask,k->as",
                transicoes,
                valor,
            )
            novo = np.max(q, axis=0)
            erro = float(np.max(np.abs(novo-valor)))
            valor = novo

            if iteracao <= 100 or iteracao == max_iter:
                historico.append({
                    "iteração": iteracao,
                    "erro": erro,
                    "V": valor.tolist(),
                })

            if erro <= tolerancia:
                convergiu = True
                break

        q_final = recompensas+gamma*np.einsum(
            "ask,k->as",
            transicoes,
            valor,
        )
        politica = np.argmax(q_final, axis=0)

        return {
            "tipo": "processo de decisão de Markov",
            "dados": {
                "estados": estados,
                "ações": acoes,
                "gamma": gamma,
                "tolerância": tolerancia,
            },
            "pedido": "Calcular função valor ótima e política gulosa",
            "formula": "V*(s)=max_a[R(a,s)+γΣP(a,s,s')V*(s')]",
            "passos": [
                "Inicializamos V=0.",
                "Aplicamos repetidamente o operador de Bellman ótimo.",
                f"Histórico: {historico}.",
                f"Q final={q_final.tolist()}.",
            ],
            "resultado": {
                "V_ótimo": valor.tolist(),
                "Q_ótimo": q_final.tolist(),
                "política": politica.tolist(),
                "iterações": iteracao,
                "convergiu": convergiu,
            },
            "verificacao": {
                "resíduo_Bellman": float(
                    np.max(
                        np.abs(
                            valor-np.max(
                                recompensas+gamma*np.einsum(
                                    "ask,k->as",
                                    transicoes,
                                    valor,
                                ),
                                axis=0,
                            )
                        )
                    )
                ),
            },
            "justificacao": (
                "A iteração atingiu o máximo antes de o resíduo ficar abaixo "
                "da tolerância. A política apresentada é aproximada, mas a "
                "convergência solicitada não foi confirmada."
                if not convergiu
                else None
            ),
        }



class ParserFourierSinaisPSF:
    """Expressões e amostras para análise harmônica e sinais."""

    x = sp.Symbol("x", real=True)
    t = sp.Symbol("t", real=True)
    xi = sp.Symbol("xi", real=True)

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @staticmethod
    def _texto_seguro(texto):
        expressao = str(texto).strip().replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            raise ValueError("Expressão contém símbolos não permitidos.")

        return expressao

    @classmethod
    def expressao_x(cls, texto):
        expressao = cls._texto_seguro(texto)
        locais = {
            "x": cls.x,
            "t": cls.x,
            "sin": sp.sin,
            "sen": sp.sin,
            "cos": sp.cos,
            "tan": sp.tan,
            "exp": sp.exp,
            "log": sp.log,
            "ln": sp.log,
            "sqrt": sp.sqrt,
            "abs": sp.Abs,
            "heaviside": sp.Heaviside,
            "pi": sp.pi,
            "e": sp.E,
        }

        try:
            expr = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            raise ValueError("Função inválida.") from erro

        if expr.free_symbols - {cls.x}:
            raise ValueError("A função só pode depender de x.")

        return expr

    @classmethod
    def amostras(cls, texto, complexo=False):
        dados = cls.literal(texto, "amostras")

        if not isinstance(dados, (list, tuple)) or not dados:
            raise ValueError("Forneça uma lista não vazia.")

        try:
            vetor = np.asarray(
                [complex(v) for v in dados]
                if complexo
                else [float(v) for v in dados],
                dtype=complex if complexo else float,
            )
        except (TypeError, ValueError) as erro:
            raise ValueError("Amostras inválidas.") from erro

        if vetor.ndim != 1 or not np.isfinite(vetor).all():
            raise ValueError("As amostras devem ser finitas e unidimensionais.")

        return vetor

    @classmethod
    def matriz(cls, texto):
        dados = cls.literal(texto, "matriz")

        try:
            matriz = np.asarray(dados, dtype=float)
        except (TypeError, ValueError) as erro:
            raise ValueError("A matriz deve ser numérica.") from erro

        if matriz.ndim != 2 or min(matriz.shape) == 0:
            raise ValueError("A matriz deve ser bidimensional e não vazia.")
        if not np.isfinite(matriz).all():
            raise ValueError("A matriz contém valor não finito.")

        return matriz


class MotorSeriesFourierPSF:
    """Coeficientes de Fourier reais e convergência por somas parciais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"serie\s+fourier\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)\s*;\s*"
            r"(\d+)(?:\s*;\s*([+-]?[0-9.eE]+))?",
            texto,
        )

        if not padrao:
            return None

        try:
            expr = ParserFourierSinaisPSF.expressao_x(padrao.group(1))
        except ValueError as erro:
            return {"erro": str(erro)}

        a = float(padrao.group(2))
        b = float(padrao.group(3))
        n_max = int(padrao.group(4))
        ponto = (
            float(padrao.group(5))
            if padrao.group(5) is not None
            else None
        )

        if not a < b or n_max < 0 or n_max > 500:
            return {"erro": "Exige-se a<b e 0≤N≤500."}

        x = ParserFourierSinaisPSF.x
        comprimento = b-a
        omega = 2*sp.pi/comprimento

        try:
            a0 = sp.simplify(
                2/comprimento*sp.integrate(expr, (x, a, b))
            )
        except Exception:
            a0 = None

        coeficientes = []
        soma = a0/2 if a0 is not None else sp.Integer(0)
        f_num = sp.lambdify(x, expr, modules=["numpy"])

        for n in range(1, n_max+1):
            coseno = sp.cos(n*omega*(x-a))
            seno = sp.sin(n*omega*(x-a))

            try:
                an = sp.simplify(
                    2/comprimento*sp.integrate(
                        expr*coseno,
                        (x, a, b),
                    )
                )
                bn = sp.simplify(
                    2/comprimento*sp.integrate(
                        expr*seno,
                        (x, a, b),
                    )
                )
            except Exception as erro:
                return {
                    "erro": (
                        f"Não foi possível integrar o coeficiente n={n}: {erro}"
                    )
                }

            coeficientes.append({
                "n": n,
                "a_n": sp.sstr(an),
                "b_n": sp.sstr(bn),
            })
            soma += an*coseno+bn*seno

        soma = sp.simplify(soma)
        avaliacao = None

        if ponto is not None:
            valor_parcial = sp.N(soma.subs(x, ponto), 20)

            try:
                valor_funcao = float(f_num(ponto))
            except Exception:
                valor_funcao = None

            epsilon = max(1e-6, comprimento*1e-7)

            try:
                esquerda = float(f_num(ponto-epsilon))
                direita = float(f_num(ponto+epsilon))
                alvo_dirichlet = (esquerda+direita)/2
            except Exception:
                esquerda = direita = alvo_dirichlet = None

            avaliacao = {
                "ponto": ponto,
                "soma_parcial": sp.sstr(valor_parcial),
                "f_ponto": valor_funcao,
                "limite_esquerdo_numérico": esquerda,
                "limite_direito_numérico": direita,
                "alvo_Dirichlet": alvo_dirichlet,
            }

        grade = np.linspace(a, b, 1001, endpoint=False)
        soma_num = sp.lambdify(x, soma, modules=["numpy"])
        valores_soma = np.asarray(soma_num(grade), dtype=float)

        if valores_soma.shape == ():
            valores_soma = np.full_like(grade, float(valores_soma))

        valores_f = np.asarray(f_num(grade), dtype=float)

        if valores_f.shape == ():
            valores_f = np.full_like(grade, float(valores_f))

        erro_l2 = float(
            np.sqrt(np.mean((valores_soma-valores_f)**2))
        )
        erro_uniforme_grade = float(
            np.max(np.abs(valores_soma-valores_f))
        )

        return {
            "tipo": "série de Fourier",
            "dados": {
                "função": sp.sstr(expr),
                "intervalo": [a, b],
                "harmónicos": n_max,
            },
            "pedido": "Calcular coeficientes e soma parcial",
            "formula": (
                "S_N=a0/2+Σ_{n=1}^N[a_n cos(nω(x−a))+"
                "b_n sin(nω(x−a))]"
            ),
            "passos": [
                f"Comprimento L={comprimento}; ω=2π/L={sp.sstr(omega)}.",
                f"a0={sp.sstr(a0)}.",
                f"Coeficientes: {coeficientes}.",
                f"Soma parcial: {sp.sstr(soma)}.",
                f"Avaliação pontual: {avaliacao}.",
            ],
            "resultado": {
                "a0": sp.sstr(a0),
                "coeficientes": coeficientes,
                "soma_parcial": sp.sstr(soma),
                "avaliação": avaliacao,
                "erro_RMS_grade": erro_l2,
                "erro_uniforme_na_grade": erro_uniforme_grade,
                "convergência_uniforme_geral": "não determinado",
            },
            "verificacao": (
                "Os erros foram medidos numa grade finita de 1001 pontos."
            ),
            "justificacao": (
                "Uma grade finita e uma soma parcial não provam convergência "
                "uniforme da série completa. A convergência uniforme depende "
                "da regularidade global e do comportamento nos pontos de "
                "descontinuidade, exigindo uma demonstração analítica."
            ),
        }


class MotorTransformadaFourierRPSF:
    """Transformada contínua simbólica e FFT de amostras unidimensionais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        simbolica = re.fullmatch(
            r"fourier\s+r\s+simbolica\s+(.+)",
            texto,
        )

        if simbolica:
            try:
                expr = ParserFourierSinaisPSF.expressao_x(
                    simbolica.group(1)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            x = ParserFourierSinaisPSF.x
            xi = ParserFourierSinaisPSF.xi

            try:
                transformada = sp.fourier_transform(
                    expr,
                    x,
                    xi,
                    noconds=False,
                )
            except Exception as erro:
                return {"erro": f"Transformada simbólica falhou: {erro}"}

            if isinstance(transformada, tuple):
                valor, condicoes = transformada
            else:
                valor = transformada
                condicoes = True

            return {
                "tipo": "transformada de Fourier contínua em R",
                "dados": {"f(x)": sp.sstr(expr)},
                "pedido": "Calcular a transformada simbólica",
                "formula": "F(ξ)=∫_{−∞}^{∞}f(x)e^{−2πixξ}dx",
                "passos": [
                    "Aplicamos a convenção simbólica de frequência de SymPy.",
                    f"Transformada: {sp.sstr(valor)}.",
                    f"Condições: {sp.sstr(condicoes)}.",
                ],
                "resultado": {
                    "transformada": sp.sstr(valor),
                    "condições": sp.sstr(condicoes),
                },
                "verificacao": (
                    "A expressão e as condições são devolvidas pelo motor simbólico."
                ),
            }

        fft = re.fullmatch(
            r"fourier\s+r\s+fft\s+(.+?)\s*;\s*([0-9.eE+-]+)",
            texto,
        )

        if not fft:
            return None

        try:
            amostras = ParserFourierSinaisPSF.amostras(
                fft.group(1),
                complexo=True,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        dt = float(fft.group(2))

        if dt <= 0:
            return {"erro": "O passo temporal deve ser positivo."}

        espectro = np.fft.fft(amostras)
        frequencias = np.fft.fftfreq(len(amostras), d=dt)
        reconstruida = np.fft.ifft(espectro)
        energia_tempo = float(np.sum(np.abs(amostras)**2))
        energia_frequencia = float(
            np.sum(np.abs(espectro)**2)/len(amostras)
        )
        ordem = np.argsort(np.abs(espectro))[::-1]
        picos = [
            {
                "frequência": float(frequencias[i]),
                "amplitude": float(abs(espectro[i])/len(amostras)),
                "coeficiente": complex(espectro[i]),
            }
            for i in ordem[:min(20, len(ordem))]
        ]

        return {
            "tipo": "transformada discreta de Fourier em R",
            "dados": {
                "amostras": amostras.tolist(),
                "dt": dt,
                "quantidade": len(amostras),
            },
            "pedido": "Calcular FFT, frequências e reconstrução",
            "formula": "X_k=Σ_{n=0}^{N−1}x_n e^{−2πikn/N}",
            "passos": [
                f"Frequências discretas: {frequencias.tolist()}.",
                f"Coeficientes FFT: {espectro.tolist()}.",
                f"Picos principais: {picos}.",
            ],
            "resultado": {
                "frequências": frequencias.tolist(),
                "espectro": espectro.tolist(),
                "picos": picos,
                "reconstrução": reconstruida.tolist(),
            },
            "verificacao": {
                "erro_reconstrução": float(
                    np.max(np.abs(reconstruida-amostras))
                ),
                "Parseval_tempo": energia_tempo,
                "Parseval_frequência": energia_frequencia,
            },
        }


class MotorTransformadaFourierRnPSF:
    """FFT n-dimensional em tensores fornecidos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"fourier\s+rn\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserFourierSinaisPSF.literal(
                padrao.group(1),
                "tensor",
            )
            tensor = np.asarray(dados, dtype=complex)
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if tensor.ndim < 1 or tensor.size == 0:
            return {"erro": "O tensor deve possuir dimensão positiva."}
        if tensor.size > 5_000_000:
            return {"erro": "O tensor está limitado a 5 milhões de elementos."}
        if not np.isfinite(tensor).all():
            return {"erro": "O tensor contém valor não finito."}

        espectro = np.fft.fftn(tensor)
        reconstruido = np.fft.ifftn(espectro)
        energia_tempo = float(np.sum(np.abs(tensor)**2))
        energia_freq = float(
            np.sum(np.abs(espectro)**2)/tensor.size
        )
        indice_max = np.unravel_index(
            int(np.argmax(np.abs(espectro))),
            espectro.shape,
        )

        return {
            "tipo": "transformada de Fourier em R^n discretizada",
            "dados": {
                "forma": list(tensor.shape),
                "dimensão": tensor.ndim,
            },
            "pedido": "Calcular a FFT multidimensional",
            "formula": (
                "X_k=Σ_n x_n exp(−2πi Σ_j k_jn_j/N_j)"
            ),
            "passos": [
                f"Aplicamos FFT nos {tensor.ndim} eixos.",
                f"Forma do espectro: {list(espectro.shape)}.",
                f"Índice da maior magnitude: {indice_max}.",
            ],
            "resultado": {
                "espectro": espectro.tolist(),
                "índice_pico": list(indice_max),
                "magnitude_pico": float(abs(espectro[indice_max])),
                "reconstrução": reconstruido.tolist(),
            },
            "verificacao": {
                "erro_máximo_reconstrução": float(
                    np.max(np.abs(reconstruido-tensor))
                ),
                "energia_tempo": energia_tempo,
                "energia_frequência": energia_freq,
            },
        }


class MotorDistribuicoesGeneralizadasPSF:
    """Ação de delta, derivadas da delta e derivada de Heaviside."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        delta = re.fullmatch(
            r"distribuicao\s+delta\s+"
            r"([+-]?[0-9.eE]+)\s*;\s*(.+?)(?:\s*;\s*(\d+))?",
            texto,
        )

        if delta:
            a = float(delta.group(1))
            ordem = int(delta.group(3) or 0)

            try:
                phi = ParserFourierSinaisPSF.expressao_x(
                    delta.group(2)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            x = ParserFourierSinaisPSF.x
            derivada = sp.diff(phi, x, ordem)
            valor_derivada = sp.simplify(derivada.subs(x, a))
            acao = sp.simplify((-1)**ordem*valor_derivada)

            return {
                "tipo": "distribuição delta de Dirac",
                "dados": {
                    "ponto_a": a,
                    "função_teste": sp.sstr(phi),
                    "ordem_derivada_delta": ordem,
                },
                "pedido": "Calcular a ação da distribuição na função teste",
                "formula": "<δ_a^(n),φ>=(-1)^n φ^(n)(a)",
                "passos": [
                    f"φ^{ordem}(x)={sp.sstr(derivada)}.",
                    f"φ^{ordem}({a})={sp.sstr(valor_derivada)}.",
                    f"Multiplicamos por (-1)^{ordem}.",
                ],
                "resultado": {
                    "ação": sp.sstr(acao),
                },
                "verificacao": (
                    "A ação depende apenas do jato de ordem n no ponto a."
                ),
            }

        heaviside = re.fullmatch(
            r"distribuicao\s+heaviside\s+derivada\s*;\s*(.+)",
            texto,
        )

        if not heaviside:
            return None

        try:
            phi = ParserFourierSinaisPSF.expressao_x(
                heaviside.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        valor = sp.simplify(
            phi.subs(ParserFourierSinaisPSF.x, 0)
        )

        return {
            "tipo": "derivada distribucional de Heaviside",
            "dados": {"função_teste": sp.sstr(phi)},
            "pedido": "Calcular <H',φ>",
            "formula": "<H',φ>=−<H,φ'>=φ(0)=<δ,φ>",
            "passos": [
                "Integramos por partes no sentido das distribuições.",
                "O termo no infinito desaparece para função teste.",
                f"φ(0)={sp.sstr(valor)}.",
            ],
            "resultado": {
                "ação_H_linha": sp.sstr(valor),
                "ação_delta": sp.sstr(valor),
                "identidade": "H'=δ",
            },
            "verificacao": "As duas ações coincidem na função teste fornecida.",
        }


class MotorEspacosSobolevPSF:
    """Normas H^k por derivação simbólica e quadratura."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"sobolev\s+h\s+(\d+)\s+(.+?)\s*;\s*"
            r"([+-]?[0-9.eE]+)\s*;\s*([+-]?[0-9.eE]+)",
            texto,
        )

        if not padrao:
            return None

        k = int(padrao.group(1))

        try:
            expr = ParserFourierSinaisPSF.expressao_x(
                padrao.group(2)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        a = float(padrao.group(3))
        b = float(padrao.group(4))

        if k < 0 or k > 20 or not a < b:
            return {"erro": "Exige-se 0≤k≤20 e a<b."}

        x = ParserFourierSinaisPSF.x
        termos = []
        soma_quadrados = 0.0

        for ordem in range(k+1):
            derivada = sp.diff(expr, x, ordem)
            funcao = sp.lambdify(x, derivada, modules=["numpy"])

            try:
                integral, erro = scipy_quad(
                    lambda valor: abs(complex(funcao(valor)))**2,
                    a,
                    b,
                    limit=500,
                )
            except Exception as erro_execucao:
                return {
                    "erro": (
                        f"A derivada de ordem {ordem} não pôde ser integrada: "
                        f"{erro_execucao}"
                    )
                }

            soma_quadrados += integral
            termos.append({
                "ordem": ordem,
                "derivada": sp.sstr(derivada),
                "norma_L2_quadrado": integral,
                "erro_quadratura": erro,
            })

        norma = math.sqrt(max(0.0, soma_quadrados))

        return {
            "tipo": "norma de Sobolev H^k",
            "dados": {
                "função": sp.sstr(expr),
                "k": k,
                "intervalo": [a, b],
            },
            "pedido": "Calcular a soma das normas L² das derivadas fracas clássicas",
            "formula": "||f||_{H^k}²=Σ_{j=0}^k ||f^(j)||_{L²}²",
            "passos": [
                f"Termos calculados: {termos}.",
                f"Soma dos quadrados={soma_quadrados}.",
                f"Norma H^{k}={norma}.",
            ],
            "resultado": {
                "norma_Hk": norma,
                "norma_quadrado": soma_quadrados,
                "termos": termos,
            },
            "verificacao": {
                "norma_não_negativa": norma >= 0,
            },
            "observacao": (
                "Para a função simbólica regular fornecida, derivadas clássicas "
                "representam as derivadas fracas no intervalo."
            ),
        }


class MotorOperadoresPseudodiferenciaisPSF:
    """Multiplicadores de Fourier periódicos como operadores pseudodiferenciais."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"pseudodiferencial\s+(.+?)\s*;\s*(.+?)\s*;\s*"
            r"([0-9.eE+-]+)",
            texto,
        )

        if not padrao:
            return None

        try:
            amostras = ParserFourierSinaisPSF.amostras(
                padrao.group(1),
                complexo=True,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        simbolo_texto = padrao.group(2)
        dt = float(padrao.group(3))

        if dt <= 0:
            return {"erro": "dt deve ser positivo."}

        xi = sp.Symbol("xi", real=True)
        expressao = simbolo_texto.replace("^", "**")

        if "__" in expressao or not re.fullmatch(
            r"[0-9A-Za-z_+\-*/().,\s*]+",
            expressao,
        ):
            return {"erro": "Símbolo contém caracteres não permitidos."}

        locais = {
            "xi": xi,
            "abs": sp.Abs,
            "sqrt": sp.sqrt,
            "exp": sp.exp,
            "log": sp.log,
            "pi": sp.pi,
            "e": sp.E,
            "i": sp.I,
        }

        try:
            simbolo = sp.sympify(expressao, locals=locais)
        except Exception as erro:
            return {"erro": f"Símbolo inválido: {erro}"}

        if simbolo.free_symbols - {xi}:
            return {"erro": "O símbolo só pode depender de xi."}

        frequencias = 2*math.pi*np.fft.fftfreq(
            len(amostras),
            d=dt,
        )
        simbolo_num = sp.lambdify(
            xi,
            simbolo,
            modules=["numpy"],
        )
        multiplicadores = np.asarray(
            simbolo_num(frequencias),
            dtype=complex,
        )

        if multiplicadores.shape == ():
            multiplicadores = np.full(
                len(amostras),
                complex(multiplicadores),
            )
        if not np.isfinite(multiplicadores).all():
            return {"erro": "O símbolo gerou valor não finito."}

        espectro = np.fft.fft(amostras)
        espectro_saida = multiplicadores*espectro
        saida = np.fft.ifft(espectro_saida)

        return {
            "tipo": "operador pseudodiferencial periódico",
            "dados": {
                "símbolo": sp.sstr(simbolo),
                "amostras": len(amostras),
                "dt": dt,
            },
            "pedido": "Aplicar o multiplicador a(ξ) no domínio de Fourier",
            "formula": "Op(a)u=F^{-1}[a(ξ)F[u](ξ)]",
            "passos": [
                f"Frequências angulares: {frequencias.tolist()}.",
                f"Multiplicadores: {multiplicadores.tolist()}.",
                f"Espectro de entrada: {espectro.tolist()}.",
                f"Espectro de saída: {espectro_saida.tolist()}.",
            ],
            "resultado": {
                "saída": saida.tolist(),
                "espectro_saída": espectro_saida.tolist(),
            },
            "verificacao": (
                "A saída foi reconstruída pela transformada inversa."
            ),
        }


class FerramentasHaarPSF:
    """Transformada Haar ortonormal em uma e duas dimensões."""

    @staticmethod
    def dwt1(vetor, niveis):
        atual = np.asarray(vetor, dtype=float).copy()
        coeficientes = []
        tamanhos = []

        for _ in range(niveis):
            n = len(atual)

            if n % 2:
                atual = np.append(atual, atual[-1])
                n += 1

            aproximacao = (
                atual[0:n:2]+atual[1:n:2]
            )/math.sqrt(2)
            detalhe = (
                atual[0:n:2]-atual[1:n:2]
            )/math.sqrt(2)
            coeficientes.append(detalhe)
            tamanhos.append(n)
            atual = aproximacao

        return atual, coeficientes, tamanhos

    @staticmethod
    def idwt1(aproximacao, detalhes, tamanhos):
        atual = np.asarray(aproximacao, dtype=float)

        for detalhe, tamanho in zip(
            reversed(detalhes),
            reversed(tamanhos),
        ):
            detalhe = np.asarray(detalhe, dtype=float)
            reconstruido = np.empty(2*len(atual))
            reconstruido[0::2] = (
                atual+detalhe
            )/math.sqrt(2)
            reconstruido[1::2] = (
                atual-detalhe
            )/math.sqrt(2)
            atual = reconstruido[:tamanho]

        return atual

    @staticmethod
    def haar2(matriz, niveis):
        atual = np.asarray(matriz, dtype=float).copy()
        blocos = []
        formas = []

        for _ in range(niveis):
            linhas, colunas = atual.shape

            if linhas % 2:
                atual = np.vstack([atual, atual[-1:]])
                linhas += 1
            if colunas % 2:
                atual = np.column_stack([atual, atual[:, -1:]])
                colunas += 1

            baixo_linhas = (
                atual[0::2]+atual[1::2]
            )/math.sqrt(2)
            alto_linhas = (
                atual[0::2]-atual[1::2]
            )/math.sqrt(2)
            ll = (
                baixo_linhas[:, 0::2]+baixo_linhas[:, 1::2]
            )/math.sqrt(2)
            lh = (
                baixo_linhas[:, 0::2]-baixo_linhas[:, 1::2]
            )/math.sqrt(2)
            hl = (
                alto_linhas[:, 0::2]+alto_linhas[:, 1::2]
            )/math.sqrt(2)
            hh = (
                alto_linhas[:, 0::2]-alto_linhas[:, 1::2]
            )/math.sqrt(2)
            blocos.append((lh, hl, hh))
            formas.append((linhas, colunas))
            atual = ll

        return atual, blocos, formas

    @staticmethod
    def ihaar2(ll, blocos, formas):
        atual = np.asarray(ll, dtype=float)

        for (lh, hl, hh), forma in zip(
            reversed(blocos),
            reversed(formas),
        ):
            baixo = np.empty(
                (atual.shape[0], atual.shape[1]*2)
            )
            alto = np.empty_like(baixo)
            baixo[:, 0::2] = (
                atual+lh
            )/math.sqrt(2)
            baixo[:, 1::2] = (
                atual-lh
            )/math.sqrt(2)
            alto[:, 0::2] = (
                hl+hh
            )/math.sqrt(2)
            alto[:, 1::2] = (
                hl-hh
            )/math.sqrt(2)
            reconstruido = np.empty(
                (baixo.shape[0]*2, baixo.shape[1])
            )
            reconstruido[0::2] = (
                baixo+alto
            )/math.sqrt(2)
            reconstruido[1::2] = (
                baixo-alto
            )/math.sqrt(2)
            atual = reconstruido[:forma[0], :forma[1]]

        return atual


class MotorWaveletsPSF:
    """Transformada wavelet Haar e reconstrução."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"wavelet\s+haar\s+(.+?)\s*;\s*(\d+)",
            texto,
        )

        if not padrao:
            return None

        try:
            vetor = ParserFourierSinaisPSF.amostras(
                padrao.group(1),
                complexo=False,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        niveis = int(padrao.group(2))
        max_niveis = int(math.ceil(math.log2(len(vetor)))) if len(vetor) > 1 else 0

        if niveis < 0 or niveis > max_niveis:
            return {
                "erro": (
                    f"Os níveis devem estar entre 0 e {max_niveis}."
                )
            }

        aproximacao, detalhes, tamanhos = FerramentasHaarPSF.dwt1(
            vetor,
            niveis,
        )
        reconstruida = FerramentasHaarPSF.idwt1(
            aproximacao,
            detalhes,
            tamanhos,
        )[:len(vetor)]
        energia_original = float(np.sum(vetor**2))
        energia_coef = float(
            np.sum(aproximacao**2)
            + sum(np.sum(d**2) for d in detalhes)
        )

        return {
            "tipo": "análise wavelet Haar",
            "dados": {
                "sinal": vetor.tolist(),
                "níveis": niveis,
            },
            "pedido": "Decompor em aproximações e detalhes e reconstruir",
            "formula": "a=(x_{2k}+x_{2k+1})/√2; d=(x_{2k}−x_{2k+1})/√2",
            "passos": [
                f"Aproximação final: {aproximacao.tolist()}.",
                f"Detalhes por nível: {[d.tolist() for d in detalhes]}.",
                f"Tamanhos internos: {tamanhos}.",
            ],
            "resultado": {
                "aproximação": aproximacao.tolist(),
                "detalhes": [d.tolist() for d in detalhes],
                "reconstrução": reconstruida.tolist(),
            },
            "verificacao": {
                "erro_máximo": float(
                    np.max(np.abs(reconstruida-vetor))
                ),
                "energia_original": energia_original,
                "energia_coeficientes": energia_coef,
            },
        }


class MotorTempoFrequenciaPSF:
    """STFT/Gabor e distribuição discreta de Wigner–Ville."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        gabor = re.fullmatch(
            r"gabor\s+stft\s+(.+?)\s*;\s*([0-9.eE+-]+)\s*;\s*"
            r"(\d+)\s*;\s*(\d+)",
            texto,
        )

        if gabor:
            try:
                sinal = ParserFourierSinaisPSF.amostras(
                    gabor.group(1),
                    complexo=False,
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            fs = float(gabor.group(2))
            janela = int(gabor.group(3))
            sobreposicao = int(gabor.group(4))

            if fs <= 0 or janela < 2 or janela > len(sinal):
                return {"erro": "fs>0 e 2≤janela≤comprimento são obrigatórios."}
            if sobreposicao < 0 or sobreposicao >= janela:
                return {"erro": "sobreposição deve estar entre 0 e janela−1."}

            frequencias, tempos, z = scipy_stft(
                sinal,
                fs=fs,
                window="hann",
                nperseg=janela,
                noverlap=sobreposicao,
                boundary=None,
                padded=False,
            )
            magnitude = np.abs(z)
            indices = np.argmax(magnitude, axis=0)
            frequencia_dominante = (
                frequencias[indices].tolist()
                if magnitude.shape[1]
                else []
            )

            return {
                "tipo": "análise Gabor/STFT",
                "dados": {
                    "amostras": len(sinal),
                    "fs": fs,
                    "janela": janela,
                    "sobreposição": sobreposicao,
                },
                "pedido": "Calcular o espectrograma tempo–frequência",
                "formula": "STFT_x(t,ω)=Σ_n x[n]w[n−t]e^{−iωn}",
                "passos": [
                    f"Tempos dos quadros: {tempos.tolist()}.",
                    f"Frequências: {frequencias.tolist()}.",
                    f"Frequência dominante por quadro: {frequencia_dominante}.",
                ],
                "resultado": {
                    "tempos": tempos.tolist(),
                    "frequências": frequencias.tolist(),
                    "STFT": z.tolist(),
                    "magnitude": magnitude.tolist(),
                    "frequência_dominante": frequencia_dominante,
                },
                "verificacao": {
                    "forma": list(z.shape),
                },
            }

        wigner = re.fullmatch(
            r"wigner\s+ville\s+(.+)",
            texto,
        )

        if not wigner:
            return None

        try:
            sinal = ParserFourierSinaisPSF.amostras(
                wigner.group(1),
                complexo=True,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        n = len(sinal)

        if n > 2048:
            return {
                "erro": (
                    "A Wigner–Ville exata está limitada a 2048 amostras."
                )
            }

        distribuicao = np.zeros((n, n), dtype=float)

        for tempo in range(n):
            correlacao = np.zeros(n, dtype=complex)
            limite = min(tempo, n-1-tempo)

            for tau in range(-limite, limite+1):
                correlacao[tau % n] = (
                    sinal[tempo+tau]
                    * np.conj(sinal[tempo-tau])
                )

            distribuicao[:, tempo] = np.real(
                np.fft.fft(correlacao)
            )

        marginal_tempo = np.sum(
            distribuicao,
            axis=0,
        )/n
        energia_instante = np.abs(sinal)**2

        return {
            "tipo": "distribuição de Wigner–Ville",
            "dados": {"amostras": n},
            "pedido": "Calcular uma representação quadrática tempo–frequência",
            "formula": "W_x(t,ω)=Σ_τ x(t+τ)x*(t−τ)e^{−i2ωτ}",
            "passos": [
                "Calculamos a autocorrelação local em cada instante.",
                "Aplicamos FFT no atraso τ.",
                f"Forma da distribuição: {list(distribuicao.shape)}.",
            ],
            "resultado": {
                "Wigner_Ville": distribuicao.tolist(),
                "marginal_tempo": marginal_tempo.tolist(),
            },
            "verificacao": {
                "energia_instantânea": energia_instante.tolist(),
                "erro_marginal": float(
                    np.max(
                        np.abs(marginal_tempo-energia_instante)
                    )
                ),
            },
            "observacao": (
                "A Wigner–Ville pode apresentar termos de interferência "
                "entre componentes do sinal."
            ),
        }


class MotorProcessamentoSinaisPSF:
    """Convolução, correlação, filtragem FIR e espectro."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        convolucao = re.fullmatch(
            r"sinal\s+convolucao\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if convolucao:
            try:
                x = ParserFourierSinaisPSF.amostras(
                    convolucao.group(1),
                    complexo=False,
                )
                h = ParserFourierSinaisPSF.amostras(
                    convolucao.group(2),
                    complexo=False,
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            y = np.convolve(x, h, mode="full")
            tamanho_fft = 1 << int(
                math.ceil(math.log2(len(y)))
            )
            y_fft = np.fft.ifft(
                np.fft.fft(x, tamanho_fft)
                * np.fft.fft(h, tamanho_fft)
            )[:len(y)].real

            return {
                "tipo": "convolução de sinais",
                "dados": {"x": x.tolist(), "h": h.tolist()},
                "pedido": "Calcular a saída de um sistema LTI",
                "formula": "y[n]=Σ_k x[k]h[n−k]",
                "passos": [
                    f"Comprimento da saída={len(x)}+{len(h)}−1={len(y)}.",
                    f"Convolução direta={y.tolist()}.",
                    f"Convolução via FFT={y_fft.tolist()}.",
                ],
                "resultado": {"y": y.tolist()},
                "verificacao": {
                    "erro_direta_fft": float(
                        np.max(np.abs(y-y_fft))
                    ),
                },
            }

        filtro = re.fullmatch(
            r"sinal\s+fir\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if filtro:
            try:
                x = ParserFourierSinaisPSF.amostras(
                    filtro.group(1),
                    complexo=False,
                )
                b = ParserFourierSinaisPSF.amostras(
                    filtro.group(2),
                    complexo=False,
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            y = np.convolve(x, b, mode="full")[:len(x)]
            frequencias = np.linspace(0, math.pi, 512)
            resposta = np.asarray([
                np.sum(
                    b*np.exp(-1j*omega*np.arange(len(b)))
                )
                for omega in frequencias
            ])

            return {
                "tipo": "filtro FIR",
                "dados": {
                    "sinal": x.tolist(),
                    "coeficientes": b.tolist(),
                },
                "pedido": "Filtrar o sinal e calcular a resposta em frequência",
                "formula": "y[n]=Σ_{k=0}^{M−1}b_kx[n−k]",
                "passos": [
                    f"Saída causal truncada={y.tolist()}.",
                    "Avaliamos H(e^{iω}) numa grade de 512 frequências.",
                ],
                "resultado": {
                    "saída": y.tolist(),
                    "frequências_radianos": frequencias.tolist(),
                    "magnitude_resposta": np.abs(resposta).tolist(),
                    "fase_resposta": np.angle(resposta).tolist(),
                },
                "verificacao": {
                    "energia_entrada": float(np.sum(x**2)),
                    "energia_saída": float(np.sum(y**2)),
                },
            }

        espectro = re.fullmatch(
            r"sinal\s+espectro\s+(.+?)\s*;\s*([0-9.eE+-]+)",
            texto,
        )

        if not espectro:
            return None

        try:
            x = ParserFourierSinaisPSF.amostras(
                espectro.group(1),
                complexo=False,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        fs = float(espectro.group(2))

        if fs <= 0:
            return {"erro": "fs deve ser positivo."}

        janela = np.hanning(len(x))
        ganho = np.sum(janela)
        transformada = np.fft.rfft(x*janela)
        frequencias = np.fft.rfftfreq(
            len(x),
            d=1/fs,
        )
        amplitude = (
            2*np.abs(transformada)/ganho
            if ganho > 0
            else np.abs(transformada)
        )
        pico = int(np.argmax(amplitude))

        return {
            "tipo": "espectro de sinal amostrado",
            "dados": {"amostras": len(x), "fs": fs},
            "pedido": "Estimar frequências e amplitudes espectrais",
            "formula": "X[k]=FFT{x[n]w[n]}",
            "passos": [
                "Aplicamos janela de Hann para reduzir leakage.",
                f"Frequências={frequencias.tolist()}.",
                f"Amplitudes={amplitude.tolist()}.",
            ],
            "resultado": {
                "frequências": frequencias.tolist(),
                "amplitudes": amplitude.tolist(),
                "frequência_pico": float(frequencias[pico]),
                "amplitude_pico": float(amplitude[pico]),
            },
            "verificacao": {
                "resolução_frequencial": fs/len(x),
            },
        }


class MotorCompressaoImagensWaveletPSF:
    """Compressão matricial inspirada em JPEG2000 com Haar e limiarização."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"compressao\s+imagem\s+wavelet\s+(.+?)\s*;\s*"
            r"(\d+)\s*;\s*([0-9.eE+-]+)",
            texto,
        )

        if not padrao:
            return None

        try:
            imagem = ParserFourierSinaisPSF.matriz(
                padrao.group(1)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        niveis = int(padrao.group(2))
        manter = float(padrao.group(3))

        if niveis < 1 or niveis > 10:
            return {"erro": "Os níveis devem estar entre 1 e 10."}
        if not (0 < manter <= 1):
            return {"erro": "A fração a manter deve estar em (0,1]."}

        min_dim = min(imagem.shape)
        max_niveis = int(math.floor(math.log2(min_dim)))

        if niveis > max_niveis:
            return {
                "erro": (
                    f"Para a imagem fornecida, o máximo é {max_niveis} níveis."
                )
            }

        ll, blocos, formas = FerramentasHaarPSF.haar2(
            imagem,
            niveis,
        )
        todos = [ll.reshape(-1)]

        for lh, hl, hh in blocos:
            todos.extend([
                lh.reshape(-1),
                hl.reshape(-1),
                hh.reshape(-1),
            ])

        vetor_coef = np.concatenate(todos)
        quantidade_manter = max(
            1,
            int(math.ceil(manter*len(vetor_coef))),
        )
        limiar = np.partition(
            np.abs(vetor_coef),
            -quantidade_manter,
        )[-quantidade_manter]

        ll_q = ll.copy()
        ll_q[np.abs(ll_q) < limiar] = 0
        blocos_q = []

        for lh, hl, hh in blocos:
            componentes = []

            for componente in (lh, hl, hh):
                copia = componente.copy()
                copia[np.abs(copia) < limiar] = 0
                componentes.append(copia)

            blocos_q.append(tuple(componentes))

        reconstruida = FerramentasHaarPSF.ihaar2(
            ll_q,
            blocos_q,
            formas,
        )[:imagem.shape[0], :imagem.shape[1]]
        mse = float(np.mean((imagem-reconstruida)**2))
        faixa = float(np.max(imagem)-np.min(imagem))

        if mse == 0:
            psnr = math.inf
        elif faixa == 0:
            psnr = -math.inf
        else:
            psnr = 10*math.log10(faixa**2/mse)

        nao_zero = int(np.count_nonzero(ll_q)) + sum(
            int(np.count_nonzero(componente))
            for bloco in blocos_q
            for componente in bloco
        )
        taxa = len(vetor_coef)/max(1, nao_zero)
        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "imagem_wavelet_reconstruida.png"
        figura, eixo = plt.subplots(figsize=(7, 6))
        eixo.imshow(reconstruida, cmap="gray")
        eixo.set_title("Reconstrução wavelet")
        eixo.axis("off")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "compressão de imagem por wavelets",
            "dados": {
                "forma": list(imagem.shape),
                "níveis": niveis,
                "fração_coeficientes_alvo": manter,
            },
            "pedido": "Transformar, limiarizar e reconstruir a imagem",
            "formula": (
                "DWT 2D → manter maiores coeficientes → IDWT 2D"
            ),
            "passos": [
                f"Coeficientes totais={len(vetor_coef)}.",
                f"Coeficientes-alvo={quantidade_manter}.",
                f"Limiar absoluto={limiar}.",
                f"Coeficientes não nulos após limiar={nao_zero}.",
                f"MSE={mse}; PSNR={psnr}.",
            ],
            "resultado": {
                "reconstrução": reconstruida.tolist(),
                "MSE": mse,
                "PSNR_dB": psnr,
                "taxa_esparsa_aproximada": taxa,
                "coeficientes_não_zero": nao_zero,
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "forma_preservada": list(reconstruida.shape) == list(imagem.shape),
                "valores_finitos": bool(np.isfinite(reconstruida).all()),
            },
            "observacao": (
                "É uma demonstração wavelet inspirada no princípio do JPEG2000; "
                "não produz um ficheiro codificado no padrão JPEG2000."
            ),
        }



class ParserInformacaoCodigosPSF:
    """Probabilidades, sequências binárias e matrizes de códigos."""

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @classmethod
    def probabilidades(cls, texto):
        dados = cls.literal(texto, "probabilidades")

        if isinstance(dados, dict):
            simbolos = list(dados.keys())
            valores = np.asarray(list(dados.values()), dtype=float)
        elif isinstance(dados, (list, tuple)):
            simbolos = list(range(len(dados)))
            valores = np.asarray(dados, dtype=float)
        else:
            raise ValueError("Probabilidades devem ser lista ou dicionário.")

        if len(valores) == 0 or np.any(valores < 0):
            raise ValueError("Probabilidades devem ser não negativas e não vazias.")

        soma = float(np.sum(valores))

        if soma <= 0:
            raise ValueError("A soma das probabilidades deve ser positiva.")

        valores = valores/soma
        return simbolos, valores, soma

    @classmethod
    def bits(cls, texto):
        dados = cls.literal(texto, "bits")

        if isinstance(dados, str):
            valores = [int(v) for v in dados if v in "01"]
        else:
            try:
                valores = [int(v) for v in dados]
            except (TypeError, ValueError) as erro:
                raise ValueError("Bits devem formar uma lista ou texto binário.") from erro

        if not valores or any(v not in (0, 1) for v in valores):
            raise ValueError("A sequência deve conter apenas 0 e 1.")

        return valores

    @classmethod
    def matriz_binaria(cls, texto, nome="matriz"):
        dados = cls.literal(texto, nome)

        try:
            matriz = np.asarray(dados, dtype=int)
        except (TypeError, ValueError) as erro:
            raise ValueError(f"{nome.capitalize()} inválida.") from erro

        if matriz.ndim != 2 or min(matriz.shape) == 0:
            raise ValueError(f"{nome.capitalize()} deve ser bidimensional.")

        return matriz % 2


class MotorEntropiaShannonPSF:
    """Entropia, perplexidade e quantidade efetiva de símbolos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"entropia\s+shannon\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            simbolos, probabilidades, soma_original = (
                ParserInformacaoCodigosPSF.probabilidades(
                    padrao.group(1)
                )
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        positivos = probabilidades > 0
        contribuições = np.zeros_like(probabilidades)
        contribuições[positivos] = (
            -probabilidades[positivos]
            * np.log2(probabilidades[positivos])
        )
        entropia = float(np.sum(contribuições))
        perplexidade = 2**entropia
        maximo = math.log2(len(probabilidades))
        redundancia = maximo-entropia

        return {
            "tipo": "entropia de Shannon",
            "dados": {
                "símbolos": simbolos,
                "probabilidades_normalizadas": probabilidades.tolist(),
                "soma_original": soma_original,
            },
            "pedido": "Calcular a incerteza média da fonte",
            "formula": "H(X)=−Σ_x p(x)log₂p(x)",
            "passos": [
                f"Contribuições −p log₂p: {contribuições.tolist()}.",
                f"H={entropia} bits.",
                f"2^H={perplexidade} símbolos equiprováveis efetivos.",
                f"H_max=log₂({len(probabilidades)})={maximo}.",
            ],
            "resultado": {
                "entropia_bits": entropia,
                "perplexidade": perplexidade,
                "entropia_máxima": maximo,
                "redundância": redundancia,
                "eficiência": (
                    entropia/maximo
                    if maximo > 0
                    else 1.0
                ),
            },
            "verificacao": {
                "H_entre_zero_e_log_cardinalidade": (
                    -1e-12 <= entropia <= maximo+1e-12
                ),
            },
        }


class MotorInformacaoMutuaKLPSF:
    """Informação mútua e divergências KL/Jensen–Shannon."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        kl = re.fullmatch(
            r"divergencia\s+kl\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if kl:
            try:
                _, p, _ = ParserInformacaoCodigosPSF.probabilidades(
                    kl.group(1)
                )
                _, q, _ = ParserInformacaoCodigosPSF.probabilidades(
                    kl.group(2)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if len(p) != len(q):
                return {"erro": "P e Q devem possuir o mesmo tamanho."}
            if np.any((p > 0) & (q == 0)):
                divergencia = math.inf
            else:
                mascara = p > 0
                divergencia = float(
                    np.sum(
                        p[mascara]
                        * np.log2(
                            p[mascara]/q[mascara]
                        )
                    )
                )

            m = (p+q)/2

            def kl_finita(a, b):
                mascara = a > 0
                return float(
                    np.sum(
                        a[mascara]*np.log2(a[mascara]/b[mascara])
                    )
                )

            js = 0.5*kl_finita(p, m)+0.5*kl_finita(q, m)

            return {
                "tipo": "divergência de Kullback–Leibler",
                "dados": {"P": p.tolist(), "Q": q.tolist()},
                "pedido": "Medir a discrepância informacional entre P e Q",
                "formula": "D_KL(P||Q)=Σp_i log₂(p_i/q_i)",
                "passos": [
                    "Normalizamos as duas distribuições.",
                    f"D_KL(P||Q)={divergencia}.",
                    f"Jensen–Shannon={js}.",
                ],
                "resultado": {
                    "KL_bits": divergencia,
                    "Jensen_Shannon_bits": js,
                },
                "verificacao": {
                    "KL_não_negativa": divergencia >= -1e-12,
                    "JS_entre_zero_um": -1e-12 <= js <= 1+1e-12,
                },
            }

        mi = re.fullmatch(
            r"informacao\s+mutua\s+(.+)",
            texto,
        )

        if not mi:
            return None

        try:
            conjunta = np.asarray(
                ParserInformacaoCodigosPSF.literal(
                    mi.group(1),
                    "distribuição conjunta",
                ),
                dtype=float,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if conjunta.ndim != 2 or min(conjunta.shape) == 0:
            return {"erro": "A distribuição conjunta deve ser uma matriz."}
        if np.any(conjunta < 0) or conjunta.sum() <= 0:
            return {"erro": "Probabilidades inválidas."}

        conjunta = conjunta/conjunta.sum()
        px = conjunta.sum(axis=1)
        py = conjunta.sum(axis=0)
        produto = px[:, None]*py[None, :]
        mascara = conjunta > 0
        informação = float(
            np.sum(
                conjunta[mascara]
                * np.log2(
                    conjunta[mascara]/produto[mascara]
                )
            )
        )

        def h(p):
            p = p[p > 0]
            return float(-np.sum(p*np.log2(p)))

        hx = h(px)
        hy = h(py)
        hxy = h(conjunta.reshape(-1))

        return {
            "tipo": "informação mútua",
            "dados": {
                "P_XY": conjunta.tolist(),
                "P_X": px.tolist(),
                "P_Y": py.tolist(),
            },
            "pedido": "Calcular a informação partilhada entre X e Y",
            "formula": "I(X;Y)=Σp(x,y)log₂[p(x,y)/(p(x)p(y))]",
            "passos": [
                f"H(X)={hx}.",
                f"H(Y)={hy}.",
                f"H(X,Y)={hxy}.",
                f"I(X;Y)={informação}.",
            ],
            "resultado": {
                "informação_mútua_bits": informação,
                "H_X": hx,
                "H_Y": hy,
                "H_XY": hxy,
            },
            "verificacao": {
                "identidade_H": abs(informação-(hx+hy-hxy)) < 1e-9,
                "não_negativa": informação >= -1e-12,
            },
        }


class MotorCodigosFontePSF:
    """Códigos de Huffman e Shannon–Fano."""

    @staticmethod
    def huffman(probabilidades):
        heap = []
        contador = itertools.count()

        for simbolo, prob in probabilidades.items():
            heapq.heappush(
                heap,
                (
                    prob,
                    next(contador),
                    simbolo,
                ),
            )

        if len(heap) == 1:
            simbolo = heap[0][2]
            return {simbolo: "0"}, []

        passos = []

        while len(heap) > 1:
            p1, _, n1 = heapq.heappop(heap)
            p2, _, n2 = heapq.heappop(heap)
            novo = (n1, n2)
            heapq.heappush(
                heap,
                (
                    p1+p2,
                    next(contador),
                    novo,
                ),
            )
            passos.append({
                "fundidos": [n1, n2],
                "probabilidades": [p1, p2],
                "nova": p1+p2,
            })

        raiz = heap[0][2]
        codigos = {}

        def percorrer(no, prefixo):
            if not isinstance(no, tuple):
                codigos[no] = prefixo or "0"
                return

            percorrer(no[0], prefixo+"0")
            percorrer(no[1], prefixo+"1")

        percorrer(raiz, "")
        return codigos, passos

    @staticmethod
    def shannon_fano(itens):
        codigos = {
            simbolo: ""
            for simbolo, _ in itens
        }
        passos = []

        def dividir(subitens):
            if len(subitens) <= 1:
                return

            total = sum(prob for _, prob in subitens)
            acumulado = 0
            melhor = 1
            diferença = math.inf

            for indice in range(1, len(subitens)):
                acumulado += subitens[indice-1][1]
                atual = abs(acumulado-(total-acumulado))

                if atual < diferença:
                    diferença = atual
                    melhor = indice

            esquerda = subitens[:melhor]
            direita = subitens[melhor:]

            for simbolo, _ in esquerda:
                codigos[simbolo] += "0"

            for simbolo, _ in direita:
                codigos[simbolo] += "1"

            passos.append({
                "grupo": [s for s, _ in subitens],
                "esquerda": [s for s, _ in esquerda],
                "direita": [s for s, _ in direita],
            })
            dividir(esquerda)
            dividir(direita)

        dividir(itens)
        return codigos, passos

    @staticmethod
    def prefix_free(codigos):
        valores = list(codigos.values())

        return all(
            not outro.startswith(codigo)
            for i, codigo in enumerate(valores)
            for j, outro in enumerate(valores)
            if i != j
        )

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"codigo\s+fonte\s+(huffman|shannon\s+fano)\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        metodo = padrao.group(1).replace(" ", "_")

        try:
            dados = ParserInformacaoCodigosPSF.literal(
                padrao.group(2),
                "probabilidades",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict) or not dados:
            return {"erro": "Forneça um dicionário símbolo:probabilidade."}

        probabilidades = {
            simbolo: float(prob)
            for simbolo, prob in dados.items()
        }

        if any(prob < 0 for prob in probabilidades.values()):
            return {"erro": "Probabilidades não podem ser negativas."}

        soma = sum(probabilidades.values())

        if soma <= 0:
            return {"erro": "A soma deve ser positiva."}

        probabilidades = {
            simbolo: prob/soma
            for simbolo, prob in probabilidades.items()
            if prob > 0
        }

        if metodo == "huffman":
            codigos, passos = self.huffman(probabilidades)
        else:
            itens = sorted(
                probabilidades.items(),
                key=lambda item: item[1],
                reverse=True,
            )
            codigos, passos = self.shannon_fano(itens)

        comprimento_medio = sum(
            probabilidades[simbolo]*len(codigo)
            for simbolo, codigo in codigos.items()
        )
        entropia = -sum(
            prob*math.log2(prob)
            for prob in probabilidades.values()
        )
        kraft = sum(2**(-len(codigo)) for codigo in codigos.values())

        return {
            "tipo": f"código de fonte {metodo}",
            "dados": {"probabilidades": probabilidades},
            "pedido": "Construir um código binário prefixo",
            "formula": "L̄=Σp_i l_i; Σ2^{-l_i}≤1",
            "passos": [
                f"Construção: {passos}.",
                f"Códigos: {codigos}.",
                f"Comprimento médio={comprimento_medio}.",
                f"Entropia={entropia}.",
            ],
            "resultado": {
                "códigos": codigos,
                "comprimento_médio": comprimento_medio,
                "entropia": entropia,
                "redundância": comprimento_medio-entropia,
                "Kraft": kraft,
            },
            "verificacao": {
                "prefix_free": self.prefix_free(codigos),
                "Kraft≤1": kraft <= 1+1e-12,
                "H≤L": entropia <= comprimento_medio+1e-12,
            },
        }


class MotorCapacidadeCanalPSF:
    """Capacidade de canal binário e canal discreto geral."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        bsc = re.fullmatch(
            r"capacidade\s+bsc\s+([0-9.eE+-]+)",
            texto,
        )

        if bsc:
            p = float(bsc.group(1))

            if not (0 <= p <= 1):
                return {"erro": "p deve estar entre 0 e 1."}

            def h2(valor):
                if valor in (0, 1):
                    return 0.0

                return (
                    -valor*math.log2(valor)
                    -(1-valor)*math.log2(1-valor)
                )

            capacidade = 1-h2(p)

            return {
                "tipo": "capacidade de canal binário simétrico",
                "dados": {"probabilidade_erro": p},
                "pedido": "Calcular a capacidade por uso do canal",
                "formula": "C=1−H₂(p)",
                "passos": [
                    f"H₂({p})={h2(p)}.",
                    f"C={capacidade} bits/uso.",
                ],
                "resultado": {"capacidade_bits_por_uso": capacidade},
                "verificacao": {
                    "entre_zero_um": 0 <= capacidade <= 1+1e-12,
                },
            }

        geral = re.fullmatch(
            r"capacidade\s+canal\s+(.+)"
            r"(?:\s*;\s*([0-9.eE+-]+))?"
            r"(?:\s*;\s*(\d+))?",
            texto,
        )

        if not geral:
            return None

        try:
            canal = np.asarray(
                ParserInformacaoCodigosPSF.literal(
                    geral.group(1),
                    "matriz do canal",
                ),
                dtype=float,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        tolerancia = float(geral.group(2) or 1e-12)
        max_iter = int(geral.group(3) or 10000)

        if canal.ndim != 2 or min(canal.shape) == 0:
            return {"erro": "A matriz do canal deve ser bidimensional."}
        if np.any(canal < 0) or not np.allclose(
            canal.sum(axis=1),
            1,
            atol=1e-9,
        ):
            return {"erro": "Cada linha P(y|x) deve somar 1."}

        entradas, saidas = canal.shape
        q = np.full(entradas, 1/entradas)
        historico = []
        convergiu = False

        for iteracao in range(1, max_iter+1):
            py = q@canal
            d = np.zeros(entradas)

            for i in range(entradas):
                mascara = canal[i] > 0
                d[i] = np.sum(
                    canal[i, mascara]
                    * np.log2(
                        canal[i, mascara]/py[mascara]
                    )
                )

            novo = q*(2**d)
            novo = novo/novo.sum()
            erro = float(np.max(np.abs(novo-q)))
            q = novo

            if iteracao <= 100 or iteracao == max_iter:
                historico.append({
                    "iteração": iteracao,
                    "entrada": q.tolist(),
                    "erro": erro,
                    "D": d.tolist(),
                })

            if erro <= tolerancia:
                convergiu = True
                break

        py = q@canal
        capacidade = 0.0

        for i in range(entradas):
            mascara = canal[i] > 0
            capacidade += q[i]*np.sum(
                canal[i, mascara]
                * np.log2(
                    canal[i, mascara]/py[mascara]
                )
            )

        return {
            "tipo": "capacidade de canal discreto",
            "dados": {
                "P_y_dado_x": canal.tolist(),
                "entradas": entradas,
                "saídas": saidas,
            },
            "pedido": "Maximizar I(X;Y) pelo algoritmo de Blahut–Arimoto",
            "formula": "C=max_{p(x)} I(X;Y)",
            "passos": [
                "Inicializamos a distribuição de entrada uniformemente.",
                "Alternamos divergências por símbolo e atualização de p(x).",
                f"Histórico: {historico}.",
            ],
            "resultado": {
                "capacidade_bits_por_uso": float(capacidade),
                "distribuição_entrada_ótima": q.tolist(),
                "distribuição_saída": py.tolist(),
                "iterações": iteracao,
                "convergiu": convergiu,
            },
            "verificacao": {
                "soma_entrada": float(q.sum()),
                "soma_saída": float(py.sum()),
            },
            "justificacao": (
                "O máximo de iterações foi atingido antes de satisfazer a "
                "tolerância. A capacidade apresentada é aproximada e a "
                "convergência solicitada não foi confirmada."
                if not convergiu
                else None
            ),
        }


class MotorCodigosCorretoresPSF:
    """Hamming(7,4) e Reed–Solomon por avaliação/interpolação."""

    @staticmethod
    def hamming_encode(bits):
        d1, d2, d3, d4 = bits
        p1 = d1 ^ d2 ^ d4
        p2 = d1 ^ d3 ^ d4
        p3 = d2 ^ d3 ^ d4
        return [p1, p2, d1, p3, d2, d3, d4]

    @staticmethod
    def hamming_syndrome(palavra):
        b = [0]+palavra
        s1 = b[1] ^ b[3] ^ b[5] ^ b[7]
        s2 = b[2] ^ b[3] ^ b[6] ^ b[7]
        s3 = b[4] ^ b[5] ^ b[6] ^ b[7]
        return s1+2*s2+4*s3

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        hamming_enc = re.fullmatch(
            r"hamming\s+74\s+codificar\s+(.+)",
            texto,
        )

        if hamming_enc:
            try:
                bits = ParserInformacaoCodigosPSF.bits(
                    hamming_enc.group(1)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if len(bits) != 4:
                return {"erro": "Hamming(7,4) exige quatro bits de dados."}

            palavra = self.hamming_encode(bits)

            return {
                "tipo": "código Hamming(7,4)",
                "dados": {"dados": bits},
                "pedido": "Calcular três bits de paridade e formar a palavra",
                "formula": "posições 1,2,4 são paridades; 3,5,6,7 são dados",
                "passos": [
                    f"p1=d1⊕d2⊕d4={palavra[0]}.",
                    f"p2=d1⊕d3⊕d4={palavra[1]}.",
                    f"p3=d2⊕d3⊕d4={palavra[3]}.",
                    f"Palavra={palavra}.",
                ],
                "resultado": {"palavra": palavra},
                "verificacao": {
                    "síndrome": self.hamming_syndrome(palavra),
                },
            }

        hamming_dec = re.fullmatch(
            r"hamming\s+74\s+decodificar\s+(.+)",
            texto,
        )

        if hamming_dec:
            try:
                recebida = ParserInformacaoCodigosPSF.bits(
                    hamming_dec.group(1)
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if len(recebida) != 7:
                return {"erro": "Hamming(7,4) exige sete bits recebidos."}

            sindrome = self.hamming_syndrome(recebida)
            corrigida = recebida[:]

            if sindrome:
                corrigida[sindrome-1] ^= 1

            dados = [
                corrigida[2],
                corrigida[4],
                corrigida[5],
                corrigida[6],
            ]

            return {
                "tipo": "decodificação Hamming(7,4)",
                "dados": {"recebida": recebida},
                "pedido": "Localizar e corrigir um erro de bit",
                "formula": "síndrome binária identifica a posição do erro",
                "passos": [
                    f"Síndrome={sindrome}.",
                    (
                        f"Invertemos a posição {sindrome}."
                        if sindrome
                        else "Nenhum erro simples foi indicado."
                    ),
                    f"Palavra corrigida={corrigida}.",
                ],
                "resultado": {
                    "síndrome": sindrome,
                    "palavra_corrigida": corrigida,
                    "dados": dados,
                },
                "verificacao": {
                    "síndrome_após_correção": self.hamming_syndrome(corrigida),
                },
            }

        rs = re.fullmatch(
            r"reed\s+solomon\s+codificar\s+"
            r"(\d+)\s*;\s*(.+?)\s*;\s*(.+)",
            texto,
        )

        if rs:
            p = int(rs.group(1))

            if not sp.isprime(p):
                return {"erro": "O módulo p deve ser primo."}

            try:
                mensagem = [
                    int(v) % p
                    for v in ParserInformacaoCodigosPSF.literal(
                        rs.group(2),
                        "coeficientes",
                    )
                ]
                pontos = [
                    int(v) % p
                    for v in ParserInformacaoCodigosPSF.literal(
                        rs.group(3),
                        "pontos de avaliação",
                    )
                ]
            except (ValueError, TypeError) as erro:
                return {"erro": str(erro)}

            if not mensagem or not pontos:
                return {"erro": "Coeficientes e pontos não podem ser vazios."}
            if len(set(pontos)) != len(pontos):
                return {"erro": "Os pontos de avaliação devem ser distintos."}
            if len(mensagem) > len(pontos):
                return {"erro": "O número de coeficientes deve ser ≤ n."}

            palavra = [
                sum(
                    coef*pow(x, grau, p)
                    for grau, coef in enumerate(mensagem)
                ) % p
                for x in pontos
            ]
            distancia = len(pontos)-len(mensagem)+1

            return {
                "tipo": "código Reed–Solomon por avaliação",
                "dados": {
                    "GF": p,
                    "coeficientes": mensagem,
                    "pontos": pontos,
                },
                "pedido": "Avaliar o polinômio da mensagem nos pontos do corpo",
                "formula": "c_i=m(α_i); d_min=n−k+1",
                "passos": [
                    f"m(x)=Σm_jx^j com coeficientes {mensagem}.",
                    f"Avaliações={palavra}.",
                    f"Distância mínima projetada={distancia}.",
                ],
                "resultado": {
                    "palavra": palavra,
                    "parâmetros": [len(pontos), len(mensagem), distancia],
                    "erros_corrigíveis": (distancia-1)//2,
                },
                "verificacao": {
                    "comprimento": len(palavra),
                },
            }

        rs_interp = re.fullmatch(
            r"reed\s+solomon\s+interpolar\s+"
            r"(\d+)\s*;\s*(.+?)\s*;\s*(.+)",
            texto,
        )

        if not rs_interp:
            return None

        p = int(rs_interp.group(1))

        if not sp.isprime(p):
            return {"erro": "p deve ser primo."}

        try:
            xs = [
                int(v) % p
                for v in ParserInformacaoCodigosPSF.literal(
                    rs_interp.group(2),
                    "pontos",
                )
            ]
            ys = [
                int(v) % p
                for v in ParserInformacaoCodigosPSF.literal(
                    rs_interp.group(3),
                    "valores",
                )
            ]
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        if len(xs) != len(ys) or not xs or len(set(xs)) != len(xs):
            return {"erro": "Pontos distintos e valores de mesmo tamanho são exigidos."}

        x = sp.Symbol("x")
        polinomio = 0
        termos = []

        for i, (xi, yi) in enumerate(zip(xs, ys)):
            numerador = 1
            denominador = 1

            for j, xj in enumerate(xs):
                if i == j:
                    continue

                numerador *= x-xj
                denominador = denominador*(xi-xj) % p

            inverso = pow(denominador % p, -1, p)
            termo = yi*inverso*numerador
            polinomio += termo
            termos.append(sp.sstr(sp.expand(termo)))

        poly = sp.Poly(
            sp.expand(polinomio),
            x,
            modulus=p,
        )
        verificacao = [
            int(poly.eval(xi)) % p
            for xi in xs
        ]

        return {
            "tipo": "interpolação Reed–Solomon",
            "dados": {"GF": p, "pontos": xs, "valores": ys},
            "pedido": "Reconstruir o polinômio a partir de símbolos conhecidos",
            "formula": "m(x)=Σy_i∏_{j≠i}(x−x_j)/(x_i−x_j)",
            "passos": [
                f"Termos de Lagrange: {termos}.",
                f"Polinômio reduzido módulo {p}: {sp.sstr(poly.as_expr())}.",
            ],
            "resultado": {
                "polinômio": sp.sstr(poly.as_expr()),
                "coeficientes": [
                    int(v) % p
                    for v in reversed(poly.all_coeffs())
                ],
            },
            "verificacao": {
                "valores_recalculados": verificacao,
                "esperados": ys,
                "coincidem": verificacao == ys,
            },
            "observacao": (
                "Esta operação reconstrói a partir de símbolos conhecidos; "
                "a localização automática de erros desconhecidos exige "
                "algoritmos adicionais de decodificação."
            ),
        }


class FerramentasConvolucionaisPSF:
    """Codificação convolucional e Viterbi hard-decision."""

    @staticmethod
    def polinomio_bits(valor, memoria):
        return [
            (valor >> i) & 1
            for i in range(memoria, -1, -1)
        ]

    @classmethod
    def transicoes(cls, geradores, memoria):
        estados = 2**memoria
        tabela = {}

        for estado in range(estados):
            memoria_bits = [
                (estado >> (memoria-1-i)) & 1
                for i in range(memoria)
            ] if memoria else []

            for bit in (0, 1):
                registrador = [bit]+memoria_bits
                saida = []

                for gerador in geradores:
                    coef = cls.polinomio_bits(gerador, memoria)
                    saida.append(
                        sum(
                            a*b
                            for a, b in zip(registrador, coef)
                        ) % 2
                    )

                nova_memoria = registrador[:-1] if memoria else []
                novo_estado = 0

                for valor in nova_memoria:
                    novo_estado = (novo_estado << 1)|valor

                tabela[(estado, bit)] = (
                    novo_estado,
                    tuple(saida),
                )

        return tabela

    @classmethod
    def codificar(cls, bits, geradores, memoria, terminar=True):
        tabela = cls.transicoes(geradores, memoria)
        estado = 0
        entrada = list(bits)+([0]*memoria if terminar else [])
        saida = []
        passos = []

        for indice, bit in enumerate(entrada):
            novo, simbolos = tabela[(estado, bit)]
            passos.append({
                "índice": indice,
                "estado": estado,
                "bit": bit,
                "saída": simbolos,
                "novo_estado": novo,
            })
            saida.extend(simbolos)
            estado = novo

        return saida, passos, estado

    @classmethod
    def viterbi(cls, recebidos, geradores, memoria, terminado=True):
        taxa = len(geradores)

        if len(recebidos) % taxa:
            raise ValueError("O comprimento recebido deve ser múltiplo da taxa.")

        tabela = cls.transicoes(geradores, memoria)
        estados = 2**memoria
        infinito = 10**18
        metricas = [infinito]*estados
        metricas[0] = 0
        sobreviventes = []
        passos = len(recebidos)//taxa

        for tempo in range(passos):
            símbolo = tuple(
                recebidos[tempo*taxa:(tempo+1)*taxa]
            )
            novas = [infinito]*estados
            predecessor = [None]*estados

            for estado in range(estados):
                if metricas[estado] >= infinito:
                    continue

                for bit in (0, 1):
                    destino, esperado = tabela[(estado, bit)]
                    distância = sum(
                        a != b
                        for a, b in zip(símbolo, esperado)
                    )
                    candidata = metricas[estado]+distância

                    if candidata < novas[destino]:
                        novas[destino] = candidata
                        predecessor[destino] = (
                            estado,
                            bit,
                            esperado,
                        )

            metricas = novas
            sobreviventes.append(predecessor)

        estado_final = (
            0
            if terminado and metricas[0] < infinito
            else int(np.argmin(metricas))
        )
        bits = []
        caminho = []
        estado = estado_final

        for tempo in range(passos-1, -1, -1):
            registro = sobreviventes[tempo][estado]

            if registro is None:
                raise ValueError("Não existe caminho válido no trellis.")

            anterior, bit, esperado = registro
            bits.append(bit)
            caminho.append({
                "tempo": tempo,
                "estado": anterior,
                "bit": bit,
                "saída_esperada": esperado,
                "destino": estado,
            })
            estado = anterior

        bits.reverse()
        caminho.reverse()

        if terminado and memoria:
            dados = bits[:-memoria]
        else:
            dados = bits

        return dados, bits, caminho, metricas[estado_final]


class MotorCodigosConvolucionaisViterbiPSF:
    """Codificação convolucional e decodificação Viterbi."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        codificar = re.fullmatch(
            r"convolucional\s+codificar\s+(.+?)\s*;\s*(.+?)\s*;\s*(\d+)",
            texto,
        )

        if codificar:
            try:
                bits = ParserInformacaoCodigosPSF.bits(codificar.group(1))
                geradores = [
                    int(v)
                    for v in ParserInformacaoCodigosPSF.literal(
                        codificar.group(2),
                        "geradores",
                    )
                ]
            except (ValueError, TypeError) as erro:
                return {"erro": str(erro)}

            memoria = int(codificar.group(3))

            if memoria < 1 or memoria > 15:
                return {"erro": "A memória deve estar entre 1 e 15."}
            if not geradores or any(
                g <= 0 or g >= 2**(memoria+1)
                for g in geradores
            ):
                return {"erro": "Geradores incompatíveis com a memória."}

            saida, passos, estado = FerramentasConvolucionaisPSF.codificar(
                bits,
                geradores,
                memoria,
                terminar=True,
            )

            return {
                "tipo": "código convolucional",
                "dados": {
                    "bits": bits,
                    "geradores": geradores,
                    "memória": memoria,
                },
                "pedido": "Codificar no trellis e terminar no estado zero",
                "formula": "saídas são produtos escalares módulo 2 do registrador",
                "passos": [f"Trellis percorrido: {passos}."],
                "resultado": {
                    "codificado": saida,
                    "estado_final": estado,
                    "taxa_nominal": f"1/{len(geradores)}",
                },
                "verificacao": {"terminou_em_zero": estado == 0},
            }

        viterbi = re.fullmatch(
            r"viterbi\s+decodificar\s+(.+?)\s*;\s*(.+?)\s*;\s*(\d+)",
            texto,
        )

        if not viterbi:
            return None

        try:
            recebidos = ParserInformacaoCodigosPSF.bits(viterbi.group(1))
            geradores = [
                int(v)
                for v in ParserInformacaoCodigosPSF.literal(
                    viterbi.group(2),
                    "geradores",
                )
            ]
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        memoria = int(viterbi.group(3))

        try:
            dados, caminho_bits, caminho, métrica = (
                FerramentasConvolucionaisPSF.viterbi(
                    recebidos,
                    geradores,
                    memoria,
                    terminado=True,
                )
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        recodificado, _, _ = FerramentasConvolucionaisPSF.codificar(
            dados,
            geradores,
            memoria,
            terminar=True,
        )

        return {
            "tipo": "decodificação Viterbi",
            "dados": {
                "recebidos": recebidos,
                "geradores": geradores,
                "memória": memoria,
            },
            "pedido": "Encontrar o caminho de menor distância no trellis",
            "formula": "métrica acumulada = soma das distâncias de Hamming",
            "passos": [
                f"Caminho sobrevivente: {caminho}.",
                f"Métrica final={métrica}.",
            ],
            "resultado": {
                "dados_decodificados": dados,
                "bits_com_terminação": caminho_bits,
                "métrica": métrica,
                "recodificado": recodificado,
            },
            "verificacao": {
                "distância_recebido_recodificado": sum(
                    a != b
                    for a, b in zip(recebidos, recodificado)
                ),
            },
        }


class MotorTurboLDPCPSF:
    """Codificador turbo didático e decodificador LDPC por bit flipping."""

    @staticmethod
    def rsc(bits):
        estado = [0, 0]
        paridade = []
        passos = []

        for indice, bit in enumerate(bits):
            realimentado = bit ^ estado[0] ^ estado[1]
            par = realimentado ^ estado[1]
            novo_estado = [realimentado, estado[0]]
            passos.append({
                "índice": indice,
                "entrada": bit,
                "estado": estado[:],
                "feedback": realimentado,
                "paridade": par,
                "novo_estado": novo_estado[:],
            })
            paridade.append(par)
            estado = novo_estado

        return paridade, passos

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        turbo = re.fullmatch(
            r"turbo\s+codificar\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if turbo:
            try:
                bits = ParserInformacaoCodigosPSF.bits(
                    turbo.group(1)
                )
                permutacao = [
                    int(v)
                    for v in ParserInformacaoCodigosPSF.literal(
                        turbo.group(2),
                        "interleaver",
                    )
                ]
            except (ValueError, TypeError) as erro:
                return {"erro": str(erro)}

            if sorted(permutacao) != list(range(len(bits))):
                return {"erro": "O interleaver deve ser uma permutação dos índices."}

            intercalados = [bits[i] for i in permutacao]
            p1, passos1 = self.rsc(bits)
            p2, passos2 = self.rsc(intercalados)
            palavra = []

            for sistematico, a, b in zip(bits, p1, p2):
                palavra.extend([sistematico, a, b])

            return {
                "tipo": "codificador turbo didático",
                "dados": {
                    "bits": bits,
                    "interleaver": permutacao,
                },
                "pedido": "Concatenar dois codificadores RSC em paralelo",
                "formula": "saída=(bit sistemático, paridade 1, paridade 2)",
                "passos": [
                    f"Sequência intercalada={intercalados}.",
                    f"Primeiro RSC={passos1}.",
                    f"Segundo RSC={passos2}.",
                ],
                "resultado": {
                    "palavra_turbo": palavra,
                    "paridade_1": p1,
                    "paridade_2": p2,
                    "taxa": "1/3",
                },
                "verificacao": {
                    "comprimento": len(palavra),
                    "esperado": 3*len(bits),
                },
                "observacao": (
                    "É um codificador turbo didático. A decodificação iterativa "
                    "MAP/Log-MAP não está implícita nesta operação."
                ),
            }

        ldpc = re.fullmatch(
            r"ldpc\s+bitflip\s+(.+?)\s*;\s*(.+?)\s*;\s*(\d+)",
            texto,
        )

        if not ldpc:
            return None

        try:
            h = ParserInformacaoCodigosPSF.matriz_binaria(
                ldpc.group(1),
                "H",
            )
            recebido = np.asarray(
                ParserInformacaoCodigosPSF.bits(
                    ldpc.group(2)
                ),
                dtype=int,
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        max_iter = int(ldpc.group(3))

        if h.shape[1] != len(recebido):
            return {"erro": "H deve possuir uma coluna por bit recebido."}
        if max_iter < 1 or max_iter > 10000:
            return {"erro": "max_iter deve estar entre 1 e 10000."}

        palavra = recebido.copy()
        historico = []
        convergiu = False

        for iteracao in range(1, max_iter+1):
            sindrome = (h@palavra) % 2

            if not np.any(sindrome):
                convergiu = True
                break

            insatisfeitas = h.T@sindrome
            máximo = int(np.max(insatisfeitas))
            candidatos = np.where(insatisfeitas == máximo)[0]

            if máximo == 0:
                break

            palavra[candidatos] ^= 1
            historico.append({
                "iteração": iteracao,
                "síndrome": sindrome.tolist(),
                "contagens": insatisfeitas.tolist(),
                "bits_invertidos": candidatos.tolist(),
                "palavra": palavra.tolist(),
            })

        sindrome_final = (h@palavra) % 2

        return {
            "tipo": "decodificação LDPC por bit flipping",
            "dados": {
                "H": h.tolist(),
                "recebido": recebido.tolist(),
                "max_iter": max_iter,
            },
            "pedido": "Reduzir a síndrome invertendo bits mais suspeitos",
            "formula": "s=Hrᵀ mod 2; inverter bits ligados a mais checks falhos",
            "passos": [
                f"Histórico: {historico}.",
                f"Síndrome final={sindrome_final.tolist()}.",
            ],
            "resultado": {
                "palavra_decodificada": palavra.tolist(),
                "síndrome_final": sindrome_final.tolist(),
                "convergiu": convergiu,
                "iterações": len(historico),
            },
            "verificacao": {
                "parity_checks_satisfeitos": not np.any(sindrome_final),
            },
            "justificacao": (
                "O algoritmo heurístico de bit flipping não zerou a síndrome "
                "dentro do limite. Isso não prova que não exista palavra-código "
                "próxima; apenas indica que este decodificador não convergiu."
                if not convergiu
                else None
            ),
        }


class MotorInformacaoQuanticaPSF:
    """Matrizes densidade, entropia de von Neumann e emaranhamento bipartido."""

    @staticmethod
    def matriz_complexa(texto, nome):
        dados = ParserInformacaoCodigosPSF.literal(texto, nome)

        try:
            matriz = np.asarray(dados, dtype=complex)
        except (TypeError, ValueError) as erro:
            raise ValueError(f"{nome.capitalize()} inválida.") from erro

        if matriz.ndim != 2 or matriz.shape[0] != matriz.shape[1]:
            raise ValueError(f"{nome.capitalize()} deve ser quadrada.")

        return matriz

    @staticmethod
    def entropia_vn(rho):
        autovalores = np.linalg.eigvalsh(
            (rho+rho.conj().T)/2
        )
        autovalores = np.clip(
            np.real(autovalores),
            0,
            1,
        )
        positivos = autovalores > 1e-15
        entropia = float(
            -np.sum(
                autovalores[positivos]
                * np.log2(autovalores[positivos])
            )
        )
        return entropia, autovalores

    @staticmethod
    def parcial_estado_puro(psi, da, db, subsistema):
        tensor = psi.reshape(da, db)

        if subsistema == "a":
            return tensor@tensor.conj().T

        return tensor.conj().T@tensor

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        densidade = re.fullmatch(
            r"informacao\s+quantica\s+densidade\s+(.+)",
            texto,
        )

        if densidade:
            try:
                rho = self.matriz_complexa(
                    densidade.group(1),
                    "matriz densidade",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            hermitiana = np.allclose(rho, rho.conj().T)
            traço = complex(np.trace(rho))
            entropia, autovalores = self.entropia_vn(rho)
            positiva = bool(np.min(autovalores) >= -1e-10)
            pureza = float(np.real(np.trace(rho@rho)))

            return {
                "tipo": "informação quântica de matriz densidade",
                "dados": {"rho": rho.tolist()},
                "pedido": "Validar o estado e calcular entropia/pureza",
                "formula": "S(ρ)=−Tr(ρlog₂ρ); γ=Tr(ρ²)",
                "passos": [
                    f"Hermitiana={hermitiana}.",
                    f"Tr(ρ)={traço}.",
                    f"Autovalores={autovalores.tolist()}.",
                    f"S(ρ)={entropia}; pureza={pureza}.",
                ],
                "resultado": {
                    "estado_válido": (
                        hermitiana
                        and abs(traço-1) < 1e-8
                        and positiva
                    ),
                    "entropia_von_Neumann_bits": entropia,
                    "pureza": pureza,
                    "autovalores": autovalores.tolist(),
                },
                "verificacao": {
                    "hermitiana": bool(hermitiana),
                    "traço_um": abs(traço-1) < 1e-8,
                    "positiva": positiva,
                },
            }

        parcial = re.fullmatch(
            r"informacao\s+quantica\s+parcial\s+"
            r"(.+?)\s*;\s*(\d+)\s*;\s*(\d+)\s*;\s*([ab])",
            texto,
        )

        if not parcial:
            return None

        try:
            psi = np.asarray(
                [
                    complex(v)
                    for v in ParserInformacaoCodigosPSF.literal(
                        parcial.group(1),
                        "estado",
                    )
                ],
                dtype=complex,
            )
        except (ValueError, TypeError) as erro:
            return {"erro": str(erro)}

        da = int(parcial.group(2))
        db = int(parcial.group(3))
        subsistema = parcial.group(4)

        if psi.ndim != 1 or len(psi) != da*db:
            return {"erro": "O estado deve possuir da×db amplitudes."}

        norma = np.linalg.norm(psi)

        if norma == 0:
            return {"erro": "O estado não pode ser zero."}

        psi = psi/norma
        rho_reduzida = self.parcial_estado_puro(
            psi,
            da,
            db,
            subsistema,
        )
        entropia, autovalores = self.entropia_vn(rho_reduzida)
        schmidt = np.linalg.svd(
            psi.reshape(da, db),
            compute_uv=False,
        )
        emaranhado = entropia > 1e-10

        return {
            "tipo": "informação quântica bipartida",
            "dados": {
                "dimensões": [da, db],
                "subsistema_reduzido": subsistema.upper(),
            },
            "pedido": "Calcular estado reduzido e entropia de emaranhamento",
            "formula": "ρ_A=Tr_B(|ψ><ψ|); E=S(ρ_A)",
            "passos": [
                f"Estado normalizado={psi.tolist()}.",
                f"Coeficientes de Schmidt={schmidt.tolist()}.",
                f"Matriz reduzida={rho_reduzida.tolist()}.",
                f"Autovalores={autovalores.tolist()}.",
            ],
            "resultado": {
                "rho_reduzida": rho_reduzida.tolist(),
                "entropia_emaranhamento_bits": entropia,
                "coeficientes_Schmidt": schmidt.tolist(),
                "emaranhado": emaranhado,
            },
            "verificacao": {
                "traço_reduzida": complex(np.trace(rho_reduzida)),
                "entropias_subsistemas_iguais_para_estado_puro": True,
            },
        }


class MotorCompressaoPerdasPSF:
    """Comparação entre compressão zlib sem perdas e quantização com perdas."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"compressao\s+comparar\s+(.+?)\s*;\s*([0-9.eE+-]+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserInformacaoCodigosPSF.literal(
                padrao.group(1),
                "dados",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        passo = float(padrao.group(2))

        if passo <= 0:
            return {"erro": "O passo de quantização deve ser positivo."}

        if isinstance(dados, str):
            bruto = dados.encode("utf-8")
            vetor = np.frombuffer(bruto, dtype=np.uint8).astype(float)
            tipo = "texto/bytes"
        else:
            try:
                vetor = np.asarray(dados, dtype=float).reshape(-1)
            except (TypeError, ValueError) as erro:
                return {"erro": str(erro)}

            bruto = vetor.astype(np.float64).tobytes()
            tipo = "numérico"

        comprimido = zlib.compress(bruto, level=9)
        restaurado_bruto = zlib.decompress(comprimido)
        sem_perdas_exato = restaurado_bruto == bruto
        quantizado = np.round(vetor/passo)*passo
        erro = vetor-quantizado
        mse = float(np.mean(erro**2)) if len(vetor) else 0.0
        max_erro = float(np.max(np.abs(erro))) if len(vetor) else 0.0
        níveis = len(np.unique(quantizado))
        simbolos, contagens = np.unique(
            quantizado,
            return_counts=True,
        )
        probabilidades = contagens/len(quantizado) if len(quantizado) else np.asarray([])
        entropia_q = float(
            -np.sum(
                probabilidades*np.log2(probabilidades)
            )
        ) if len(probabilidades) else 0.0
        bits_estimados = entropia_q*len(quantizado)

        return {
            "tipo": "compressão sem perdas versus com perdas",
            "dados": {
                "tipo": tipo,
                "bytes_originais": len(bruto),
                "passo_quantização": passo,
            },
            "pedido": "Comparar reversibilidade, tamanho e distorção",
            "formula": (
                "sem perdas: reconstrução exata; "
                "com perdas: q(x)=Δ round(x/Δ)"
            ),
            "passos": [
                f"zlib: {len(bruto)}→{len(comprimido)} bytes.",
                f"Reconstrução sem perdas exata={sem_perdas_exato}.",
                f"Quantização produziu {níveis} níveis.",
                f"MSE={mse}; erro máximo={max_erro}.",
                f"Entropia dos símbolos quantizados={entropia_q}.",
            ],
            "resultado": {
                "sem_perdas": {
                    "bytes_comprimidos": len(comprimido),
                    "razão": (
                        len(bruto)/len(comprimido)
                        if len(comprimido)
                        else math.inf
                    ),
                    "reconstrução_exata": sem_perdas_exato,
                },
                "com_perdas": {
                    "quantizado": quantizado.tolist(),
                    "MSE": mse,
                    "erro_máximo": max_erro,
                    "níveis": níveis,
                    "entropia_bits_por_amostra": entropia_q,
                    "bits_ideais_estimados": bits_estimados,
                },
            },
            "verificacao": {
                "zlib_reversível": sem_perdas_exato,
                "erro_quantização_limitado_por_delta_sobre_2": (
                    max_erro <= passo/2+1e-12
                ),
            },
        }


class MotorTelecomunicacoesPSF:
    """Orçamento de enlace, Shannon e atenuação em fibra."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        enlace = re.fullmatch(
            r"telecom\s+enlace\s+(.+)",
            texto,
        )

        if enlace:
            try:
                dados = ParserInformacaoCodigosPSF.literal(
                    enlace.group(1),
                    "orçamento de enlace",
                )
            except ValueError as erro:
                return {"erro": str(erro)}

            if not isinstance(dados, dict):
                return {"erro": "Forneça um dicionário de parâmetros."}

            pt = float(dados.get("potencia_tx_dbm", 0))
            gt = float(dados.get("ganho_tx_dbi", 0))
            gr = float(dados.get("ganho_rx_dbi", 0))
            perdas = float(dados.get("perdas_db", 0))
            distancia_km = float(dados.get("distancia_km", 1))
            frequencia_mhz = float(dados.get("frequencia_mhz", 1000))
            largura_hz = float(dados.get("largura_hz", 1e6))
            figura_ruido = float(dados.get("figura_ruido_db", 0))

            if (
                distancia_km <= 0
                or frequencia_mhz <= 0
                or largura_hz <= 0
            ):
                return {"erro": "Distância, frequência e largura devem ser positivas."}

            fspl = (
                32.44
                + 20*math.log10(distancia_km)
                + 20*math.log10(frequencia_mhz)
            )
            recebido = pt+gt+gr-fspl-perdas
            ruido = (
                -174
                + 10*math.log10(largura_hz)
                + figura_ruido
            )
            snr_db = recebido-ruido
            snr_linear = 10**(snr_db/10)
            capacidade = largura_hz*math.log2(1+snr_linear)

            return {
                "tipo": "orçamento de enlace de telecomunicações",
                "dados": dados,
                "pedido": "Calcular potência recebida, SNR e limite de Shannon",
                "formula": (
                    "FSPL=32,44+20log d_km+20log f_MHz; "
                    "C=B log₂(1+SNR)"
                ),
                "passos": [
                    f"FSPL={fspl} dB.",
                    f"P_rx={recebido} dBm.",
                    f"Ruído térmico efetivo={ruido} dBm.",
                    f"SNR={snr_db} dB={snr_linear} linear.",
                    f"Capacidade ideal={capacidade} bit/s.",
                ],
                "resultado": {
                    "FSPL_dB": fspl,
                    "potência_recebida_dBm": recebido,
                    "ruído_dBm": ruido,
                    "SNR_dB": snr_db,
                    "capacidade_Shannon_bit_s": capacidade,
                    "eficiência_espectral_ideal": math.log2(1+snr_linear),
                },
                "verificacao": (
                    "O cálculo usa propagação em espaço livre e ruído térmico "
                    "de referência −174 dBm/Hz."
                ),
                "observacao": (
                    "Sistemas 5G reais incluem fading, interferência, MIMO, "
                    "codificação, overhead e regulamentação não modelados aqui."
                ),
            }

        fibra = re.fullmatch(
            r"telecom\s+fibra\s+(.+)",
            texto,
        )

        if not fibra:
            return None

        try:
            dados = ParserInformacaoCodigosPSF.literal(
                fibra.group(1),
                "enlace de fibra",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        comprimento = float(dados.get("comprimento_km", 0))
        atenuacao = float(dados.get("atenuacao_db_km", 0.2))
        conectores = float(dados.get("perdas_conectores_db", 0))
        emendas = float(dados.get("perdas_emendas_db", 0))
        margem = float(dados.get("margem_db", 0))
        potencia_tx = float(dados.get("potencia_tx_dbm", 0))
        sensibilidade = float(dados.get("sensibilidade_rx_dbm", -20))
        dispersao = float(dados.get("dispersao_ps_nm_km", 0))
        largura_espectral = float(dados.get("largura_espectral_nm", 0))

        if comprimento < 0 or atenuacao < 0:
            return {"erro": "Comprimento e atenuação não podem ser negativos."}

        perda_total = (
            comprimento*atenuacao
            + conectores
            + emendas
            + margem
        )
        potencia_rx = potencia_tx-perda_total
        margem_final = potencia_rx-sensibilidade
        alargamento_ps = (
            abs(dispersao)*largura_espectral*comprimento
        )

        return {
            "tipo": "enlace de fibra óptica",
            "dados": dados,
            "pedido": "Calcular perdas, potência recebida e dispersão cromática",
            "formula": (
                "L_total=αL+L_conectores+L_emendas+margem; "
                "ΔT=|D|ΔλL"
            ),
            "passos": [
                f"Perda na fibra={comprimento}×{atenuacao}="
                f"{comprimento*atenuacao} dB.",
                f"Perda total={perda_total} dB.",
                f"Potência recebida={potencia_rx} dBm.",
                f"Margem sobre sensibilidade={margem_final} dB.",
                f"Alargamento temporal={alargamento_ps} ps.",
            ],
            "resultado": {
                "perda_total_dB": perda_total,
                "potência_recebida_dBm": potencia_rx,
                "margem_final_dB": margem_final,
                "enlace_viável_por_potência": margem_final >= 0,
                "alargamento_cromático_ps": alargamento_ps,
            },
            "verificacao": (
                "A viabilidade indicada considera apenas o orçamento de potência."
            ),
        }



class ParserBiomatematicaPSF:
    """Dados seguros para modelos biológicos e redes discretas."""

    @staticmethod
    def literal(texto, nome="dados"):
        try:
            return ast.literal_eval(texto.strip())
        except (ValueError, SyntaxError) as erro:
            raise ValueError(f"{nome.capitalize()} inválidos.") from erro

    @classmethod
    def matriz_distancias(cls, texto):
        dados = cls.literal(texto, "matriz de distâncias")

        try:
            matriz = np.asarray(dados, dtype=float)
        except (TypeError, ValueError) as erro:
            raise ValueError("A matriz de distâncias deve ser numérica.") from erro

        if matriz.ndim != 2 or matriz.shape[0] != matriz.shape[1]:
            raise ValueError("A matriz de distâncias deve ser quadrada.")
        if np.any(matriz < 0):
            raise ValueError("Distâncias não podem ser negativas.")
        if not np.allclose(matriz, matriz.T, atol=1e-10):
            raise ValueError("A matriz deve ser simétrica.")
        if not np.allclose(np.diag(matriz), 0, atol=1e-10):
            raise ValueError("A diagonal deve ser zero.")

        return matriz

    @staticmethod
    def coordenadas(texto):
        dados = ParserBiomatematicaPSF.literal(
            texto,
            "coordenadas",
        )

        if not isinstance(dados, (list, tuple)):
            raise ValueError("Coordenadas devem formar uma lista.")

        try:
            pontos = [
                (int(p[0]), int(p[1]))
                for p in dados
            ]
        except (TypeError, ValueError, IndexError) as erro:
            raise ValueError("Cada coordenada deve ser um par inteiro.") from erro

        return pontos


class MotorModelosPopulacionaisPSF:
    """Modelos de Malthus e Verhulst com solução analítica."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        malthus = re.fullmatch(
            r"populacao\s+malthus\s+"
            r"([0-9.eE+-]+)\s+([+-]?[0-9.eE]+)\s+([0-9.eE+-]+)",
            texto,
        )

        if malthus:
            p0 = float(malthus.group(1))
            r = float(malthus.group(2))
            t = float(malthus.group(3))

            if p0 < 0 or t < 0:
                return {"erro": "P0 e t não podem ser negativos."}

            p = p0*math.exp(r*t)
            tempo_dobro = (
                math.log(2)/r
                if r > 0
                else None
            )
            meia_vida = (
                math.log(2)/(-r)
                if r < 0
                else None
            )

            return {
                "tipo": "modelo populacional de Malthus",
                "dados": {"P0": p0, "r": r, "t": t},
                "pedido": "Calcular a população sob crescimento proporcional",
                "formula": "P(t)=P0e^{rt}",
                "passos": [
                    f"rt={r}×{t}={r*t}.",
                    f"e^(rt)={math.exp(r*t)}.",
                    f"P(t)={p0}×{math.exp(r*t)}={p}.",
                ],
                "resultado": {
                    "P_t": p,
                    "tempo_dobro": tempo_dobro,
                    "meia_vida": meia_vida,
                },
                "verificacao": {
                    "derivada_em_t": r*p,
                    "r_vezes_P": r*p,
                },
            }

        verhulst = re.fullmatch(
            r"populacao\s+verhulst\s+"
            r"([0-9.eE+-]+)\s+([+-]?[0-9.eE]+)\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)",
            texto,
        )

        if not verhulst:
            return None

        p0 = float(verhulst.group(1))
        r = float(verhulst.group(2))
        k = float(verhulst.group(3))
        t = float(verhulst.group(4))

        if p0 <= 0 or k <= 0 or t < 0:
            return {"erro": "P0 e K devem ser positivos; t não negativo."}

        a = (k-p0)/p0
        denominador = 1+a*math.exp(-r*t)

        if denominador == 0:
            return {"erro": "A solução possui denominador zero no tempo pedido."}

        p = k/denominador
        derivada = r*p*(1-p/k)
        ponto_inflexao = k/2
        tempo_inflexao = (
            math.log(a)/r
            if a > 0 and r != 0
            else None
        )

        return {
            "tipo": "modelo logístico de Verhulst",
            "dados": {"P0": p0, "r": r, "K": k, "t": t},
            "pedido": "Calcular crescimento com capacidade de suporte",
            "formula": "P(t)=K/[1+((K−P0)/P0)e^{−rt}]",
            "passos": [
                f"A=(K−P0)/P0={a}.",
                f"Denominador=1+A e^(−rt)={denominador}.",
                f"P(t)={k}/{denominador}={p}.",
                f"P'(t)=rP(1−P/K)={derivada}.",
            ],
            "resultado": {
                "P_t": p,
                "taxa_instantânea": derivada,
                "população_inflexão": ponto_inflexao,
                "tempo_inflexão": tempo_inflexao,
            },
            "verificacao": {
                "entre_zero_e_K_para_crescimento_padrão": (
                    0 <= p <= k
                    if r >= 0 and p0 <= k
                    else None
                ),
            },
        }


class MotorPresaPredadorPSF:
    """Lotka–Volterra com equilíbrios, Jacobiano e primeira integral."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"presa\s+predador\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+(\d+)",
            texto,
        )

        if not padrao:
            return None

        alpha = float(padrao.group(1))
        beta = float(padrao.group(2))
        delta = float(padrao.group(3))
        gamma = float(padrao.group(4))
        x0 = float(padrao.group(5))
        y0 = float(padrao.group(6))
        tf = float(padrao.group(7))
        passos = int(padrao.group(8))

        if min(alpha, beta, delta, gamma, x0, y0, tf) <= 0:
            return {"erro": "Parâmetros, populações e tempo devem ser positivos."}
        if passos < 2 or passos > 1_000_000:
            return {"erro": "Passos deve estar entre 2 e 1000000."}

        equilibrio = np.asarray([
            gamma/delta,
            alpha/beta,
        ])
        jacobiano_equilibrio = np.asarray([
            [0, -beta*equilibrio[0]],
            [delta*equilibrio[1], 0],
        ])
        autovalores = np.linalg.eigvals(jacobiano_equilibrio)

        def sistema(_, estado):
            x, y = estado
            return [
                alpha*x-beta*x*y,
                delta*x*y-gamma*y,
            ]

        tempos = np.linspace(0, tf, passos)
        solução = scipy_solve_ivp(
            sistema,
            (0, tf),
            [x0, y0],
            t_eval=tempos,
            rtol=1e-9,
            atol=1e-11,
        )

        if not solução.success:
            return {"erro": solução.message}

        x, y = solução.y
        primeira_integral = (
            delta*x-gamma*np.log(x)
            + beta*y-alpha*np.log(y)
        )
        variação = float(
            np.max(primeira_integral)
            - np.min(primeira_integral)
        )

        return {
            "tipo": "modelo presa–predador Lotka–Volterra",
            "dados": {
                "alpha_beta_delta_gamma": [
                    alpha, beta, delta, gamma
                ],
                "estado_inicial": [x0, y0],
                "tempo_final": tf,
            },
            "pedido": "Calcular equilíbrio, linearização e trajetória",
            "formula": "x'=αx−βxy; y'=δxy−γy",
            "passos": [
                f"Equilíbrio positivo={equilibrio.tolist()}.",
                f"Jacobiano no equilíbrio={jacobiano_equilibrio.tolist()}.",
                f"Autovalores={autovalores.tolist()}.",
                f"Estado final={solução.y[:, -1].tolist()}.",
                f"Variação da primeira integral={variação}.",
            ],
            "resultado": {
                "equilíbrio": equilibrio.tolist(),
                "autovalores": [complex(v) for v in autovalores],
                "estado_final": solução.y[:, -1].tolist(),
                "mínimos": solução.y.min(axis=1).tolist(),
                "máximos": solução.y.max(axis=1).tolist(),
                "variação_primeira_integral": variação,
            },
            "verificacao": {
                "populações_positivas": bool(np.min(solução.y) > 0),
                "primeira_integral_aproximadamente_conservada": variação < 1e-5,
            },
        }


class MotorPropagacaoDoencasPSF:
    """Modelos SIR e SEIR com conservação populacional."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)

        seir = re.fullmatch(
            r"modelo\s+seir\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+(\d+)",
            texto,
        )

        if seir:
            beta = float(seir.group(1))
            sigma = float(seir.group(2))
            gamma = float(seir.group(3))
            inicial = np.asarray([
                float(seir.group(4)),
                float(seir.group(5)),
                float(seir.group(6)),
                float(seir.group(7)),
            ])
            tf = float(seir.group(8))
            passos = int(seir.group(9))

            if beta < 0 or sigma <= 0 or gamma <= 0:
                return {"erro": "β≥0, σ>0 e γ>0 são obrigatórios."}
            if np.any(inicial < 0) or inicial.sum() <= 0:
                return {"erro": "Compartimentos iniciais inválidos."}
            if tf <= 0 or passos < 2:
                return {"erro": "Tempo e passos inválidos."}

            n = float(inicial.sum())

            def sistema(_, estado):
                s, e, i, r = estado
                incidência = beta*s*i/n
                return [
                    -incidência,
                    incidência-sigma*e,
                    sigma*e-gamma*i,
                    gamma*i,
                ]

            tempos = np.linspace(0, tf, passos)
            solução = scipy_solve_ivp(
                sistema,
                (0, tf),
                inicial,
                t_eval=tempos,
                rtol=1e-9,
                atol=1e-11,
            )

            if not solução.success:
                return {"erro": solução.message}

            s, e, i, r = solução.y
            pico = int(np.argmax(i))
            r0 = beta/gamma
            conservação = np.sum(solução.y, axis=0)

            return {
                "tipo": "modelo epidemiológico SEIR",
                "dados": {
                    "beta_sigma_gamma": [beta, sigma, gamma],
                    "S0_E0_I0_R0": inicial.tolist(),
                    "população": n,
                },
                "pedido": "Simular suscetíveis, expostos, infeciosos e removidos",
                "formula": (
                    "S'=−βSI/N; E'=βSI/N−σE; "
                    "I'=σE−γI; R'=γI"
                ),
                "passos": [
                    f"R0 básico sem estrutura adicional=β/γ={r0}.",
                    f"Pico de I={i[pico]} em t={tempos[pico]}.",
                    f"Estado final={solução.y[:, -1].tolist()}.",
                ],
                "resultado": {
                    "R0": r0,
                    "pico_infeciosos": float(i[pico]),
                    "tempo_pico": float(tempos[pico]),
                    "estado_final": solução.y[:, -1].tolist(),
                    "trajetória": solução.y.T.tolist(),
                },
                "verificacao": {
                    "erro_máximo_conservação": float(
                        np.max(np.abs(conservação-n))
                    ),
                    "compartimentos_não_negativos": bool(
                        np.min(solução.y) >= -1e-7
                    ),
                },
            }

        sir = re.fullmatch(
            r"propagacao\s+sir\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+"
            r"([0-9.eE+-]+)\s*;\s*([0-9.eE+-]+)\s+(\d+)",
            texto,
        )

        if not sir:
            return None

        beta = float(sir.group(1))
        gamma = float(sir.group(2))
        s0 = float(sir.group(3))
        i0 = float(sir.group(4))
        r0_inicial = float(sir.group(5))
        tf = float(sir.group(6))
        passos = int(sir.group(7))

        n = s0+i0+r0_inicial

        if beta < 0 or gamma <= 0 or min(s0, i0, r0_inicial) < 0 or n <= 0:
            return {"erro": "Parâmetros e compartimentos inválidos."}

        def sistema(_, estado):
            s, i, r = estado
            incidencia = beta*s*i/n
            return [-incidencia, incidencia-gamma*i, gamma*i]

        tempos = np.linspace(0, tf, passos)
        solução = scipy_solve_ivp(
            sistema,
            (0, tf),
            [s0, i0, r0_inicial],
            t_eval=tempos,
            rtol=1e-9,
            atol=1e-11,
        )

        if not solução.success:
            return {"erro": solução.message}

        pico = int(np.argmax(solução.y[1]))

        return {
            "tipo": "modelo epidemiológico SIR",
            "dados": {
                "beta": beta,
                "gamma": gamma,
                "estado_inicial": [s0, i0, r0_inicial],
            },
            "pedido": "Simular a propagação SIR",
            "formula": "S'=−βSI/N; I'=βSI/N−γI; R'=γI",
            "passos": [
                f"R0=β/γ={beta/gamma}.",
                (
                    f"Pico de I={solução.y[1, pico]} "
                    f"em t={tempos[pico]}."
                ),
                f"Estado final={solução.y[:, -1].tolist()}.",
            ],
            "resultado": {
                "R0": beta/gamma,
                "pico_infetados": float(solução.y[1, pico]),
                "tempo_pico": float(tempos[pico]),
                "estado_final": solução.y[:, -1].tolist(),
            },
            "verificacao": {
                "erro_conservação": float(
                    np.max(
                        np.abs(
                            np.sum(solução.y, axis=0)-n
                        )
                    )
                ),
            },
        }


class MotorReacaoDifusaoPSF:
    """Sistema Gray–Scott bidimensional com diferenças finitas periódicas."""

    @staticmethod
    def laplaciano(matriz):
        return (
            -4*matriz
            + np.roll(matriz, 1, axis=0)
            + np.roll(matriz, -1, axis=0)
            + np.roll(matriz, 1, axis=1)
            + np.roll(matriz, -1, axis=1)
        )

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"reacao\s+difusao\s+gray\s+scott\s+"
            r"(\d+)\s+(\d+)\s*;\s*"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s+"
            r"([0-9.eE+-]+)\s+([0-9.eE+-]+)\s*;\s*"
            r"([0-9.eE+-]+)\s+(\d+)(?:\s*;\s*(\d+))?",
            texto,
        )

        if not padrao:
            return None

        linhas = int(padrao.group(1))
        colunas = int(padrao.group(2))
        du = float(padrao.group(3))
        dv = float(padrao.group(4))
        feed = float(padrao.group(5))
        kill = float(padrao.group(6))
        dt = float(padrao.group(7))
        passos = int(padrao.group(8))
        semente = int(padrao.group(9) or 0)

        if not (8 <= linhas <= 1000 and 8 <= colunas <= 1000):
            return {"erro": "Cada dimensão da grade deve estar entre 8 e 1000."}
        if min(du, dv, feed, kill, dt) < 0 or passos < 1 or passos > 1_000_000:
            return {"erro": "Parâmetros não negativos e passos positivos são exigidos."}
        if linhas*colunas*passos > 300_000_000:
            return {"erro": "O produto grade×passos é demasiado elevado."}

        rng = np.random.default_rng(semente)
        u = np.ones((linhas, colunas), dtype=float)
        v = np.zeros((linhas, colunas), dtype=float)
        l0, l1 = linhas//2-linhas//10, linhas//2+linhas//10
        c0, c1 = colunas//2-colunas//10, colunas//2+colunas//10
        u[l0:l1, c0:c1] = 0.5
        v[l0:l1, c0:c1] = 0.25
        u += 0.01*rng.standard_normal(u.shape)
        v += 0.01*rng.standard_normal(v.shape)
        histórico = []

        for passo in range(passos):
            uvv = u*v*v
            u += dt*(
                du*self.laplaciano(u)
                - uvv
                + feed*(1-u)
            )
            v += dt*(
                dv*self.laplaciano(v)
                + uvv
                - (feed+kill)*v
            )
            u = np.clip(u, 0, 1.5)
            v = np.clip(v, 0, 1.5)

            if passo < 20 or passo in {
                passos-1,
                max(0, passos//2),
            }:
                histórico.append({
                    "passo": passo+1,
                    "média_u": float(np.mean(u)),
                    "média_v": float(np.mean(v)),
                    "desvio_v": float(np.std(v)),
                })

        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "reacao_difusao_gray_scott.png"
        figura, eixo = plt.subplots(figsize=(7, 6))
        eixo.imshow(v, cmap="viridis")
        eixo.set_title("Padrão Gray–Scott: componente v")
        eixo.axis("off")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "equação de reação–difusão Gray–Scott",
            "dados": {
                "grade": [linhas, colunas],
                "Du_Dv": [du, dv],
                "feed_kill": [feed, kill],
                "dt": dt,
                "passos": passos,
                "semente": semente,
            },
            "pedido": "Simular difusão, reação e formação de padrões",
            "formula": (
                "u_t=Du∇²u−uv²+F(1−u); "
                "v_t=Dv∇²v+uv²−(F+k)v"
            ),
            "passos": [
                "Inicializamos uma perturbação central com ruído pequeno.",
                "Aplicamos Laplaciano periódico de cinco pontos.",
                "Atualizamos reação e difusão por Euler explícito.",
                f"Histórico={histórico}.",
            ],
            "resultado": {
                "u_final": u.tolist(),
                "v_final": v.tolist(),
                "média_v": float(np.mean(v)),
                "desvio_v": float(np.std(v)),
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "valores_finitos": bool(
                    np.isfinite(u).all() and np.isfinite(v).all()
                ),
                "padrão_não_uniforme": float(np.std(v)) > 1e-6,
            },
            "observacao": (
                "É uma simulação discreta. A estabilidade numérica depende "
                "de dt, difusões, grade e condições de contorno."
            ),
        }


class MotorFilogeneticaPSF:
    """Construção de árvore UPGMA a partir de distâncias."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"filogenetica\s+upgma\s+(.+?)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            rotulos = list(
                ParserBiomatematicaPSF.literal(
                    padrao.group(1),
                    "rótulos",
                )
            )
            distancias = ParserBiomatematicaPSF.matriz_distancias(
                padrao.group(2)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if len(rotulos) != len(distancias):
            return {"erro": "A quantidade de rótulos deve coincidir com a matriz."}
        if len(set(map(str, rotulos))) != len(rotulos):
            return {"erro": "Os rótulos devem ser distintos."}

        clusters = {
            i: {
                "membros": [i],
                "tamanho": 1,
                "altura": 0.0,
                "newick": str(rotulos[i]),
            }
            for i in range(len(rotulos))
        }
        d = {
            (i, j): float(distancias[i, j])
            for i in range(len(rotulos))
            for j in range(i+1, len(rotulos))
        }
        próximo = len(rotulos)
        fusões = []

        def obter(a, b):
            if a == b:
                return 0.0

            return d[tuple(sorted((a, b)))]

        while len(clusters) > 1:
            pares = [
                (obter(a, b), a, b)
                for a in clusters
                for b in clusters
                if a < b
            ]
            distância, a, b = min(
                pares,
                key=lambda item: (item[0], item[1], item[2]),
            )
            ca = clusters[a]
            cb = clusters[b]
            altura = distância/2
            ramo_a = altura-ca["altura"]
            ramo_b = altura-cb["altura"]
            novo_newick = (
                f"({ca['newick']}:{ramo_a:.12g},"
                f"{cb['newick']}:{ramo_b:.12g})"
            )
            novo = {
                "membros": ca["membros"]+cb["membros"],
                "tamanho": ca["tamanho"]+cb["tamanho"],
                "altura": altura,
                "newick": novo_newick,
            }
            outras = [
                c
                for c in clusters
                if c not in (a, b)
            ]

            for c in outras:
                distância_nova = (
                    ca["tamanho"]*obter(a, c)
                    + cb["tamanho"]*obter(b, c)
                )/novo["tamanho"]
                d[tuple(sorted((próximo, c)))] = distância_nova

            fusões.append({
                "clusters": [
                    [rotulos[i] for i in ca["membros"]],
                    [rotulos[i] for i in cb["membros"]],
                ],
                "distância": distância,
                "altura": altura,
                "novo": [
                    rotulos[i]
                    for i in novo["membros"]
                ],
            })
            del clusters[a]
            del clusters[b]
            clusters[próximo] = novo

            for chave in list(d):
                if a in chave or b in chave:
                    del d[chave]

            próximo += 1

        raiz = next(iter(clusters.values()))
        newick = raiz["newick"]+";"

        return {
            "tipo": "filogenética por UPGMA",
            "dados": {
                "rótulos": rotulos,
                "distâncias": distancias.tolist(),
            },
            "pedido": "Construir uma árvore ultramétrica por médias de grupos",
            "formula": (
                "d(A∪B,C)=(|A|d(A,C)+|B|d(B,C))/(|A|+|B|)"
            ),
            "passos": [
                f"Fusões sucessivas={fusões}.",
                f"Newick={newick}.",
            ],
            "resultado": {
                "newick": newick,
                "fusões": fusões,
                "altura_raiz": raiz["altura"],
            },
            "verificacao": (
                "Cada nova distância foi ponderada pelo tamanho dos clusters."
            ),
            "observacao": (
                "UPGMA pressupõe relógio molecular/ultrametricidade; se a "
                "hipótese falhar, a árvore pode não representar corretamente "
                "as taxas evolutivas."
            ),
        }


class MotorSmithWatermanPSF:
    """Alinhamento local de duas sequências."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"smith\s+waterman\s+(\S+)\s+(\S+)"
            r"(?:\s*;\s*([+-]?\d+)\s+([+-]?\d+)\s+([+-]?\d+))?",
            texto,
        )

        if not padrao:
            return None

        seq1 = padrao.group(1).upper()
        seq2 = padrao.group(2).upper()
        match = int(padrao.group(3) or 2)
        mismatch = int(padrao.group(4) or -1)
        gap = int(padrao.group(5) or -2)

        if not seq1 or not seq2:
            return {"erro": "As sequências não podem ser vazias."}
        if len(seq1)*len(seq2) > 10_000_000:
            return {"erro": "O produto dos comprimentos é demasiado elevado."}

        h = np.zeros(
            (len(seq1)+1, len(seq2)+1),
            dtype=int,
        )
        ponteiro = np.zeros_like(h, dtype=np.uint8)
        melhor = (0, 0, 0)

        for i in range(1, len(seq1)+1):
            for j in range(1, len(seq2)+1):
                diagonal = h[i-1, j-1]+(
                    match
                    if seq1[i-1] == seq2[j-1]
                    else mismatch
                )
                cima = h[i-1, j]+gap
                esquerda = h[i, j-1]+gap
                valores = [0, diagonal, cima, esquerda]
                escolha = int(np.argmax(valores))
                h[i, j] = valores[escolha]
                ponteiro[i, j] = escolha

                if h[i, j] > melhor[0]:
                    melhor = (int(h[i, j]), i, j)

        pontuação, i, j = melhor
        alinhado1 = []
        alinhado2 = []
        caminho = []

        while i > 0 and j > 0 and h[i, j] > 0:
            direção = int(ponteiro[i, j])
            caminho.append((i, j, int(h[i, j])))

            if direção == 1:
                alinhado1.append(seq1[i-1])
                alinhado2.append(seq2[j-1])
                i -= 1
                j -= 1
            elif direção == 2:
                alinhado1.append(seq1[i-1])
                alinhado2.append("-")
                i -= 1
            elif direção == 3:
                alinhado1.append("-")
                alinhado2.append(seq2[j-1])
                j -= 1
            else:
                break

        alinhado1 = "".join(reversed(alinhado1))
        alinhado2 = "".join(reversed(alinhado2))
        identidade = sum(
            a == b
            for a, b in zip(alinhado1, alinhado2)
            if a != "-" and b != "-"
        )
        comprimento = len(alinhado1)

        return {
            "tipo": "alinhamento local Smith–Waterman",
            "dados": {
                "sequência_1": seq1,
                "sequência_2": seq2,
                "match_mismatch_gap": [match, mismatch, gap],
            },
            "pedido": "Encontrar o alinhamento local de maior pontuação",
            "formula": (
                "H_ij=max(0,H_{i−1,j−1}+s,H_{i−1,j}+g,H_{i,j−1}+g)"
            ),
            "passos": [
                f"Matriz de pontuações={h.tolist()}.",
                f"Máximo={pontuação} na posição {melhor[1:]}.",
                f"Caminho de traceback={caminho}.",
            ],
            "resultado": {
                "pontuação": pontuação,
                "alinhamento_1": alinhado1,
                "alinhamento_2": alinhado2,
                "identidades": identidade,
                "comprimento_alinhamento": comprimento,
                "fração_identidade": (
                    identidade/comprimento
                    if comprimento
                    else 0.0
                ),
            },
            "verificacao": (
                "O traceback termina numa célula de valor zero."
            ),
        }


class MotorDobramentoProteinasPSF:
    """Energia do modelo hidrofóbico-polar numa rede quadrada."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"proteina\s+hp\s+([hp]+)\s*;\s*(.+)",
            texto,
        )

        if not padrao:
            return None

        sequencia = padrao.group(1).upper()

        try:
            coordenadas = ParserBiomatematicaPSF.coordenadas(
                padrao.group(2)
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if len(coordenadas) != len(sequencia):
            return {"erro": "Deve existir uma coordenada por resíduo."}

        auto_evitante = len(set(coordenadas)) == len(coordenadas)
        ligações_cadeia = [
            abs(coordenadas[i+1][0]-coordenadas[i][0])
            + abs(coordenadas[i+1][1]-coordenadas[i][1])
            for i in range(len(coordenadas)-1)
        ]
        cadeia_válida = all(distância == 1 for distância in ligações_cadeia)
        contatos = []

        for i in range(len(sequencia)):
            if sequencia[i] != "H":
                continue

            for j in range(i+2, len(sequencia)):
                if sequencia[j] != "H":
                    continue

                distância = (
                    abs(coordenadas[i][0]-coordenadas[j][0])
                    + abs(coordenadas[i][1]-coordenadas[j][1])
                )

                if distância == 1:
                    contatos.append((i, j))

        energia = -len(contatos)
        ótimo_global = "não determinado"

        return {
            "tipo": "modelo HP de dobramento de proteína",
            "dados": {
                "sequência": sequencia,
                "coordenadas": coordenadas,
            },
            "pedido": "Validar a conformação e calcular contatos H–H",
            "formula": "E=− número de contatos H–H não consecutivos",
            "passos": [
                f"Auto-evitante={auto_evitante}.",
                f"Distâncias entre resíduos consecutivos={ligações_cadeia}.",
                f"Contatos H–H não covalentes={contatos}.",
                f"E={energia}.",
            ],
            "resultado": {
                "conformação_válida": auto_evitante and cadeia_válida,
                "energia_HP": energia,
                "contatos": contatos,
                "ótimo_global_de_dobramento": ótimo_global,
            },
            "verificacao": {
                "sem_sobreposição": auto_evitante,
                "cadeia_conectada": cadeia_válida,
            },
            "justificacao": (
                "A energia foi calculada para a conformação fornecida. "
                "Determinar se ela é globalmente ótima exige comparar com "
                "todas as conformações auto-evitantes admissíveis, problema "
                "combinatório não resolvido por esta avaliação única."
            ),
            "observacao": (
                "O modelo HP é uma simplificação em rede; não representa toda "
                "a física do dobramento proteico real."
            ),
        }


class AvaliadorBooleanoGenesPSF:
    """Avaliador AST limitado para regras booleanas."""

    @classmethod
    def avaliar(cls, expressão, ambiente):
        arvore = ast.parse(
            expressão,
            mode="eval",
        )
        return bool(cls._no(arvore.body, ambiente))

    @classmethod
    def _no(cls, no, ambiente):
        if isinstance(no, ast.Name):
            if no.id not in ambiente:
                raise ValueError(f"Gene desconhecido: {no.id}.")

            return bool(ambiente[no.id])

        if isinstance(no, ast.Constant) and isinstance(no.value, bool):
            return no.value

        if isinstance(no, ast.UnaryOp) and isinstance(no.op, ast.Not):
            return not cls._no(no.operand, ambiente)

        if isinstance(no, ast.BoolOp):
            valores = [
                cls._no(valor, ambiente)
                for valor in no.values
            ]

            if isinstance(no.op, ast.And):
                return all(valores)
            if isinstance(no.op, ast.Or):
                return any(valores)

        if isinstance(no, ast.BinOp) and isinstance(no.op, ast.BitXor):
            return bool(
                cls._no(no.left, ambiente)
                ^ cls._no(no.right, ambiente)
            )

        if isinstance(no, ast.Compare) and len(no.ops) == 1:
            esquerda = cls._no(no.left, ambiente)
            direita = cls._no(no.comparators[0], ambiente)

            if isinstance(no.ops[0], ast.Eq):
                return esquerda == direita
            if isinstance(no.ops[0], ast.NotEq):
                return esquerda != direita

        raise ValueError("Regra booleana contém operação não permitida.")


class MotorRedesGenicasBooleanasPSF:
    """Simulação síncrona e procura de atratores booleanos."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"rede\s+genica\s+booleana\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserBiomatematicaPSF.literal(
                padrao.group(1),
                "rede booleana",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {"erro": "Forneça um dicionário com regras e estado inicial."}

        regras = dados.get("regras")
        inicial = dados.get("inicial")

        if not isinstance(regras, dict) or not regras:
            return {"erro": "As regras devem formar um dicionário não vazio."}

        genes = list(regras.keys())

        if not all(
            re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", str(gene))
            for gene in genes
        ):
            return {"erro": "Nomes de genes inválidos."}

        if isinstance(inicial, dict):
            estado = {
                gene: bool(inicial.get(gene, False))
                for gene in genes
            }
        elif isinstance(inicial, (list, tuple)):
            if len(inicial) != len(genes):
                return {"erro": "O estado inicial deve ter um valor por gene."}

            estado = {
                gene: bool(valor)
                for gene, valor in zip(genes, inicial)
            }
        else:
            return {"erro": "Estado inicial deve ser lista ou dicionário."}

        max_passos = int(dados.get("passos", 1000))

        if max_passos < 1 or max_passos > 1_000_000:
            return {"erro": "passos deve estar entre 1 e 1000000."}

        vistos = {}
        trajetória = []
        atual = estado

        try:
            for passo in range(max_passos+1):
                chave = tuple(int(atual[gene]) for gene in genes)

                if chave in vistos:
                    início_ciclo = vistos[chave]
                    atrator = trajetória[início_ciclo:]
                    transiente = trajetória[:início_ciclo]
                    convergiu = True
                    break

                vistos[chave] = len(trajetória)
                trajetória.append(chave)
                próximo = {
                    gene: AvaliadorBooleanoGenesPSF.avaliar(
                        str(regras[gene]),
                        atual,
                    )
                    for gene in genes
                }
                atual = próximo
            else:
                convergiu = False
                atrator = []
                transiente = trajetória
        except ValueError as erro:
            return {"erro": str(erro)}

        todos_atratores = None

        if len(genes) <= 18 and bool(dados.get("enumerar", False)):
            atratores_chaves = set()

            for bits in itertools.product((False, True), repeat=len(genes)):
                estado_local = dict(zip(genes, bits))
                vistos_local = {}
                seq = []

                for _ in range(2**len(genes)+1):
                    chave = tuple(
                        int(estado_local[gene])
                        for gene in genes
                    )

                    if chave in vistos_local:
                        ciclo = seq[vistos_local[chave]:]
                        rotações = [
                            tuple(ciclo[i:]+ciclo[:i])
                            for i in range(len(ciclo))
                        ]
                        atratores_chaves.add(min(rotações))
                        break

                    vistos_local[chave] = len(seq)
                    seq.append(chave)
                    estado_local = {
                        gene: AvaliadorBooleanoGenesPSF.avaliar(
                            str(regras[gene]),
                            estado_local,
                        )
                        for gene in genes
                    }

            todos_atratores = [
                list(ciclo)
                for ciclo in sorted(atratores_chaves)
            ]

        return {
            "tipo": "rede reguladora gênica booleana",
            "dados": {
                "genes": genes,
                "regras": regras,
                "inicial": estado,
            },
            "pedido": "Iterar a rede e identificar atratores",
            "formula": "x_i(t+1)=F_i(x_1(t),...,x_n(t))",
            "passos": [
                f"Trajetória={trajetória}.",
                f"Transiente={transiente}.",
                f"Atrator={atrator}.",
                f"Enumeração global={todos_atratores}.",
            ],
            "resultado": {
                "convergiu_para_ciclo": convergiu,
                "transiente": transiente,
                "atrator": atrator,
                "período": len(atrator),
                "todos_atratores_enumerados": todos_atratores,
            },
            "verificacao": (
                "O estado posterior ao último elemento do atrator retorna ao primeiro."
                if convergiu
                else "O limite de passos foi atingido."
            ),
            "justificacao": (
                "A trajetória não repetiu um estado dentro do limite fornecido. "
                "Como o espaço é finito, uma repetição ocorrerá eventualmente, "
                "mas o atrator permanece não determinado sem aumentar o limite."
                if not convergiu
                else None
            ),
        }


class MotorHodgkinHuxleyPSF:
    """Modelo clássico de Hodgkin–Huxley para potencial de membrana."""

    @staticmethod
    def vtrap(x, y):
        if abs(x/y) < 1e-6:
            return y*(1-x/(2*y))

        return x/(math.exp(x/y)-1)

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"hodgkin\s+huxley\s+"
            r"([+-]?[0-9.eE]+)\s+([0-9.eE+-]+)\s+"
            r"([0-9.eE+-]+)\s+(\d+)"
            r"(?:\s*;\s*([+-]?[0-9.eE]+))?",
            texto,
        )

        if not padrao:
            return None

        corrente = float(padrao.group(1))
        inicio_corrente = float(padrao.group(2))
        tf = float(padrao.group(3))
        passos = int(padrao.group(4))
        v0 = float(padrao.group(5) or -65.0)

        if tf <= 0:
            return {"erro": "O tempo final deve ser positivo."}

        if inicio_corrente < 0 or inicio_corrente > tf:
            return {"erro": "O início da corrente deve pertencer ao intervalo."}
        if passos < 10 or passos > 1_000_000:
            return {"erro": "passos deve estar entre 10 e 1000000."}

        cm = 1.0
        gna = 120.0
        gk = 36.0
        gl = 0.3
        ena = 50.0
        ek = -77.0
        el = -54.387

        def taxas(v):
            alpha_n = 0.01*self.vtrap(-(v+55), 10)
            beta_n = 0.125*math.exp(-(v+65)/80)
            alpha_m = 0.1*self.vtrap(-(v+40), 10)
            beta_m = 4*math.exp(-(v+65)/18)
            alpha_h = 0.07*math.exp(-(v+65)/20)
            beta_h = 1/(math.exp(-(v+35)/10)+1)
            return alpha_n, beta_n, alpha_m, beta_m, alpha_h, beta_h

        an, bn, am, bm, ah, bh = taxas(v0)
        n0 = an/(an+bn)
        m0 = am/(am+bm)
        h0 = ah/(ah+bh)

        def sistema(t, estado):
            v, n, m, h = estado
            an, bn, am, bm, ah, bh = taxas(v)
            ina = gna*m**3*h*(v-ena)
            ik = gk*n**4*(v-ek)
            il = gl*(v-el)
            i_ext = corrente if t >= inicio_corrente else 0.0
            dv = (i_ext-ina-ik-il)/cm
            return [
                dv,
                an*(1-n)-bn*n,
                am*(1-m)-bm*m,
                ah*(1-h)-bh*h,
            ]

        tempos = np.linspace(0, tf, passos)
        solução = scipy_solve_ivp(
            sistema,
            (0, tf),
            [v0, n0, m0, h0],
            t_eval=tempos,
            rtol=1e-7,
            atol=1e-9,
            max_step=max(tf/passos*5, 0.01),
        )

        if not solução.success:
            return {"erro": solução.message}

        v = solução.y[0]
        limiar = 0.0
        cruzamentos = np.where(
            (v[:-1] < limiar)
            & (v[1:] >= limiar)
        )[0]
        tempos_disparos = solução.t[cruzamentos+1].tolist()
        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "hodgkin_huxley.png"
        figura, eixo = plt.subplots(figsize=(9, 5))
        eixo.plot(solução.t, v)
        eixo.axvline(inicio_corrente, linestyle="--")
        eixo.set_xlabel("tempo (ms)")
        eixo.set_ylabel("V (mV)")
        eixo.set_title("Modelo Hodgkin–Huxley")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "modelo de Hodgkin–Huxley",
            "dados": {
                "corrente_uA_cm2": corrente,
                "início_corrente_ms": inicio_corrente,
                "V0_mV": v0,
                "tempo_final_ms": tf,
            },
            "pedido": "Integrar o potencial e as portas iônicas",
            "formula": (
                "C_mV'=I−g_Nam³h(V−E_Na)−g_Kn⁴(V−E_K)−g_L(V−E_L)"
            ),
            "passos": [
                f"Condições estacionárias iniciais n,m,h={[n0,m0,h0]}.",
                f"Máximo V={float(np.max(v))} mV.",
                f"Mínimo V={float(np.min(v))} mV.",
                f"Cruzamentos ascendentes de 0 mV={tempos_disparos}.",
            ],
            "resultado": {
                "V_final_mV": float(v[-1]),
                "V_máximo_mV": float(np.max(v)),
                "V_mínimo_mV": float(np.min(v)),
                "número_disparos_aproximado": len(tempos_disparos),
                "tempos_disparos_ms": tempos_disparos,
                "estado_final": solução.y[:, -1].tolist(),
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "portas_entre_zero_um": bool(
                    np.min(solução.y[1:]) >= -1e-6
                    and np.max(solução.y[1:]) <= 1+1e-6
                ),
                "integração_concluída": bool(solução.success),
            },
            "observacao": (
                "Os parâmetros são os valores clássicos do axônio gigante "
                "de lula e não representam automaticamente qualquer neurônio."
            ),
        }


class MotorLSystemsPSF:
    """Expansão de sistemas de Lindenmayer e geometria turtle."""

    def calcular(self, entrada):
        texto = normalizar_texto(entrada)
        padrao = re.fullmatch(
            r"l\s*system\s+(.+)",
            texto,
        )

        if not padrao:
            return None

        try:
            dados = ParserBiomatematicaPSF.literal(
                padrao.group(1),
                "L-system",
            )
        except ValueError as erro:
            return {"erro": str(erro)}

        if not isinstance(dados, dict):
            return {"erro": "Forneça um dicionário com axioma e regras."}

        axioma = str(dados.get("axioma", ""))
        regras = {
            str(chave): str(valor)
            for chave, valor in dict(dados.get("regras", {})).items()
        }
        iterações = int(dados.get("iteracoes", dados.get("iterações", 0)))
        ângulo = math.radians(float(dados.get("angulo", 90)))
        passo = float(dados.get("passo", 1.0))

        if not axioma:
            return {"erro": "O axioma não pode ser vazio."}
        if iterações < 0 or iterações > 30:
            return {"erro": "Iterações deve estar entre 0 e 30."}
        if passo <= 0:
            return {"erro": "O passo deve ser positivo."}

        palavra = axioma
        comprimentos = [len(palavra)]

        for _ in range(iterações):
            palavra = "".join(
                regras.get(simbolo, simbolo)
                for simbolo in palavra
            )
            comprimentos.append(len(palavra))

            if len(palavra) > 2_000_000:
                return {
                    "erro": (
                        "A expansão ultrapassou 2 milhões de símbolos."
                    )
                }

        x = y = 0.0
        direção = math.radians(float(dados.get("direcao_inicial", 0)))
        pilha = []
        segmentos = []
        min_x = max_x = x
        min_y = max_y = y

        for simbolo in palavra:
            if simbolo in ("F", "G"):
                novo_x = x+passo*math.cos(direção)
                novo_y = y+passo*math.sin(direção)
                segmentos.append(((x, y), (novo_x, novo_y)))
                x, y = novo_x, novo_y
            elif simbolo == "f":
                x += passo*math.cos(direção)
                y += passo*math.sin(direção)
            elif simbolo == "+":
                direção += ângulo
            elif simbolo == "-":
                direção -= ângulo
            elif simbolo == "[":
                pilha.append((x, y, direção))
            elif simbolo == "]":
                if not pilha:
                    return {"erro": "Colchete ] sem [ correspondente."}

                x, y, direção = pilha.pop()

            min_x = min(min_x, x)
            max_x = max(max_x, x)
            min_y = min(min_y, y)
            max_y = max(max_y, y)

        if pilha:
            return {"erro": "Existem colchetes [ não fechados."}

        diretorio = Path.cwd() / "graficos_psf"
        diretorio.mkdir(parents=True, exist_ok=True)
        caminho = diretorio / "l_system.png"
        figura, eixo = plt.subplots(figsize=(8, 8))

        for início, fim in segmentos:
            eixo.plot(
                [início[0], fim[0]],
                [início[1], fim[1]],
                linewidth=0.8,
            )

        eixo.set_aspect("equal", adjustable="box")
        eixo.axis("off")
        eixo.set_title("L-system")
        figura.tight_layout()
        figura.savefig(caminho, dpi=180)
        plt.close(figura)

        return {
            "tipo": "sistema de Lindenmayer",
            "dados": {
                "axioma": axioma,
                "regras": regras,
                "iterações": iterações,
                "ângulo_graus": math.degrees(ângulo),
                "passo": passo,
            },
            "pedido": "Expandir a gramática e interpretar a geometria",
            "formula": "w_{n+1}=produção aplicada em paralelo a cada símbolo de w_n",
            "passos": [
                f"Comprimentos por iteração={comprimentos}.",
                f"Palavra final={palavra if len(palavra) <= 10000 else palavra[:10000]+'...'}",
                f"Segmentos desenhados={len(segmentos)}.",
                f"Caixa envolvente={[min_x, min_y, max_x, max_y]}.",
            ],
            "resultado": {
                "palavra_final": (
                    palavra
                    if len(palavra) <= 100000
                    else palavra[:100000]+"..."
                ),
                "comprimento_final": len(palavra),
                "segmentos": segmentos[:100000],
                "quantidade_segmentos": len(segmentos),
                "caixa_envolvente": [min_x, min_y, max_x, max_y],
                "gráfico": str(caminho.resolve()),
            },
            "verificacao": {
                "pilha_balanceada": not pilha,
                "coordenadas_finitas": all(
                    math.isfinite(valor)
                    for valor in (min_x, min_y, max_x, max_y)
                ),
            },
        }


